INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文献", "is_correct": true, "explanation": "正确：“记录了村子几百年的变化”的主语是文献，指记录历史的文字材料，语义相合。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不能记录村子的历史变化。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟只用来报时，无法记录村子几百年的变化。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：“记录”的对象是变化、事件等，不与“手套”搭配。"}], "explanations": {"文献": "正确：“记录了村子几百年的变化”的主语是文献，指记录历史的文字材料，语义相合。", "饺子": "语义：饺子是食物，不能记录村子的历史变化。", "闹钟": "语义：闹钟只用来报时，无法记录村子几百年的变化。", "手套": "搭配：“记录”的对象是变化、事件等，不与“手套”搭配。"}, "sentence_index": 6, "correct_answer": "文献"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件文献是用青铜做的，很重。", "explanation": "这里应该用〈文物〉。青铜器是实物，文献是文字资料，不能用青铜制成。"}, {"text": "妈妈给宝宝买了这份文献，宝宝很喜欢玩。", "explanation": "这里应该用〈玩具〉。文献是学术或历史资料，不是玩具；给宝宝玩的是玩具。"}, {"text": "这篇文献的幽默让人发笑。", "explanation": "这里应该用〈文章〉。形容幽默、令人发笑的是文章；文献重在资料价值。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份文献我读了过。", "corrected_sentence": "这份文献我读过了。", "error_description": "体标错误：“过”和“了”的顺序颠倒，“读过了”表示已经读过，不说“读了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经找了到这些文献。", "corrected_sentence": "我已经找到了这些文献。", "error_description": "补语位置错误：“找到”是结果补语，“了”应放在“到”之后，说“找到了”，不说“找了到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
