INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20918, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你心里知道自己在想什么、做什么，这就是意识。", "primary_collocate": null, "pronunciation": "yì shí", "ipa": "i˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "孩子要有安全意识。", "target_word": "意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的环保意识很强。", "target_word": "意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对自己的不良习惯缺乏意识。", "target_word": "意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要提高节约用水的意识。", "target_word": "意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人的自我保护意识需要加强。", "target_word": "意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望学生有主动学习的意识。", "target_word": "意识", "complexity_tier": "T3", "furigana": "lǎo shī xī wàng xué shēng yǒu zhǔ dòng xué xí de yì shí", "sentence_source": "generated"}, {"text": "这位爷爷的健康意识很好。", "target_word": "意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要有服务意识。", "target_word": "意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该培养孩子的理财意识。", "target_word": "意识", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的法律意识越来越强。", "target_word": "意识", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "安全意识", "label": "复合"}, {"form": "环保意识", "label": "复合"}], "register": "中性", "sense_fingerprint": "人心里对自己和周围事情的认识与感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3365f9ac-881d-493f-88dc-1a13db791d52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20918, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "意识", "is_correct": true, "explanation": "正确答案。意识（yì shí）指人心里对自己和周围事情的认识与感觉。"}, {"text": "衣食", "is_correct": false, "explanation": "第一个音节 yī（第一声）与 yì（第四声）声调不同，意思是衣服和食物。"}, {"text": "一时", "is_correct": false, "explanation": "第一个音节 yī（第一声）与 yì（第四声）声调不同，意思是一段时间。"}, {"text": "议事", "is_correct": false, "explanation": "第二个音节 shì（第四声）与 shí（第二声）声调不同，意思是商量事情。"}, {"text": "意思", "is_correct": false, "explanation": "第二个音节 sī（第一声）与 shí 声母不同（s 与 sh），意思是意义或心意。"}], "explanations": {"意识": "正确答案。意识（yì shí）指人心里对自己和周围事情的认识与感觉。", "衣食": "第一个音节 yī（第一声）与 yì（第四声）声调不同，意思是衣服和食物。", "一时": "第一个音节 yī（第一声）与 yì（第四声）声调不同，意思是一段时间。", "议事": "第二个音节 shì（第四声）与 shí（第二声）声调不同，意思是商量事情。", "意思": "第二个音节 sī（第一声）与 shí 声母不同（s 与 sh），意思是意义或心意。"}, "sentence_index": null, "correct_answer": "意识"}, "level_3": {"options": [{"text": "意识", "is_correct": true, "explanation": "“安全意识”指对安全的觉察与重视，与“有”搭配自然，句子通顺。"}, {"text": "兴趣", "is_correct": false, "explanation": "搭配：“兴趣”指对事物的喜好，不说“安全兴趣”，句子不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是气象状况，与“安全”无关，“孩子要有安全天气”句意荒谬。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”一般不与“安全”搭配，不说“安全性格”，句子不通。"}], "explanations": {"意识": "“安全意识”指对安全的觉察与重视，与“有”搭配自然，句子通顺。", "兴趣": "搭配：“兴趣”指对事物的喜好，不说“安全兴趣”，句子不通。", "天气": "语义：“天气”是气象状况，与“安全”无关，“孩子要有安全天气”句意荒谬。", "性格": "搭配：“性格”一般不与“安全”搭配，不说“安全性格”，句子不通。"}, "sentence_index": 0, "correct_answer": "意识"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一听到下课铃，意识就跑出了教室。", "explanation": "这里应该去掉〈意识〉。“意识”是心里的觉察，不能做出“跑出教室”的动作，应说“他一听到下课铃，就跑出了教室”。"}, {"text": "他对节约用水有一颗意识。", "explanation": "这里量词应该用〈种〉（一种意识）。“颗”用于粒状的小东西，不能用来数“意识”。"}, {"text": "我们把环保意识吃掉了一半。", "explanation": "这里应该用〈增强〉。“吃掉”不能用于意识，应说“增强环保意识”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20918, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "意识", "is_correct": true, "explanation": "正确答案。意识（yì shí）指人心里对自己和周围事情的认识与感觉。"}, {"text": "医师", "is_correct": false, "explanation": "两个音节声调都不同：yī（第一声）与 yì，shī（第一声）与 shí，意思是医生。"}, {"text": "一世", "is_correct": false, "explanation": "第一个音节 yī（第一声）与 yì 声调不同，第二个音节 shì（第四声）与 shí 声调不同，意思是一生。"}, {"text": "一事", "is_correct": false, "explanation": "第一个音节 yī（第一声）与 yì 声调不同，第二个音节 shì（第四声）与 shí 声调不同，意思是一件事。"}], "explanations": {"意识": "正确答案。意识（yì shí）指人心里对自己和周围事情的认识与感觉。", "医师": "两个音节声调都不同：yī（第一声）与 yì，shī（第一声）与 shí，意思是医生。", "一世": "第一个音节 yī（第一声）与 yì 声调不同，第二个音节 shì（第四声）与 shí 声调不同，意思是一生。", "一事": "第一个音节 yī（第一声）与 yì 声调不同，第二个音节 shì（第四声）与 shí 声调不同，意思是一件事。"}, "sentence_index": null, "correct_answer": "意识"}, "level_3": {"options": [{"text": "意识", "is_correct": true, "explanation": "“健康意识”指对健康的重视与觉察，与“很好”搭配，句意通顺。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”指性情，不说“健康脾气”，句子不通。"}, {"text": "手艺", "is_correct": false, "explanation": "语义：“手艺”指技能，与“健康”无关，句意荒谬。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：“乐器”是演奏用的器具，不能用来修饰“健康”，句子不通。"}], "explanations": {"意识": "“健康意识”指对健康的重视与觉察，与“很好”搭配，句意通顺。", "脾气": "搭配：“脾气”指性情，不说“健康脾气”，句子不通。", "手艺": "语义：“手艺”指技能，与“健康”无关，句意荒谬。", "乐器": "语义：“乐器”是演奏用的器具，不能用来修饰“健康”，句子不通。"}, "sentence_index": 6, "correct_answer": "意识"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事有重要的意识。", "explanation": "这里应该用〈意义〉。“重要”修饰“意义”（重要的意义），“意识”指对事物的觉察，不说“重要的意识”。"}, {"text": "他终于找到了人生的意识。", "explanation": "这里应该用〈方向〉。“找到”搭配“方向”（找到人生的方向），“意识”不能这样使用。"}, {"text": "他对环保有一块意识。", "explanation": "这里量词应该用〈种〉（一种意识）。“块”用于成块的东西，不能用来数“意识”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对安全问题有一只很强的意识。", "corrected_sentence": "他对安全问题有一种很强的意识。", "error_description": "量词错误：“意识”应用量词“种”（一种意识），不能用“只”。“只”多用于动物或成对的东西，“一只意识”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市有一片很强的交通意识。", "corrected_sentence": "这个城市有一种很强的交通意识。", "error_description": "量词错误：“意识”应用量词“种”，不能用“片”。“片”用于面状或平展的东西，“一片意识”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
