INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20924, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很多电脑连在一起，可以互相传消息。", "primary_collocate": null, "pronunciation": "xìn xī wǎng luò", "ipa": "ɕin˥˩ ɕi˥ wɑŋ˨˩˦ luo˥˩", "syllable_count": 4, "sentences": [{"text": "公司有一个信息网络，同事可以互相传文件。", "target_word": "信息网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的信息网络连着每个教室的电脑。", "target_word": "信息网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个信息网络很大，连着上百台电脑。", "target_word": "信息网络", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息网络坏了，我们收不到消息。", "target_word": "信息网络", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在帮学校修信息网络。", "target_word": "信息网络", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "家里的电脑也连进了信息网络。", "target_word": "信息网络", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了信息网络，办公室传文件很方便。", "target_word": "信息网络", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座楼的信息网络今天停了。", "target_word": "信息网络", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师正在检查信息网络。", "target_word": "信息网络", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "信息网络让电脑之间能互相传消息。", "target_word": "信息网络", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个信息网络", "label": "量词"}, {"form": "信息網絡", "label": "繁体"}], "register": "口语", "sense_fingerprint": "许多电脑连在一起、能互相传消息的网络", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c454d24f-0f35-4a6d-a548-05385f361c94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20924, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信息网络", "is_correct": true, "explanation": "“公司有一个信息网络，同事可以互相传文件”，与语境一致。"}, {"text": "停车场", "is_correct": false, "explanation": "语义：“停车场”不能用来让同事互相传文件，句意矛盾。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”与传文件无关，句意不通。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”是吃饭的地方，不能用来互相传文件。"}], "explanations": {"信息网络": "“公司有一个信息网络，同事可以互相传文件”，与语境一致。", "停车场": "语义：“停车场”不能用来让同事互相传文件，句意矛盾。", "花园": "语义：“花园”与传文件无关，句意不通。", "食堂": "语义：“食堂”是吃饭的地方，不能用来互相传文件。"}, "sentence_index": 0, "correct_answer": "信息网络"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "渔民的信息网络破了，鱼都跑掉了。", "explanation": "这里的“网”指渔网，与“信息网络”指计算机系统的义项不同，不能指渔网。"}, {"text": "公司买了一条信息网络。", "explanation": "这里不能用〈条〉。条用于细长的东西，信息网络是计算机系统，应用〈套〉或〈个〉。"}, {"text": "体育老师把信息网络挂在球场上。", "explanation": "这里应该用〈球网〉。信息网络指计算机系统，不是挂在球场上的网，球场上挂的应是球网。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信息网络", "is_correct": true, "explanation": "“有了信息网络，办公室传文件很方便”，与语境一致。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”不能用来传文件，与“办公室传文件很方便”的语境不合。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”与传文件无关，句意不通。"}, {"text": "暖气", "is_correct": false, "explanation": "语义：“暖气”是取暖设备，与传文件无关，句意不通。"}], "explanations": {"信息网络": "“有了信息网络，办公室传文件很方便”，与语境一致。", "雨伞": "语义：“雨伞”不能用来传文件，与“办公室传文件很方便”的语境不合。", "钢琴": "语义：“钢琴”与传文件无关，句意不通。", "暖气": "语义：“暖气”是取暖设备，与传文件无关，句意不通。"}, "sentence_index": 6, "correct_answer": "信息网络"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "蜘蛛让墙角的信息网络越来越大。", "explanation": "这里应该用〈蜘蛛网〉。信息网络指计算机系统，不是蜘蛛织的网，墙角越来越大的网应说蜘蛛网。"}, {"text": "妈妈把信息网络挂在床边。", "explanation": "这里应该用〈蚊帐〉。信息网络指计算机系统，挂在床边防蚊子的应是蚊帐。"}, {"text": "工人用信息网络围住了这块地。", "explanation": "这里应该用〈铁丝网〉。信息网络指计算机系统，不能用来围地，围地要用铁丝网。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司的一台信息网络出了点问题。", "corrected_sentence": "公司的一个信息网络出了点问题。", "error_description": "“信息网络”的量词应用“个”或“套”，“台”用于机器，不能用于网络。应为“一个信息网络”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把办公室的信息网络换。", "corrected_sentence": "我们把办公室的信息网络换了。", "error_description": "“把”字句的谓语后要带“了”等补充成分，漏掉“了”，句子不完整。应为“换了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20926, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "双向", "is_correct": true, "explanation": "反义：「双向」指车辆或通行可以两个方向都走，与「单向」相对。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：「明亮」形容光线，与「单向」不构成相对的关系。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：「柔软」形容质地，与「单向」不构成相对的关系。"}, {"text": "温暖", "is_correct": false, "explanation": "语义：「温暖」形容温度，与「单向」不构成相对的关系。"}], "correct_answer": "双向", "explanations": {"双向": "反义：「双向」指车辆或通行可以两个方向都走，与「单向」相对。", "明亮": "语义：「明亮」形容光线，与「单向」不构成相对的关系。", "柔软": "语义：「柔软」形容质地，与「单向」不构成相对的关系。", "温暖": "语义：「温暖」形容温度，与「单向」不构成相对的关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20926, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "双向", "is_correct": true, "explanation": "反义：「双向」指两个方向都可以通行或流动，与「单向」相对。"}, {"text": "缓慢", "is_correct": false, "explanation": "语义：「缓慢」形容速度，与「单向」不构成相对的关系。"}, {"text": "干净", "is_correct": false, "explanation": "语义：「干净」形容清洁程度，与「单向」不构成相对的关系。"}, {"text": "高大", "is_correct": false, "explanation": "语义：「高大」形容体形或尺寸，与「单向」不构成相对的关系。"}], "correct_answer": "双向", "explanations": {"双向": "反义：「双向」指两个方向都可以通行或流动，与「单向」相对。", "缓慢": "语义：「缓慢」形容速度，与「单向」不构成相对的关系。", "干净": "语义：「干净」形容清洁程度，与「单向」不构成相对的关系。", "高大": "语义：「高大」形容体形或尺寸，与「单向」不构成相对的关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20926, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "只往一个方向，不换方向。", "primary_collocate": null, "pronunciation": "dān xiàng", "ipa": "tan˥ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这条街是单向的，只能往东开。", "target_word": "单向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前面的路是单向的，不能掉头。", "target_word": "单向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥是单向通行的。", "target_word": "单向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条车道是单向的，不能倒车。", "target_word": "单向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个门是单向的，只能出不能进。", "target_word": "单向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家门口的路改成了单向的。", "target_word": "单向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地铁站里的楼梯是单向的。", "target_word": "单向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机开进了单向的小路，只好往前走。", "target_word": "单向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请注意，这条路只能单向行驶。", "target_word": "单向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水是单向流动的，推着小船往前走。", "target_word": "单向", "complexity_tier": "T3", "furigana": "dān xiàng", "sentence_source": "generated"}], "morphological_forms": [{"form": "單向", "label": "繁体"}, {"form": "单向性", "label": "复合"}], "register": "中性", "sense_fingerprint": "只朝一个方向走，不能换方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c454d24f-0f35-4a6d-a548-05385f361c94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20926, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "单向", "is_correct": true, "explanation": "正确：「只能往东开」说明车辆只朝一个方向行驶，「单向」正合句意。"}, {"text": "双向", "is_correct": false, "explanation": "语义：「双向」与后半句「只能往东开」矛盾，不能描述只能朝一个方向行驶的街道。"}, {"text": "甜蜜", "is_correct": false, "explanation": "搭配：「甜蜜」形容感情或生活，不能修饰街道。"}, {"text": "柔软", "is_correct": false, "explanation": "体貌：「柔软」形容质地，街道不能是柔软的。"}], "explanations": {"单向": "正确：「只能往东开」说明车辆只朝一个方向行驶，「单向」正合句意。", "双向": "语义：「双向」与后半句「只能往东开」矛盾，不能描述只能朝一个方向行驶的街道。", "甜蜜": "搭配：「甜蜜」形容感情或生活，不能修饰街道。", "柔软": "体貌：「柔软」形容质地，街道不能是柔软的。"}, "sentence_index": 0, "correct_answer": "单向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子很单向，相信所有人。", "explanation": "这里应该用〈单纯〉。「单向」指只往一个方向，不用来形容人的性格；心地简单、不设防应说「单纯」。"}, {"text": "我买了一张单向票，只去不回。", "explanation": "这里应该用〈单程〉。只去不回的车票称「单程票」，不说「单向票」。"}, {"text": "他单向取消了约定。", "explanation": "这里应该用〈单方面〉。「单向」指朝一个方向，不修饰「取消」这类动作；由一方独自作出应说「单方面」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20926, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "单向", "is_correct": true, "explanation": "正确：「地铁站里的楼梯」只允许人朝一个方向上下，「单向」符合句意。"}, {"text": "热情", "is_correct": false, "explanation": "语义：「热情」形容人的态度，楼梯不能是热情的。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：「清脆」多形容声音，不说楼梯是清脆的。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：「温柔」形容人的性情，不能用来描述楼梯。"}], "explanations": {"单向": "正确：「地铁站里的楼梯」只允许人朝一个方向上下，「单向」符合句意。", "热情": "语义：「热情」形容人的态度，楼梯不能是热情的。", "清脆": "搭配：「清脆」多形容声音，不说楼梯是清脆的。", "温柔": "语义：「温柔」形容人的性情，不能用来描述楼梯。"}, "sentence_index": 6, "correct_answer": "单向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他身体单向，经不起风吹。", "explanation": "这里应该用〈单薄〉。「单向」指只往一个方向，不用来形容身材或体质；身体瘦弱应说「单薄」。"}, {"text": "我们单向谈了一次，效果很好。", "explanation": "这里应该用〈单独〉。「单向」不修饰「谈」这类动作；两人单独见面商谈应说「单独」。"}, {"text": "这首歌的旋律太单向了，听久了很累。", "explanation": "这里应该用〈单调〉。「单向」不用来形容旋律；旋律变化少、听着乏味应说「单调」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路段是单向地，只能往北走。", "corrected_sentence": "这条路段是单向的，只能往北走。", "error_description": "作谓语的「单向」后要用「的」，应说「是单向的」；写成「单向地」用错了词尾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车子只能单向的通过这座桥。", "corrected_sentence": "车子只能单向地通过这座桥。", "error_description": "「单向」修饰动词「通过」时要用「地」，应说「单向地通过」；用「的」不符合规范。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
