INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20936, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20936, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "民族就是很多人一起生活，他们有一样的语言和习惯。", "primary_collocate": null, "pronunciation": "mín zú", "ipa": "min˧˥ tsu˧˥", "syllable_count": 2, "sentences": [{"text": "中国有五十六个民族。", "target_word": "民族", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每个民族都有自己的语言。", "target_word": "民族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个民族的人喜欢唱歌跳舞。", "target_word": "民族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们是两个不同的民族。", "target_word": "民族", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "民族节日那天，大家穿着漂亮的衣服。", "target_word": "民族", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个民族有自己的新年。", "target_word": "民族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想学习这个民族的历史。", "target_word": "民族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在中国，很多民族一起生活。", "target_word": "民族", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你是哪个民族的人？", "target_word": "民族", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个民族的饭菜很好吃。", "target_word": "民族", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "少数民族", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：有共同语言和习惯的人群", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a7a5ac5-16ea-4b03-b6bf-b31c050a3381') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20936, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民族", "is_correct": true, "explanation": "正确。“中国有五十六个民族”指五十六个有共同语言和习惯的人群，“个”搭配人群类名词。"}, {"text": "地区", "is_correct": false, "explanation": "语义：地区是地理区划，不指有共同语言和习惯的人群，与“五十六”不符。"}, {"text": "省份", "is_correct": false, "explanation": "语义：中国的省份数量远少于五十六，且省份是行政区划，不是人群。"}, {"text": "国籍", "is_correct": false, "explanation": "搭配：“国籍”指个人的法律归属，不作群体计数对象，不说“五十六个国籍”。"}], "explanations": {"民族": "正确。“中国有五十六个民族”指五十六个有共同语言和习惯的人群，“个”搭配人群类名词。", "地区": "语义：地区是地理区划，不指有共同语言和习惯的人群，与“五十六”不符。", "省份": "语义：中国的省份数量远少于五十六，且省份是行政区划，不是人群。", "国籍": "搭配：“国籍”指个人的法律归属，不作群体计数对象，不说“五十六个国籍”。"}, "sentence_index": 0, "correct_answer": "民族"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中国有五十六只民族。", "explanation": "这里应该用〈个〉。民族的量词是“个”，不说“只”。"}, {"text": "这三个人是一个民族，住在一起。", "explanation": "这里不能用〈民族〉指几个人。民族指很多人共有语言和习惯的群体，三个人不够“很多人”，应说“这三个人住在一起”。"}, {"text": "我是一个民族。", "explanation": "这里不能用〈民族〉指单个人。民族指人群，应说“我是某个民族的人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20936, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民族", "is_correct": true, "explanation": "正确。“这个民族的历史”指有共同语言和习惯的人群的历史。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以研究历史的人群或对象，与“学习……的历史”不符。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭是一顿饭，不是可以作为学习对象的历史主体。"}, {"text": "呼吸", "is_correct": false, "explanation": "搭配：“呼吸”不能与“这个……的历史”搭配，不说“呼吸的历史”。"}], "explanations": {"民族": "正确。“这个民族的历史”指有共同语言和习惯的人群的历史。", "天气": "语义：天气不是可以研究历史的人群或对象，与“学习……的历史”不符。", "午饭": "语义：午饭是一顿饭，不是可以作为学习对象的历史主体。", "呼吸": "搭配：“呼吸”不能与“这个……的历史”搭配，不说“呼吸的历史”。"}, "sentence_index": 6, "correct_answer": "民族"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司是一个民族，由三个人组成。", "explanation": "这里不能用〈民族〉指公司等组织。民族指人群，应说“这家公司由三个人组成”。"}, {"text": "我的民族把书放在桌子上了。", "explanation": "这里不能用〈民族〉作施事做具体动作。民族是群体，应说“我把书放在桌子上了”。"}, {"text": "他把民族放进了书包。", "explanation": "这里用错了〈民族〉的对象。民族是人群，不是可以装进书包的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20936, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只民族有自己的语言。", "corrected_sentence": "这个民族有自己的语言。", "error_description": "错误：“民族”的量词是“个”，不是“只”。正确：这个民族。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们学习这个民族们的文化。", "corrected_sentence": "我们学习这个民族的文化。", "error_description": "错误：“民族”后不加“们”，“们”只用于指人的名词或人称。正确：这个民族的文化。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
