INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20938, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20938, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种经济制度：工厂、商店等生产资料归私人所有，人们靠经营赚钱。", "primary_collocate": null, "pronunciation": "zī běn zhǔ yì", "ipa": "tsɹ̩˥ pən˨˩ ʈʂu˨˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "有人开工厂赚钱，这是资本主义。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资本主义就是自己开店，自己赚钱。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸说，资本主义让人努力做生意。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在资本主义里，工厂和商店是私人的。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了什么是资本主义。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的人喜欢资本主义，因为能自己赚钱。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了解资本主义是怎么来的。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资本主义国家有很多大公司。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得资本主义好不好？", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的资本主义发展得很快。", "target_word": "资本主义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "資本主義", "label": "繁体"}], "register": "中性", "sense_fingerprint": "私人开工厂、商店赚钱的做法和制度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c454d24f-0f35-4a6d-a548-05385f361c94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20938, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "资本主义", "is_correct": true, "explanation": "正确：句中说的是私人开工厂赚钱的做法，即资本主义。"}, {"text": "社会主义", "is_correct": false, "explanation": "语义：句中说的是私人开工厂赚钱，与社会主义的公有制不符。"}, {"text": "民主", "is_correct": false, "explanation": "语义：「民主」指政治制度，与开工厂赚钱的经济做法无关。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：「这是工厂」不能解释「开工厂赚钱」这种做法。"}], "explanations": {"资本主义": "正确：句中说的是私人开工厂赚钱的做法，即资本主义。", "社会主义": "语义：句中说的是私人开工厂赚钱，与社会主义的公有制不符。", "民主": "语义：「民主」指政治制度，与开工厂赚钱的经济做法无关。", "工厂": "搭配：「这是工厂」不能解释「开工厂赚钱」这种做法。"}, "sentence_index": 0, "correct_answer": "资本主义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的资本主义是每天互相帮助。", "explanation": "这里应用〈信条〉。资本主义是经济制度，不指班级的主张或准则；班级的准则可说「信条」。"}, {"text": "我们暑假去资本主义旅游。", "explanation": "这里应用〈资本主义国家〉。资本主义是经济制度，不是地点；去某类国家应说「资本主义国家」。"}, {"text": "这位资本主义拥有很多家工厂。", "explanation": "这里应用〈资本家〉。资本主义是经济制度，不指人；拥有工厂的人应说「资本家」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资本主义", "is_correct": true, "explanation": "正确：「了解……是怎么来的」问的是一种制度的起源，资本主义符合。"}, {"text": "爸爸", "is_correct": false, "explanation": "语域：「爸爸」是亲属称谓，不适合放在讨论制度起源的书面语境中。"}, {"text": "老师", "is_correct": false, "explanation": "语义：「老师」指人，「是怎么来的」问的是制度或事物的起源。"}, {"text": "妈妈", "is_correct": false, "explanation": "搭配：问「妈妈是怎么来的」指人的出身，不符合「了解」的对象。"}], "explanations": {"资本主义": "正确：「了解……是怎么来的」问的是一种制度的起源，资本主义符合。", "爸爸": "语域：「爸爸」是亲属称谓，不适合放在讨论制度起源的书面语境中。", "老师": "语义：「老师」指人，「是怎么来的」问的是制度或事物的起源。", "妈妈": "搭配：问「妈妈是怎么来的」指人的出身，不符合「了解」的对象。"}, "sentence_index": 6, "correct_answer": "资本主义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个国家的一座资本主义发展得很快。", "explanation": "这里应用〈种〉（一种资本主义）。座用于山、建筑等大型物体；经济制度类名词计量用「种」。"}, {"text": "这个国家的一台资本主义发展得很快。", "explanation": "这里不能用〈台〉。台用于机器，资本主义是经济制度，不能用台计量；应用「种」。"}, {"text": "我们把这个资本主义搬进了教室。", "explanation": "这里不能把〈资本主义〉当作可以搬动的具体物品。资本主义是抽象的经济制度，不能搬进教室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一本资本主义，不是社会主义。", "corrected_sentence": "这是一种资本主义，不是社会主义。", "error_description": "量词错误：「资本主义」是经济制度，计量应用「种」；「本」用于书册，不能用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个国家的资本主义发展地很快。", "corrected_sentence": "这个国家的资本主义发展得很快。", "error_description": "补语标记错误：「发展」后的补语应用「得」引出，「地」用于修饰动词，「发展地很快」不成立。应为「发展得很快」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20942, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻挠", "is_correct": true, "explanation": "反义：“促成”是出力帮忙使事情成功，“阻挠”是从中设置障碍使事情不能成功，二者意思相反。"}, {"text": "收藏", "is_correct": false, "explanation": "与“促成”不构成反义关系，“收藏”指把东西保存起来。"}, {"text": "洗涤", "is_correct": false, "explanation": "与“促成”不构成反义关系，“洗涤”指用水清除污垢。"}, {"text": "翻译", "is_correct": false, "explanation": "与“促成”不构成反义关系，“翻译”指把一种语言转换成另一种语言。"}], "correct_answer": "阻挠", "explanations": {"阻挠": "反义：“促成”是出力帮忙使事情成功，“阻挠”是从中设置障碍使事情不能成功，二者意思相反。", "收藏": "与“促成”不构成反义关系，“收藏”指把东西保存起来。", "洗涤": "与“促成”不构成反义关系，“洗涤”指用水清除污垢。", "翻译": "与“促成”不构成反义关系，“翻译”指把一种语言转换成另一种语言。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20942, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻挠", "is_correct": true, "explanation": "反义：“促成”是帮助事情成功，“阻挠”是设置障碍使事情不成，二者意思相反。"}, {"text": "观察", "is_correct": false, "explanation": "与“促成”不构成反义关系，“观察”指仔细看以了解情况。"}, {"text": "修补", "is_correct": false, "explanation": "与“促成”不构成反义关系，“修补”指修理破损的东西。"}, {"text": "包装", "is_correct": false, "explanation": "与“促成”不构成反义关系，“包装”指用纸或盒子把东西裹起来。"}], "correct_answer": "阻挠", "explanations": {"阻挠": "反义：“促成”是帮助事情成功，“阻挠”是设置障碍使事情不成，二者意思相反。", "观察": "与“促成”不构成反义关系，“观察”指仔细看以了解情况。", "修补": "与“促成”不构成反义关系，“修补”指修理破损的东西。", "包装": "与“促成”不构成反义关系，“包装”指用纸或盒子把东西裹起来。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20942, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让一件事成功发生。", "primary_collocate": null, "pronunciation": "cù chéng", "ipa": "tsʰu˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "小李帮忙促成了我们的约会。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你促成这件事。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直想促成这次旅行。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈促成了哥哥和老师的见面。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是邻居促成了这门亲事。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的话促成了我们的和好。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想促成他们俩和好。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机会是朋友促成的。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起促成了这次聚会。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想办法促成了这笔买卖。", "target_word": "促成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "促成了", "label": "体标"}, {"form": "促成过", "label": "体标"}], "register": "书面", "sense_fingerprint": "出力帮忙，让某件事顺利成功", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730e64f6-c995-4cfd-ab89-a28de46c42ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20942, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咬", "is_correct": false, "explanation": "语义：“咬”不能带“约会”作宾语，句意荒谬。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”不能与“约会”搭配，无法表示帮忙使事情成功。"}, {"text": "促成", "is_correct": true, "explanation": "正确：“促成”指出力帮忙让事情成功，与“帮忙”及“约会”搭配，句意通顺。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能带“约会”作宾语，表达不出帮忙促成的意思。"}], "explanations": {"咬": "语义：“咬”不能带“约会”作宾语，句意荒谬。", "擦": "搭配：“擦”不能与“约会”搭配，无法表示帮忙使事情成功。", "促成": "正确：“促成”指出力帮忙让事情成功，与“帮忙”及“约会”搭配，句意通顺。", "洗": "搭配：“洗”不能带“约会”作宾语，表达不出帮忙促成的意思。"}, "sentence_index": 0, "correct_answer": "促成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想促成这把椅子。", "explanation": "这里应该用〈搬走〉。促成的对象是事情或结果，不能是具体的椅子。"}, {"text": "我想促成那只猫。", "explanation": "这里应该用〈养〉。促成的对象是事情或结果，「那只猫」是动物，不能作促成的对象；应说「我想养那只猫」。"}, {"text": "他想促成那瓶水。", "explanation": "这里应该用〈喝〉。促成的对象是事情或结果，「那瓶水」是具体的东西，不能作促成的对象；应说「他想喝那瓶水」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20942, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拆", "is_correct": false, "explanation": "语义：“拆”是拆开的意思，不能使人和好，“拆他们俩和好”句意矛盾。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”不能表示促使人和好，句意荒谬。"}, {"text": "促成", "is_correct": true, "explanation": "正确：“促成”指推动事情达成，与“想”及“他们俩和好”搭配，句意通顺。"}, {"text": "尝", "is_correct": false, "explanation": "搭配：“尝”不能带“他们俩和好”这样的小句作宾语。"}], "explanations": {"拆": "语义：“拆”是拆开的意思，不能使人和好，“拆他们俩和好”句意矛盾。", "烤": "语义：“烤”不能表示促使人和好，句意荒谬。", "促成": "正确：“促成”指推动事情达成，与“想”及“他们俩和好”搭配，句意通顺。", "尝": "搭配：“尝”不能带“他们俩和好”这样的小句作宾语。"}, "sentence_index": 6, "correct_answer": "促成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们希望促成那棵树。", "explanation": "这里应该用〈种〉。促成的对象是事情或结果，「那棵树」是具体的东西，不能作促成的对象；应说「我们希望种那棵树」。"}, {"text": "他想促成那声叹息。", "explanation": "这里应该用〈听到〉。促成的对象是事情或结果，“那声叹息”是声音，不能用“促成”，应说“听到”。"}, {"text": "他想促成那位老人。", "explanation": "这里应该用〈照顾〉。促成的对象是事情或结果，不能直接用于人，想照顾老人应说“照顾”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们俩促成着这次旅行。", "corrected_sentence": "他们俩促成过这次旅行。", "error_description": "“着”用错：表示曾经经历的“过”应放在动词后面，应说“促成过”，不能用“着”表示持续。错误：促成着。正确：促成过。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老师促成着那次见面。", "corrected_sentence": "这位老师促成了那次见面。", "error_description": "“着”用错：“促成”表示事情已经达成，完成时应用“了”，不能用“着”表示持续。错误：促成着。正确：促成了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f90431d3-04c9-4bfb-8e8d-e2d14614129d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
