INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20944, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f0b7ac-84f8-4ec9-9eb1-25f685137808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20944, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "脑子里的想法。", "primary_collocate": null, "pronunciation": "sī xiǎng", "ipa": "sɹ̩˥ ɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他脸上很平静，没人知道他的思想。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的脑子里有很多奇怪的思想。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的思想突然跳出一个念头，他一下子愣住了。", "target_word": "思想", "complexity_tier": "T3", "furigana": "sī xiǎng", "sentence_source": "generated"}, {"text": "睡觉前，他的思想总是很乱。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子的小脑袋里装着许多思想。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很少说话，思想却一直在动。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把心里的思想都写在日记里。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安静的夜晚，他的思想飞得很远。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人看着窗外，思想回到了小时候。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些思想他从来没有告诉过别人。", "target_word": "思想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种思想", "label": "量词：种"}, {"form": "一些思想", "label": "量词：些"}, {"form": "思想家", "label": "复合"}], "register": "书面", "sense_fingerprint": "脑子里的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44487a15-d41b-418d-9679-5307425a1f18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20944, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "思想", "is_correct": true, "explanation": "「思想」指脑子里的想法，与「没人知道他的…」所说的内心隐秘相合。"}, {"text": "哭声", "is_correct": false, "explanation": "语义：「哭声」能被听到，与「脸上很平静」的情形矛盾。"}, {"text": "笑声", "is_correct": false, "explanation": "语义：「笑声」与「脸上很平静」的状态不符。"}, {"text": "歌声", "is_correct": false, "explanation": "搭配：「歌声」是可以听见的声音，不是藏在心里、不为人知的东西，不能与「没人知道」搭配。"}], "explanations": {"思想": "「思想」指脑子里的想法，与「没人知道他的…」所说的内心隐秘相合。", "哭声": "语义：「哭声」能被听到，与「脸上很平静」的情形矛盾。", "笑声": "语义：「笑声」与「脸上很平静」的状态不符。", "歌声": "搭配：「歌声」是可以听见的声音，不是藏在心里、不为人知的东西，不能与「没人知道」搭配。"}, "sentence_index": 0, "correct_answer": "思想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨晚我做了一个很长的思想。", "explanation": "这里应该用〈梦〉。「做梦」是固定搭配，「思想」不能与「做」搭配。"}, {"text": "他突然收到一封很长的思想。", "explanation": "这里应该用〈信〉。「思想」是脑子里的想法，不能用量词「封」来计量。"}, {"text": "她把一个很大的思想装进了行李箱。", "explanation": "这里应该用〈衣服〉。「思想」是无形的念头，不能像衣服一样装进行李箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f0b7ac-84f8-4ec9-9eb1-25f685137808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思想", "is_correct": true, "explanation": "「思想」指脑子里的想法，可以写在日记里，与「心里的…都写在日记里」相合。"}, {"text": "心跳", "is_correct": false, "explanation": "语义：「心跳」无法写在日记里，与「都写在日记里」的语境矛盾。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：「体温」不能与「写在日记里」搭配。"}, {"text": "体重", "is_correct": false, "explanation": "语义：「体重」不是心里的想法，与「心里的」语境不符。"}], "explanations": {"思想": "「思想」指脑子里的想法，可以写在日记里，与「心里的…都写在日记里」相合。", "心跳": "语义：「心跳」无法写在日记里，与「都写在日记里」的语境矛盾。", "体温": "搭配：「体温」不能与「写在日记里」搭配。", "体重": "语义：「体重」不是心里的想法，与「心里的」语境不符。"}, "sentence_index": 6, "correct_answer": "思想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把思想摆在桌上。", "explanation": "这里应该用〈书〉。「思想」无形，不能像书一样摆在桌上。"}, {"text": "他把思想戴在鼻梁上。", "explanation": "这里应该用〈眼镜〉。「思想」无形，不能戴在鼻梁上。"}, {"text": "他撑着思想走进雨里。", "explanation": "这里应该用〈伞〉。「思想」不能被撑开遮雨，「撑」的对象应是伞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f0b7ac-84f8-4ec9-9eb1-25f685137808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的一条思想总在半夜里转个不停。", "corrected_sentence": "她的一些思想总在半夜里转个不停。", "error_description": "量词错误：「条」用于细长的东西，不能用于「思想」，应用「些」或「种」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f0b7ac-84f8-4ec9-9eb1-25f685137808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她心里藏着一张思想，从来没有说出来。", "corrected_sentence": "她心里藏着一种思想，从来没有说出来。", "error_description": "量词错误：「张」用于平面的东西，不能用于「思想」，应用「种」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f0b7ac-84f8-4ec9-9eb1-25f685137808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
