INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20946, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们做东西的方法。", "primary_collocate": null, "pronunciation": "shēng chǎn fāng shì", "ipa": "ʂɤŋ˥ ʈʂʰan˨˩ faŋ˥ ʂɻ̩˥˩", "syllable_count": 4, "sentences": [{"text": "以前的生产方式很慢。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在工厂用机器，生产方式变了。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店有自己的生产方式。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想了解面包的生产方式。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的生产方式让产品又快又便宜。", "target_word": "生产方式", "complexity_tier": "T3", "furigana": "xīn de shēng chǎn fāng shì ràng chǎn pǐn yòu kuài yòu pián yi.", "sentence_source": "generated"}, {"text": "农民的生产方式和工人不一样。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种生产方式不会浪费东西。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们看了工厂的生产方式。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的生产方式能省很多时间。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们换了一种生产方式。", "target_word": "生产方式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生產方式", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人们制作东西所用的方法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c454d24f-0f35-4a6d-a548-05385f361c94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20946, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生产方式", "is_correct": true, "explanation": "正确：「以前的……很慢」描述的是做东西的方法，即生产方式。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不能作为做东西的方法来说「很慢」。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：天气不能作为做东西的方法，也不说「很慢」。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：名字没有快慢，不能与「很慢」搭配。"}], "explanations": {"生产方式": "正确：「以前的……很慢」描述的是做东西的方法，即生产方式。", "老虎": "语义：老虎是动物，不能作为做东西的方法来说「很慢」。", "天气": "搭配：天气不能作为做东西的方法，也不说「很慢」。", "名字": "搭配：名字没有快慢，不能与「很慢」搭配。"}, "sentence_index": 0, "correct_answer": "生产方式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我换了生产方式，成绩进步很快。", "explanation": "这里应用〈学习方法〉。生产方式指制作东西的方法，不用于学习。"}, {"text": "他说话的生产方式很特别。", "explanation": "这里应用〈说话方式〉。生产方式指制作东西的方法，不指说话。"}, {"text": "她的穿衣生产方式很独特。", "explanation": "这里应用〈穿衣风格〉。生产方式指制作东西的方法，不指穿衣的风格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生产方式", "is_correct": true, "explanation": "正确：「这种……不会浪费东西」评价的是做东西的方法，即生产方式。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不是做东西的方法，不能「不会浪费东西」。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：朋友是人，不是做东西的方法。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：「空气」不能用「不会浪费东西」来描述做东西的方法。"}], "explanations": {"生产方式": "正确：「这种……不会浪费东西」评价的是做东西的方法，即生产方式。", "小猫": "语义：小猫是动物，不是做东西的方法，不能「不会浪费东西」。", "朋友": "语义：朋友是人，不是做东西的方法。", "空气": "搭配：「空气」不能用「不会浪费东西」来描述做东西的方法。"}, "sentence_index": 6, "correct_answer": "生产方式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们换了一块生产方式。", "explanation": "这里不能用〈块〉。块用于片状或块状的东西，生产方式是抽象的方法，应用〈种〉。"}, {"text": "他的生产方式很有礼貌。", "explanation": "这里应用〈待人态度〉。生产方式指制作东西的方法，不能形容人的礼貌。"}, {"text": "他们的生产方式很浪漫。", "explanation": "这里应用〈恋爱方式〉。生产方式指制作东西的方法，不能形容恋爱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店用了一件生产方式。", "corrected_sentence": "这家店用了一种生产方式。", "error_description": "量词错误：「生产方式」应搭配量词「种」，不能用「件」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们换了一把新的生产方式。", "corrected_sentence": "他们换了一种新的生产方式。", "error_description": "量词错误：「生产方式」应搭配量词「种」，不能用「把」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
