INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20948, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西你中有我，我中有你，分不开。", "primary_collocate": null, "pronunciation": "xiāng hù jiāo zhī", "ipa": "ɕi̯ɑŋ˥ xu˥˩ tɕi̯ɑʊ˥ ʈʂɻ̩˥", "syllable_count": 4, "sentences": [{"text": "老树的根在地下相互交织。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶上的电线相互交织，像一张网。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的草和花相互交织着。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的马路相互交织，像一张大网。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竹子的根相互交织，把土抓得很紧。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毛线相互交织，织成了一件毛衣。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林里，树枝相互交织，挡住了阳光。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外的藤蔓相互交织，爬满了墙。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔网上的线相互交织，非常结实。", "target_word": "相互交织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两棵老树的枝叶在山下相互交织。", "target_word": "相互交织", "complexity_tier": "T3", "furigana": "liǎng kē lǎo shù de zhī yè zài shān xià xiāng hù jiāo zhī", "sentence_source": "generated"}], "morphological_forms": [{"form": "相互交织着", "label": "体标"}], "register": "书面", "sense_fingerprint": "具体的东西你中有我、我中有你、分不开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '490a1ea9-d1a0-48ef-b4b1-68de036f2317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相互交织", "is_correct": true, "explanation": "正确：老树的根在地下互相缠绕，符合具体事物缠绕的义项。"}, {"text": "相互飞翔", "is_correct": false, "explanation": "语义：根在地下不能飞翔，与“在地下”的语境矛盾。"}, {"text": "相互对视", "is_correct": false, "explanation": "配价：“对视”的主体须是有眼睛的生物，树根不能对视。"}, {"text": "相互唱和", "is_correct": false, "explanation": "配价：“唱和”需要能歌唱的主体，树根不能唱和。"}], "explanations": {"相互交织": "正确：老树的根在地下互相缠绕，符合具体事物缠绕的义项。", "相互飞翔": "语义：根在地下不能飞翔，与“在地下”的语境矛盾。", "相互对视": "配价：“对视”的主体须是有眼睛的生物，树根不能对视。", "相互唱和": "配价：“唱和”需要能歌唱的主体，树根不能唱和。"}, "sentence_index": 0, "correct_answer": "相互交织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两位朋友在街上相互交织，各走各的。", "explanation": "这里应该用〈分开〉。各走各的是分开，“相互交织”表示东西你中有我、分不开，不能用于分开。"}, {"text": "两张照片在桌上相互交织。", "explanation": "这里应该用〈重叠〉。两物部分盖在一起要用重叠，“相互交织”强调缠绕穿插。"}, {"text": "这条路到了前面一分为二，又相互交织。", "explanation": "这里应该用〈分岔〉。道路一分为二要用分岔，“相互交织”表示缠绕在一起，两者意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相互交织", "is_correct": true, "explanation": "正确：树枝互相缠绕，才能挡住阳光。"}, {"text": "相互远离", "is_correct": false, "explanation": "语义：树枝相互远离就不会挡住阳光，与“挡住了阳光”矛盾。"}, {"text": "相互照耀", "is_correct": false, "explanation": "语义：“照耀”指发光，树枝不会发光，与“挡住了阳光”矛盾。"}, {"text": "相互问候", "is_correct": false, "explanation": "配价：“问候”的主体须是人，树枝不能问候。"}], "explanations": {"相互交织": "正确：树枝互相缠绕，才能挡住阳光。", "相互远离": "语义：树枝相互远离就不会挡住阳光，与“挡住了阳光”矛盾。", "相互照耀": "语义：“照耀”指发光，树枝不会发光，与“挡住了阳光”矛盾。", "相互问候": "配价：“问候”的主体须是人，树枝不能问候。"}, "sentence_index": 6, "correct_answer": "相互交织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两支军队在河边相互交织，互相攻击。", "explanation": "这里应该用〈对抗〉。互相攻击是对抗，“相互交织”表示东西分不开，不表示敌对。"}, {"text": "两个孩子在院子里相互交织，互相追跑。", "explanation": "这里应该用〈追逐〉。互相追跑是追逐，“相互交织”表示缠绕在一起，不表示追逐。"}, {"text": "两位同事在办公室里相互交织，聊了一下午。", "explanation": "这里应该用〈交谈〉。聊天要说交谈，“相互交织”指东西缠绕在一起，不用于人的交谈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两根铁丝在墙角被相互交织着。", "corrected_sentence": "两根铁丝在墙角相互交织着。", "error_description": "被字句误用：“相互交织”是不及物动词，不能用在“被”字句中，应去掉“被”，说“相互交织着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "藤蔓在墙上相互交织的很密。", "corrected_sentence": "藤蔓在墙上相互交织得很密。", "error_description": "错误在于补语标记。表示动作程度的补语要用结构助词“得”，写成“的”是常见错误。正确形式是“相互交织得很密”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a5d8731-1f49-491a-b49c-50d91d9928ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20950, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "阻止", "is_correct": true, "explanation": "“阻止”表示使事情无法前进，与“推动”（使事情前进）的意思相对，是反义词。"}, {"text": "欣赏", "is_correct": false, "explanation": "“欣赏”表示喜爱、称赞，与“推动”没有反义关系。"}, {"text": "收藏", "is_correct": false, "explanation": "“收藏”表示保存起来，与“推动”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”表示仔细看，与“推动”没有反义关系。"}], "correct_answer": "阻止", "explanations": {"阻止": "“阻止”表示使事情无法前进，与“推动”（使事情前进）的意思相对，是反义词。", "欣赏": "“欣赏”表示喜爱、称赞，与“推动”没有反义关系。", "收藏": "“收藏”表示保存起来，与“推动”没有反义关系。", "观察": "“观察”表示仔细看，与“推动”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
