INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20950, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西动起来或让事情向前走。", "primary_collocate": null, "pronunciation": "tuī dòng", "ipa": "tʰuei˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "风推动了河上的小船。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力推动了那辆旧车。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新技术推动了经济发展。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话推动我努力学习。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水可以推动大轮子转起来。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起推动这个计划。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友推动我完成了这件事。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想推动环境保护。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛推动了城市的发展。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮忙推动一下这张桌子。", "target_word": "推动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推动了", "label": "体标"}, {"form": "推动着", "label": "体标"}, {"form": "推动过", "label": "体标"}, {"form": "推动力", "label": "复合"}], "register": "中性", "sense_fingerprint": "用力使物体移动或使事情进展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73bdc592-5317-4323-ab99-fe56d44fcace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20950, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "推动", "is_correct": true, "explanation": "“推动”表示使小船移动，符合“风……了河上的小船”的句意。"}, {"text": "修理", "is_correct": false, "explanation": "语义：风不能修理小船，句意不通。"}, {"text": "卖", "is_correct": false, "explanation": "语义：风不能卖东西，句意不通。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的动作主体一般是人，不说“风驾驶小船”。"}], "explanations": {"推动": "“推动”表示使小船移动，符合“风……了河上的小船”的句意。", "修理": "语义：风不能修理小船，句意不通。", "卖": "语义：风不能卖东西，句意不通。", "驾驶": "搭配：“驾驶”的动作主体一般是人，不说“风驾驶小船”。"}, "sentence_index": 0, "correct_answer": "推动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我推动他明天会来。", "explanation": "这里应该用〈推断〉。“推动”表示促使事情前进，不能表示根据已知情况作出判断。"}, {"text": "会议推动了一天。", "explanation": "这里应该用〈推迟〉。“推动”表示使事情前进，不能表示把时间往后延。"}, {"text": "他推动了老师的邀请。", "explanation": "这里应该用〈推辞〉。“推动”不能表示拒绝别人的邀请。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推动", "is_correct": true, "explanation": "“推动”表示促使事情完成，符合“好朋友……我完成了这件事”的语境。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆开或拆除，不能表示促使别人完成事情。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是加热食物，与句意完全无关。"}, {"text": "砸", "is_correct": false, "explanation": "搭配：“砸”带的一般是具体物体，不能用来带人作宾语。"}], "explanations": {"推动": "“推动”表示促使事情完成，符合“好朋友……我完成了这件事”的语境。", "拆": "语义：“拆”指拆开或拆除，不能表示促使别人完成事情。", "烤": "语义：“烤”是加热食物，与句意完全无关。", "砸": "搭配：“砸”带的一般是具体物体，不能用来带人作宾语。"}, "sentence_index": 6, "correct_answer": "推动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "起义军推动了暴君。", "explanation": "这里应该用〈推翻〉。“推动”表示促使事情前进，不能表示打倒统治者，打倒暴君要说“推翻”。"}, {"text": "他在街上推动牛奶。", "explanation": "这里应该用〈推销〉。“推动”不能表示推销商品，推销牛奶要说“推销”。"}, {"text": "他总是推动责任，不肯承认错误。", "explanation": "这里应该用〈推卸〉。“推动”不能表示把责任推给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们昨天用力推动了着那辆大车。", "corrected_sentence": "工人们昨天用力推动了那辆大车。", "error_description": "错误：“了”和“着”不能同时用在“推动”后面。应说“工人们昨天用力推动了那辆大车”，去掉“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市政府推动了着这项改革。", "corrected_sentence": "市政府推动了这项改革。", "error_description": "错误：“了”和“着”不能同时用在“推动”后面。应说“市政府推动了这项改革”，去掉“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
