INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20958, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "觉得别人说的对。", "primary_collocate": null, "pronunciation": "rèn tóng", "ipa": "ʐən˥˩ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我认同你说的话。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都认同他的意见。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说得对，我完全认同。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法，我不太认同。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你认同我的看法吗？", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈认同了我的决定。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都认同这个办法。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话很有道理，大家都认同。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对这件事，我们都认同小李的做法。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她以前认同过这种想法。", "target_word": "认同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "认同了", "label": "体标（了）"}, {"form": "认同过", "label": "体标（过）"}, {"form": "认同感", "label": "复合词"}], "register": "中性", "sense_fingerprint": "觉得别人说的对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d954bdb-808a-46ea-869b-37621b1d7757') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20958, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认同", "is_correct": true, "explanation": "正确：“认同”表示赞成对方的看法，与“你说的话”搭配。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”指用力使东西裂开，话不能被撕。"}, {"text": "捡", "is_correct": false, "explanation": "搭配：“捡”用于拾取具体的东西，不能说捡别人说的话。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃别人说的话。"}], "explanations": {"认同": "正确：“认同”表示赞成对方的看法，与“你说的话”搭配。", "撕": "语义：“撕”指用力使东西裂开，话不能被撕。", "捡": "搭配：“捡”用于拾取具体的东西，不能说捡别人说的话。", "吃": "搭配：“吃”的对象是食物，不能说吃别人说的话。"}, "sentence_index": 0, "correct_answer": "认同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于认同了自己犯下的错误。", "explanation": "这里应该用〈承认〉。认同指对看法、想法表示赞同；承认错误这类事实要用承认。"}, {"text": "我认同你的申请，马上帮你办。", "explanation": "这里应该用〈同意〉。认同用于对看法的赞同，对申请、请求表示答应要用同意。"}, {"text": "学校认同了他的学历。", "explanation": "这里应该用〈认可〉。认同指赞同看法，学历、资格的正式承认要用认可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b13d3ae-cd47-4f7c-b475-99c532358180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20958, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认同", "is_correct": true, "explanation": "正确：“认同”表示大家都赞成这个办法，与“同学们都”搭配。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，办法不能喝。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说唱这个办法。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”指用脚击打，这个办法不是可以用脚踢的东西。"}], "explanations": {"认同": "正确：“认同”表示大家都赞成这个办法，与“同学们都”搭配。", "喝": "搭配：“喝”的对象是饮品，办法不能喝。", "唱": "搭配：“唱”的对象是歌曲，不能说唱这个办法。", "踢": "语义：“踢”指用脚击打，这个办法不是可以用脚踢的东西。"}, "sentence_index": 6, "correct_answer": "认同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很认同他的不幸。", "explanation": "这里应该用〈同情〉。认同指赞同看法或身份认同，对别人遭遇的怜悯要用同情。"}, {"text": "他认同了这个邀请，下周就来。", "explanation": "这里应该用〈接受〉。认同用于对看法的赞同，邀请、礼物等要用接受。"}, {"text": "他一眼就认同了老朋友。", "explanation": "这里应该用〈认出〉。认同指赞同看法或身份上的认同，辨认人的面貌要用认出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b13d3ae-cd47-4f7c-b475-99c532358180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不认同得你的做法。", "corrected_sentence": "我不认同你的做法。", "error_description": "错误：“认同”后不带补语“得”，应说“我不认同你的做法”，不说“我不认同得你的做法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b13d3ae-cd47-4f7c-b475-99c532358180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她以前认同了过这个观点。", "corrected_sentence": "她以前认同过这个观点。", "error_description": "错误：动词“认同”后已有表示经历的“过”，又加了“了”，形成“认同了过”，两个体标不能同时用。应为“认同过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b13d3ae-cd47-4f7c-b475-99c532358180') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20960, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱化", "is_correct": true, "explanation": "与“强化”构成反义，指使变弱。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”指防护，与“强化”不构成反义。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：“冷却”指降温，与“强化”不构成反义。"}, {"text": "美化", "is_correct": false, "explanation": "语义：“美化”指使美观，与“强化”不构成反义。"}], "correct_answer": "弱化", "explanations": {"弱化": "与“强化”构成反义，指使变弱。", "保护": "语义：“保护”指防护，与“强化”不构成反义。", "冷却": "语义：“冷却”指降温，与“强化”不构成反义。", "美化": "语义：“美化”指使美观，与“强化”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20960, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱化", "is_correct": true, "explanation": "与“强化”构成反义，指使变弱。"}, {"text": "唤醒", "is_correct": false, "explanation": "语义：“唤醒”指叫醒或激发，不是“强化”的反义词。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使燃烧，不是“强化”的反义词。"}, {"text": "消毒", "is_correct": false, "explanation": "语义：“消毒”指杀灭细菌，与“强化”不构成反义。"}], "correct_answer": "弱化", "explanations": {"弱化": "与“强化”构成反义，指使变弱。", "唤醒": "语义：“唤醒”指叫醒或激发，不是“强化”的反义词。", "点燃": "语义：“点燃”指使燃烧，不是“强化”的反义词。", "消毒": "语义：“消毒”指杀灭细菌，与“强化”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20960, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让某样东西变得更强。", "primary_collocate": null, "pronunciation": "qiáng huà", "ipa": "tɕʰiɑŋ˧˥ xuɑ˥˩", "syllable_count": 2, "sentences": [{"text": "老师经常考试，是为了强化学生的记忆。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司开会，是想强化大家的安全意识。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多听几遍，可以强化你对新词的印象。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理决定强化对新员工的管理。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练让队员每天多练，来强化基本功。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司想进一步强化合作关系。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校强化了对考试纪律的要求。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了强化自律能力，他每天坚持锻炼。", "target_word": "强化", "complexity_tier": "T3", "furigana": "qiáng huà", "sentence_source": "generated"}, {"text": "这个活动强化了同学们的团队意识。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了强化环保意识，学校开了一节课。", "target_word": "强化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "强化了", "label": "体标"}, {"form": "强化过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使记忆、意识、管理、关系等抽象事物变得更强更牢固", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '646a9811-93f6-4f9b-bfec-56a7c7ff221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20960, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "强化", "is_correct": true, "explanation": "正确：“强化”表示使记忆更牢固，与句中的目的一致。"}, {"text": "弱化", "is_correct": false, "explanation": "语义：“弱化”指减弱，与“为了……强化记忆”的目的相反。"}, {"text": "消化", "is_correct": false, "explanation": "搭配：“消化”多接食物或知识，不说消化学生的记忆。"}, {"text": "美化", "is_correct": false, "explanation": "语义：“美化”指使事物变美观，与记忆无关。"}], "explanations": {"强化": "正确：“强化”表示使记忆更牢固，与句中的目的一致。", "弱化": "语义：“弱化”指减弱，与“为了……强化记忆”的目的相反。", "消化": "搭配：“消化”多接食物或知识，不说消化学生的记忆。", "美化": "语义：“美化”指使事物变美观，与记忆无关。"}, "sentence_index": 0, "correct_answer": "强化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个项目要强化进度。", "explanation": "这里应该用〈加快〉。说进度快慢要用“加快”，“强化”指使能力、意识等变得更牢固，不用来说速度。"}, {"text": "雨势强化了，路上没有行人。", "explanation": "这里应该用〈加强〉。雨势变大要说“加强”，“强化”多用于能力、意识、管理等抽象事物。"}, {"text": "他的体重强化了三公斤。", "explanation": "这里应该用“增加”。强化只用于抽象的能力、意识、管理，体重这类数量要用“增加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "强化", "is_correct": true, "explanation": "正确：“强化”表示使要求更严格，与学校对考试纪律的做法一致。"}, {"text": "唤醒", "is_correct": false, "explanation": "语义：“唤醒”指叫醒或激发，不能用于要求。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使燃烧，与纪律要求的句意不符。"}, {"text": "消毒", "is_correct": false, "explanation": "搭配：“消毒”接对象一般是物体或环境，不说消毒要求。"}], "explanations": {"强化": "正确：“强化”表示使要求更严格，与学校对考试纪律的做法一致。", "唤醒": "语义：“唤醒”指叫醒或激发，不能用于要求。", "点燃": "语义：“点燃”指使燃烧，与纪律要求的句意不符。", "消毒": "搭配：“消毒”接对象一般是物体或环境，不说消毒要求。"}, "sentence_index": 6, "correct_answer": "强化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间要强化噪音。", "explanation": "这里应该用〈降低〉。噪音要“降低”，“强化”表示让事物变得更强，不能用于噪音。"}, {"text": "这次工作强化了他的负担。", "explanation": "这里应该用〈减轻〉。负担要“减轻”，“强化”表示让事物变得更强，不能用于负担。"}, {"text": "周末我想强化一下心情。", "explanation": "这里应该用〈放松〉。心情要“放松”，“强化”不能用于心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次培训是为了强化了员工的服务意识。", "corrected_sentence": "这次培训是为了强化员工的服务意识。", "error_description": "错误形式：“强化了”。正确形式：“强化”。“为了”引出目的，后面的动词不能带“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校把考试纪律强化很好。", "corrected_sentence": "学校把考试纪律强化得很好。", "error_description": "错误形式：缺少“得”。正确形式：“强化得很好”。“把”字句中，动词“强化”后要用“得”引出补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
