INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20964, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "印刷品是印出来的东西，比如书和报纸。", "primary_collocate": null, "pronunciation": "yìn shuā pǐn", "ipa": "in˥˩ ʂwa˥ pʰin˨˩˦", "syllable_count": 3, "sentences": [{"text": "印刷品上有很多字和图片。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们发了几份印刷品。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "印刷品放久了，纸会变黄。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个展览有很多古代的印刷品。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢看印刷品，不太喜欢看手机。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店里的印刷品种类很多。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份印刷品是免费的，你可以拿走。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧印刷品都卖给了收废品的人。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆里的印刷品要小心保管。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在电子书多了，买印刷品的人少了。", "target_word": "印刷品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "批", "label": "量词"}], "register": "中性", "sense_fingerprint": "印出来的东西，如书和报纸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e245a58-1dc2-40c3-b6f0-b46e940614ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20964, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "印刷品", "is_correct": true, "explanation": "正确：指印出来的东西，书和报纸上都可以有字和图片。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气上没有字和图片，这句说的是印出来的东西。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮上不会印有字和图片，与句意不符。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”不能说“上有字和图片”，搭配不当。"}], "explanations": {"印刷品": "正确：指印出来的东西，书和报纸上都可以有字和图片。", "天气": "语义：天气上没有字和图片，这句说的是印出来的东西。", "月亮": "语义：月亮上不会印有字和图片，与句意不符。", "空气": "搭配：“空气”不能说“上有字和图片”，搭配不当。"}, "sentence_index": 0, "correct_answer": "印刷品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个展览是一座古代的印刷品。", "explanation": "这里应该用〈博物馆〉。印刷品指印出来的东西，不指建筑。"}, {"text": "这个展览的古代印刷品是一台电视。", "explanation": "这里应该用〈电视〉。印刷品指印出来的东西，不是电器。"}, {"text": "我的朋友是一个古代的印刷品，很爱说话。", "explanation": "这里应该指〈人〉而不是〈物品〉。印刷品是印出来的东西，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6975c98-7307-4301-ade2-83f350f6a7f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20964, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "印刷品", "is_correct": true, "explanation": "正确：“印刷品”是可以免费拿走的纸质物品，与“免费”“拿走”相符。"}, {"text": "手术", "is_correct": false, "explanation": "语义：手术不能像纸质物品那样免费拿走，句子不通。"}, {"text": "友谊", "is_correct": false, "explanation": "语义：“友谊”是抽象情感，不能被拿走。"}, {"text": "大海", "is_correct": false, "explanation": "体貌：“大海”体量巨大，不能用“份”计量并拿走。"}], "explanations": {"印刷品": "正确：“印刷品”是可以免费拿走的纸质物品，与“免费”“拿走”相符。", "手术": "语义：手术不能像纸质物品那样免费拿走，句子不通。", "友谊": "语义：“友谊”是抽象情感，不能被拿走。", "大海": "体貌：“大海”体量巨大，不能用“份”计量并拿走。"}, "sentence_index": 6, "correct_answer": "印刷品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现在电子书多了，我买了一台印刷品。", "explanation": "这里应该用〈电子阅读器〉。印刷品指印出来的东西，不指电子设备。"}, {"text": "现在电子书多了，印刷品的软件很好用。", "explanation": "这里应该用〈软件〉。印刷品是印出来的东西，不是程序。"}, {"text": "现在电子书多了，印刷品的屏幕更亮了。", "explanation": "这里应该用〈屏幕〉。印刷品是印出来的纸制品，不指显示器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6975c98-7307-4301-ade2-83f350f6a7f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20964, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在书店买了一只印刷品。", "corrected_sentence": "我在书店买了一份印刷品。", "error_description": "“印刷品”是纸制品，数量用“份”或“批”，不用“只”。错误句“一只印刷品”应改为“一份印刷品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6975c98-7307-4301-ade2-83f350f6a7f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20964, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那只旧印刷品都卖掉了。", "corrected_sentence": "他把那份旧印刷品都卖掉了。", "error_description": "“印刷品”是纸制品，量词用“份”，不用“只”。错误句“那只旧印刷品”应改为“那份旧印刷品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6975c98-7307-4301-ade2-83f350f6a7f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20966, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
