INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20966, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一只脚抬起来，迈过一样东西。", "primary_collocate": null, "pronunciation": "kuà", "ipa": "kʰua˥˩", "syllable_count": 1, "sentences": [{"text": "他一步跨过了小河。", "target_word": "跨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有水，请跨过去。", "target_word": "跨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跨进教室，大家都笑了。", "target_word": "跨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗太小，跨不过那条沟。", "target_word": "跨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抬起腿，跨上了自行车。", "target_word": "跨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跨出家门，往学校走去。", "target_word": "跨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷腿不好，跨不了高的台阶。", "target_word": "跨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子小心地跨过了门槛。", "target_word": "跨", "complexity_tier": "T3", "furigana": "hái zi xiǎo xīn de kuà guò le mén kǎn", "sentence_source": "generated"}, {"text": "他把脚一跨，就上了车。", "target_word": "跨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有一根木头，我跨过去了。", "target_word": "跨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跨了", "label": "体标（了）"}, {"form": "跨着", "label": "体标（着）"}, {"form": "跨过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "抬起一只脚迈过或迈进某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3365f9ac-881d-493f-88dc-1a13db791d52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20966, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "跨", "is_correct": true, "explanation": "正确答案。跨（kuà）指抬起一只脚迈过一样东西。"}, {"text": "夸", "is_correct": false, "explanation": "声调不同：kuā（第一声）与 kuà（第四声），意思是称赞。"}, {"text": "垮", "is_correct": false, "explanation": "声调不同：kuǎ（第三声）与 kuà（第四声），意思是倒塌或失败。"}, {"text": "快", "is_correct": false, "explanation": "韵母不同：kuài（第四声）比 kuà 多一个 i（ai 与 a），意思是速度高。"}], "explanations": {"跨": "正确答案。跨（kuà）指抬起一只脚迈过一样东西。", "夸": "声调不同：kuā（第一声）与 kuà（第四声），意思是称赞。", "垮": "声调不同：kuǎ（第三声）与 kuà（第四声），意思是倒塌或失败。", "快": "韵母不同：kuài（第四声）比 kuà 多一个 i（ai 与 a），意思是速度高。"}, "sentence_index": null, "correct_answer": "跨"}, "level_3": {"options": [{"text": "跨", "is_correct": true, "explanation": "“一步跨过”表示一步迈过小河，与句意相符。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”是在水中划动前进，“一步”无法游过小河，句子不通。"}, {"text": "躺", "is_correct": false, "explanation": "配价：“躺”是不及物动词，不能带宾语“小河”，不说“躺过小河”。"}, {"text": "爬", "is_correct": false, "explanation": "语义：“爬”需要慢慢手脚并用前进，与“一步”矛盾，句子不通。"}], "explanations": {"跨": "“一步跨过”表示一步迈过小河，与句意相符。", "游": "语义：“游”是在水中划动前进，“一步”无法游过小河，句子不通。", "躺": "配价：“躺”是不及物动词，不能带宾语“小河”，不说“躺过小河”。", "爬": "语义：“爬”需要慢慢手脚并用前进，与“一步”矛盾，句子不通。"}, "sentence_index": 0, "correct_answer": "跨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跨过了一顿饭，又去打球了。", "explanation": "这里应该用〈吃〉。“跨过”指迈过具体的障碍，不能用于吃饭，应说“吃了一顿饭”。"}, {"text": "他一个人在医院跨了那碗药。", "explanation": "这里应该用〈喝〉。“跨”指迈过障碍，不能带“药”作宾语，应说“喝了那碗药”。"}, {"text": "一阵风跨过了平静的湖面。", "explanation": "这里应该用〈掠过〉。“掠过”指轻快地从表面经过，风吹过湖面要说“掠过”，“跨过”强调抬脚迈过障碍，不能用于风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20966, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "跨", "is_correct": true, "explanation": "正确答案。跨（kuà）指抬起一只脚迈过一样东西。"}, {"text": "裤", "is_correct": false, "explanation": "韵母不同：kù（第四声）与 kuà 的韵母 u 与 ua 不同，意思是裤子。"}, {"text": "扩", "is_correct": false, "explanation": "韵母不同：kuò（第四声）与 kuà 的韵母 uo 与 ua 不同，意思是扩大。"}, {"text": "块", "is_correct": false, "explanation": "韵母不同：kuài（第四声）与 kuà 的韵母 ai 与 a 不同，意思是块状物。"}], "explanations": {"跨": "正确答案。跨（kuà）指抬起一只脚迈过一样东西。", "裤": "韵母不同：kù（第四声）与 kuà 的韵母 u 与 ua 不同，意思是裤子。", "扩": "韵母不同：kuò（第四声）与 kuà 的韵母 uo 与 ua 不同，意思是扩大。", "块": "韵母不同：kuài（第四声）与 kuà 的韵母 ai 与 a 不同，意思是块状物。"}, "sentence_index": null, "correct_answer": "跨"}, "level_3": {"options": [{"text": "跨", "is_correct": true, "explanation": "“跨不了”表示腿脚迈不过高台阶，与句意相符。"}, {"text": "飞", "is_correct": false, "explanation": "语义：“飞”指在空中移动，与台阶无关，“飞不了高的台阶”句意荒谬。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指吃东西，与台阶无关，句子不通。"}, {"text": "扶", "is_correct": false, "explanation": "语义：“扶”指用手支撑人或物，不表示迈过台阶，句子不通。"}], "explanations": {"跨": "“跨不了”表示腿脚迈不过高台阶，与句意相符。", "飞": "语义：“飞”指在空中移动，与台阶无关，“飞不了高的台阶”句意荒谬。", "吃": "语义：“吃”指吃东西，与台阶无关，句子不通。", "扶": "语义：“扶”指用手支撑人或物，不表示迈过台阶，句子不通。"}, "sentence_index": 6, "correct_answer": "跨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跨着书包走进教室。", "explanation": "这里应该用〈挎〉。“挎”指把东西挂在胳膊上，与“跨”同音但意思不同，“跨”不能带“书包”作宾语。"}, {"text": "放假时我跨了一碗面，停下来吃了。", "explanation": "这里应该用〈端〉。“跨”指迈过障碍，不能带“面”作宾语，端一碗面要说“端”。"}, {"text": "他把那道数学题跨进了本子里，终于松了一口气。", "explanation": "这里应该用〈抄〉。“跨进”指抬脚进入某处，不能用于题目进入本子，应说“抄进本子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他轻轻跨了门口的石头。", "corrected_sentence": "他轻轻跨过了门口的石头。", "error_description": "补语缺失：“跨”表示迈过障碍物时要带结果补语“过”，应说“跨过”，“跨了石头”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一抬脚，就过跨了那道门槛。", "corrected_sentence": "他一抬脚，就跨过了那道门槛。", "error_description": "语序错误：“跨”与结果补语“过”的顺序颠倒，应说“跨过”，不能说“过跨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
