INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20970, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b11c6d02-1c2e-4ccf-827c-3efbae0b1aae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20970, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很久以前，一些人觉得教会做的事情不对，就想要改变它，这叫做宗教改革。", "primary_collocate": null, "pronunciation": "zōng jiào gǎi gé", "ipa": "tsʊŋ˥˥ tɕjɑʊ̯˥˩ kai̯˨˩˦ kɤ˧˥", "syllable_count": 4, "sentences": [{"text": "宗教改革是欧洲很久以前的大事。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，宗教改革改变了教会。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人觉得教会不对，就开始了宗教改革。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书里读到了关于宗教改革的内容。", "target_word": "宗教改革", "complexity_tier": "T3", "furigana": "wǒ zài shū lǐ dú dào le guān yú zōng jiào gǎi gé de nèi róng", "sentence_source": "generated"}, {"text": "宗教改革以后，出现了新教。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事和宗教改革有关。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对宗教改革很有兴趣。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天学了宗教改革。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宗教改革发生在很久以前。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宗教改革让很多人有了新想法。", "target_word": "宗教改革", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宗教改革运动", "label": "复合"}], "register": "中性", "sense_fingerprint": "很久以前有人觉得教会不对而要改变教会的历史事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49c86a1a-5204-4936-87bc-89eede9ea748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20970, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外卖", "is_correct": false, "explanation": "语义：外卖是近代以后才有的服务，与“很久以前”的时间矛盾。"}, {"text": "宗教改革", "is_correct": true, "explanation": "正确：指很久以前欧洲人反对教会、要求改变教会的历史事件，可以称为“大事”。"}, {"text": "八卦", "is_correct": false, "explanation": "语义：八卦指闲话、传闻，不是可以称为“大事”的历史事件，句子不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是现代产品，很久以前的欧洲并不存在，句子不通。"}], "explanations": {"外卖": "语义：外卖是近代以后才有的服务，与“很久以前”的时间矛盾。", "宗教改革": "正确：指很久以前欧洲人反对教会、要求改变教会的历史事件，可以称为“大事”。", "八卦": "语义：八卦指闲话、传闻，不是可以称为“大事”的历史事件，句子不通。", "手机": "语义：手机是现代产品，很久以前的欧洲并不存在，句子不通。"}, "sentence_index": 0, "correct_answer": "宗教改革"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在书里读到了一只宗教改革。", "explanation": "这里应该用〈场〉。〈只〉用于动物，“宗教改革”这类运动要用〈场〉。"}, {"text": "我昨天吃了一顿宗教改革。", "explanation": "这里应该用〈饭〉。宗教改革是历史事件，不是食物，不能用“吃”。"}, {"text": "工厂今年进行了一场宗教改革。", "explanation": "这里应该用〈改革〉。宗教改革指对教会做法的变革，工厂的生产调整要用〈改革〉，不能用“宗教改革”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b11c6d02-1c2e-4ccf-827c-3efbae0b1aae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20970, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "痛苦", "is_correct": false, "explanation": "语义：人一般不会对痛苦感兴趣，句子读起来自相矛盾。"}, {"text": "宗教改革", "is_correct": true, "explanation": "正确：历史事件可以成为人感兴趣的对象，与“很有兴趣”相符。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是值得感兴趣的对象，句子不通。"}, {"text": "厕所", "is_correct": false, "explanation": "搭配：“对……有兴趣”后接学科、活动或事物，不搭配场所。"}], "explanations": {"痛苦": "语义：人一般不会对痛苦感兴趣，句子读起来自相矛盾。", "宗教改革": "正确：历史事件可以成为人感兴趣的对象，与“很有兴趣”相符。", "垃圾": "语义：垃圾不是值得感兴趣的对象，句子不通。", "厕所": "搭配：“对……有兴趣”后接学科、活动或事物，不搭配场所。"}, "sentence_index": 6, "correct_answer": "宗教改革"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很厉害，是宗教改革。", "explanation": "这里应该用〈宗教改革家〉。“宗教改革”是历史事件，不能直接当作人的身份。"}, {"text": "我今天去宗教改革买菜。", "explanation": "“宗教改革”是历史事件，不是地点，不能用“去”表示前往。"}, {"text": "妈妈在超市买了宗教改革。", "explanation": "“宗教改革”是历史事件，不是商品，不能用“买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b11c6d02-1c2e-4ccf-827c-3efbae0b1aae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那时候，欧洲发生了一只宗教改革。", "corrected_sentence": "那时候，欧洲发生了一场宗教改革。", "error_description": "错误：“一只宗教改革”，应为“一场宗教改革”。“只”用于动物，宗教改革应用量词“场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b11c6d02-1c2e-4ccf-827c-3efbae0b1aae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们把宗教改革介绍很详细。", "corrected_sentence": "同学们把宗教改革介绍得很详细。", "error_description": "错误：补语“详细”前缺少“得”，应为“介绍得很详细”。动词与补语之间要用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b11c6d02-1c2e-4ccf-827c-3efbae0b1aae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
