INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20974, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20974, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "喜欢想问题、有自己想法的人。", "primary_collocate": null, "pronunciation": "sī xiǎng jiā", "ipa": "sɿ˥ ɕjɑŋ˨˩ tɕja˥", "syllable_count": 3, "sentences": [{"text": "我弟弟是个小思想家，总爱问为什么。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就爱想问题，大家都叫她思想家。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子像个小思想家，坐着想了一下午。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同桌是班里的思想家，什么事都有自己的看法。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别看他年纪小，已经是个思想家了。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸笑着说我是家里的思想家。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友是个思想家，遇到事总要先想一想。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她像个思想家一样，对每件事都有自己的想法。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明不爱说话，却是我们班的思想家。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做思想家很好，但也要多去外面玩。", "target_word": "思想家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}], "register": "口语", "sense_fingerprint": "日常说法，指爱动脑筋、凡事有自己想法的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcb27e5f-444c-42a7-80fe-3a6d050e1591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20974, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不会说话、提问，不能指爱问为什么的孩子。"}, {"text": "思想家", "is_correct": true, "explanation": "“小思想家”口语指爱动脑筋、凡事有自己想法的孩子，与“总爱问为什么”一致。"}, {"text": "雨伞", "is_correct": false, "explanation": "配价：“总爱问为什么”要求有思考能力的人作主语，雨伞不能作施事。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象是动物，不能用“小思想家”指我弟弟。"}], "explanations": {"石头": "语义：石头不会说话、提问，不能指爱问为什么的孩子。", "思想家": "“小思想家”口语指爱动脑筋、凡事有自己想法的孩子，与“总爱问为什么”一致。", "雨伞": "配价：“总爱问为什么”要求有思考能力的人作主语，雨伞不能作施事。", "大象": "语义：大象是动物，不能用“小思想家”指我弟弟。"}, "sentence_index": 0, "correct_answer": "思想家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我同桌是班里的思想家，每次开车送我上学。", "explanation": "用词错误：这里应该用〈司机〉。思想家指爱动脑筋、有自己看法的人，不指开车的人。"}, {"text": "我同桌是班里的思想家，什么事都不愿动脑子，总是照着别人抄。", "explanation": "义项矛盾：“思想家”指爱动脑筋的人，与“什么事都不愿动脑子”直接相反；这里应说〈懒虫〉。"}, {"text": "我同桌是班里的思想家，凡事都不拿主意，总是跟着别人走。", "explanation": "义项矛盾：“思想家”指有自己想法的人，与“凡事都不拿主意”直接相反；这里应说〈跟屁虫〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不会“遇到事先想一想”。"}, {"text": "思想家", "is_correct": true, "explanation": "“思想家”指爱动脑筋、有自己想法的人，与后句“遇到事总要先想一想”一致。"}, {"text": "闹钟", "is_correct": false, "explanation": "配价：“想一想”要求有思考能力的人作主语，闹钟不能作施事。"}, {"text": "懒虫", "is_correct": false, "explanation": "语义：“懒虫”指懒惰的人，与“遇到事总要先想一想”的意思相反。"}], "explanations": {"冰箱": "语义：冰箱是家用电器，不会“遇到事先想一想”。", "思想家": "“思想家”指爱动脑筋、有自己想法的人，与后句“遇到事总要先想一想”一致。", "闹钟": "配价：“想一想”要求有思考能力的人作主语，闹钟不能作施事。", "懒虫": "语义：“懒虫”指懒惰的人，与“遇到事总要先想一想”的意思相反。"}, "sentence_index": 6, "correct_answer": "思想家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的小狗是个小思想家，总爱汪汪叫。", "explanation": "语义：“思想家”只用于指人，不能用于小狗；这里应说〈淘气〉。"}, {"text": "这几个小思想家从来不愿想问题，只顾着玩游戏。", "explanation": "义项矛盾：“思想家”指爱想问题的人，“从来不愿想问题”与之直接相反；这里应说〈小玩家〉。"}, {"text": "周末我们去思想家玩。", "explanation": "语义：“思想家”指人，不能作为去玩的地点；去玩的地方应说〈公园〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的朋友是个真正得思想家，凡事都要先弄明白。", "corrected_sentence": "我的朋友是个真正的思想家，凡事都要先弄明白。", "error_description": "助词错误：修饰“思想家”的定语应用“的”，不能用“得”。“得”引出补语，“真正得思想家”说不通，应说“真正的思想家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹像只小思想家一样，坐在窗前想了很久。", "corrected_sentence": "妹妹像个小思想家一样，坐在窗前想了很久。", "error_description": "量词错误：“思想家”指人，应用“个”计量；“只”只用于动物或成对物品中的一个，不能用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
