INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20980, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "教小孩子开始学知识。", "primary_collocate": null, "pronunciation": "qǐ méng", "ipa": "tɕʰi˨˩˦ mɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "奶奶用儿歌启蒙小孙女。", "target_word": "启蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小跟着外公学写字，外公启蒙了他。", "target_word": "启蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在孩子上学前先启蒙他数数。", "target_word": "启蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐常给弟弟读书，启蒙他认字。", "target_word": "启蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套图画书可以启蒙三岁的孩子。", "target_word": "启蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天晚上启蒙女儿学拼音。", "target_word": "启蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幼儿园的老师正在启蒙小朋友唱歌。", "target_word": "启蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的字是爷爷启蒙的。", "target_word": "启蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带孩子看动物，启蒙他认识世界。", "target_word": "启蒙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师启蒙过很多农村的孩子。", "target_word": "启蒙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "启蒙教育", "label": "复合"}, {"form": "启蒙老师", "label": "复合"}], "register": "中性", "sense_fingerprint": "教小孩子开始学知识", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e245a58-1dc2-40c3-b6f0-b46e940614ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20980, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "启蒙", "is_correct": true, "explanation": "正确。“奶奶用儿歌启蒙小孙女”指用儿歌教小孩子开始学知识。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车、船等交通工具，不能用于小孙女。"}, {"text": "处罚", "is_correct": false, "explanation": "语义：“处罚”是惩戒，与用儿歌教孩子的语境相反。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：“修剪”指剪去多余的枝叶，不能用于教育小孙女。"}], "explanations": {"启蒙": "正确。“奶奶用儿歌启蒙小孙女”指用儿歌教小孩子开始学知识。", "驾驶": "搭配：“驾驶”的对象是车、船等交通工具，不能用于小孙女。", "处罚": "语义：“处罚”是惩戒，与用儿歌教孩子的语境相反。", "修剪": "语义：“修剪”指剪去多余的枝叶，不能用于教育小孙女。"}, "sentence_index": 0, "correct_answer": "启蒙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "园丁每天启蒙花木。", "explanation": "这里应该用〈培育〉。启蒙的对象是小孩子这类学习者，不能用于植物。"}, {"text": "这位教授启蒙过许多博士生。", "explanation": "这里应该用〈指导〉。启蒙针对初学者，博士生已有较深的专业基础，应说指导。"}, {"text": "朋友常常启蒙我，带我去吃火锅。", "explanation": "这里应该用〈请〉。启蒙指教给初学者知识，不指请客吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6975c98-7307-4301-ade2-83f350f6a7f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20980, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "启蒙", "is_correct": true, "explanation": "正确。“幼儿园的老师正在启蒙小朋友唱歌”指老师正在教小朋友开始学唱歌。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：“批改”用于作业、试卷，不能用于唱歌。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉建筑、设施，与唱歌无关。"}, {"text": "修补", "is_correct": false, "explanation": "语义：“修补”指修理破损之物，不能用于教小朋友唱歌。"}], "explanations": {"启蒙": "正确。“幼儿园的老师正在启蒙小朋友唱歌”指老师正在教小朋友开始学唱歌。", "批改": "搭配：“批改”用于作业、试卷，不能用于唱歌。", "拆除": "语义：“拆除”指拆掉建筑、设施，与唱歌无关。", "修补": "语义：“修补”指修理破损之物，不能用于教小朋友唱歌。"}, "sentence_index": 6, "correct_answer": "启蒙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "哥哥总是启蒙弟弟抽烟。", "explanation": "这里应该用〈教唆〉。启蒙是教给初学者正当的知识，不能用于怂恿他人做坏事。"}, {"text": "数学老师启蒙公式。", "explanation": "这里应该用〈讲解〉。启蒙的对象是学习者，“公式”不能作为教导的对象。"}, {"text": "奶奶启蒙我长大。", "explanation": "这里应该用〈抚养〉。启蒙指教给初学者知识，不能用于生活上的照顾和养育。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6975c98-7307-4301-ade2-83f350f6a7f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶每天启蒙了孙女认字。", "corrected_sentence": "奶奶每天启蒙孙女认字。", "error_description": "“每天”表示经常性、重复的动作，与表示完成的“了”不搭配；错误句“每天启蒙了孙女认字”应删去“了”，改为“每天启蒙孙女认字”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6975c98-7307-4301-ade2-83f350f6a7f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "幼儿园的老师每天把启蒙小朋友认字。", "corrected_sentence": "幼儿园的老师每天启蒙小朋友认字。", "error_description": "“把”字句的“把”后要接受事名词，“启蒙”不能直接跟在“把”后。错误形式是“把启蒙小朋友认字”，正确形式是“启蒙小朋友认字”，删去“把”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6975c98-7307-4301-ade2-83f350f6a7f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
