INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20982, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西慢慢变出来，或者事情慢慢有了。", "primary_collocate": null, "pronunciation": "xíng chéng", "ipa": "ɕiŋ˧˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "好习惯要慢慢形成。", "target_word": "形成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "云是怎么形成的？", "target_word": "形成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水带来泥沙，形成了一块平地。", "target_word": "形成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候的生活形成了他的性格。", "target_word": "形成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里形成了一个新的小城市。", "target_word": "形成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了一夜雪，路上形成了冰。", "target_word": "形成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的看法已经形成了。", "target_word": "形成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的水流到一起，形成了大河。", "target_word": "形成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的看法是在国外形成的。", "target_word": "形成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书，才能形成自己的想法。", "target_word": "形成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "形成了", "label": "体标"}, {"form": "形成过", "label": "体标"}], "register": "中性", "sense_fingerprint": "事物或情况经过一段时间逐渐出现、成型", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 河水 (Zipf 3.84), 泥沙 (Zipf 3.43), 平地 (Zipf 3.52)','sentence 7 above tier T1: 3 words above tier T1 (max 2): 山里 (Zipf 3.64), 水流 (Zipf 3.89), 大河 (Zipf 3.59)']::text[], 'f35b906f-46d6-4de6-ad17-6696c52b793f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "形成", "is_correct": true, "explanation": "正确：“形成”指逐渐出现或成型，与“慢慢”和“好习惯”相符。"}, {"text": "消失", "is_correct": false, "explanation": "语义：“好习惯”应当“慢慢形成”，“消失”与“好”的积极含义相反。"}, {"text": "断绝", "is_correct": false, "explanation": "语义：“断绝”指切断联系，好习惯不能“慢慢断绝”，搭配不通。"}, {"text": "发生", "is_correct": false, "explanation": "语义：“发生”多指事件出现，不用于描述“好习惯”的养成。"}], "explanations": {"形成": "正确：“形成”指逐渐出现或成型，与“慢慢”和“好习惯”相符。", "消失": "语义：“好习惯”应当“慢慢形成”，“消失”与“好”的积极含义相反。", "断绝": "语义：“断绝”指切断联系，好习惯不能“慢慢断绝”，搭配不通。", "发生": "语义：“发生”多指事件出现，不用于描述“好习惯”的养成。"}, "sentence_index": 0, "correct_answer": "形成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们形成了一座大桥。", "explanation": "这里应该用〈建造〉。“形成”指东西慢慢出现或事情逐渐有了，不用于人工建造大型建筑；建桥要说“建造”。"}, {"text": "他形成了一碗饭。", "explanation": "这里应该用〈做〉。“形成”的对象是事情或情况，不能用于做具体的食物。"}, {"text": "这位老师形成了很多学生。", "explanation": "这里应该用〈培养〉。“形成”不用于培养人，应说“培养”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "形成", "is_correct": true, "explanation": "正确：“大家的看法已经形成了”，“形成”表示看法逐渐成型，与“已经”相符。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”指液体变成固体，不能用于“看法”。"}, {"text": "卖出", "is_correct": false, "explanation": "搭配：“卖出”的对象是商品，不能用于“看法”。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”指物体被火毁坏，与“看法”的语境不合。"}], "explanations": {"形成": "正确：“大家的看法已经形成了”，“形成”表示看法逐渐成型，与“已经”相符。", "结冰": "语义：“结冰”指液体变成固体，不能用于“看法”。", "卖出": "搭配：“卖出”的对象是商品，不能用于“看法”。", "烧毁": "语义：“烧毁”指物体被火毁坏，与“看法”的语境不合。"}, "sentence_index": 6, "correct_answer": "形成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爱迪生形成了灯泡。", "explanation": "这里应该用〈发明〉。“形成”表示慢慢出现，不指创造新物品，应说“发明”。"}, {"text": "作家形成了一部小说。", "explanation": "这里应该用〈创作〉。“形成”不用于作品的写作，应说“创作”。"}, {"text": "他形成了一本书。", "explanation": "这里应该用〈写〉。“形成”不用于写书，应说“写了一本书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种习惯正在形成过。", "corrected_sentence": "这种习惯正在形成。", "error_description": "“正在”表示动作正在进行，不能与表示经历过的“过”同用，应去掉“过”，说“这种习惯正在形成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套规则在长期实践中慢慢形成了过。", "corrected_sentence": "这套规则在长期实践中慢慢形成了。", "error_description": "体标语序错误：“了”与“过”不能这样排列，应去掉“过”，说“慢慢形成了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
