INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20984, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个东西动，另一个跟着动。", "primary_collocate": null, "pronunciation": "gòng zhèn", "ipa": "kʊŋ˥˩ ʈʂən˥˩", "syllable_count": 2, "sentences": [{"text": "桌子上的杯子因共振而发出了声音。", "target_word": "共振", "complexity_tier": "T3", "furigana": "gòng zhèn", "sentence_source": "generated"}, {"text": "吉他弦一响，另一把吉他就产生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车开过，窗户出现了共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他敲了一下鼓，旁边的鼓发生了共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个钟摆挂在一起，会发生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机一响，桌子上的盒子发生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩在桥上跳，桥面出现了共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器一开，墙就发生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弹了一下琴弦，另一根弦发生了共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车经过时，房子里的杯子发生共振。", "target_word": "共振", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "共振频率", "label": "复合"}, {"form": "磁共振", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个物体振动，另一个物体跟着振动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0791d15f-9964-414f-b98b-e2f51390c435') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20984, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "共振", "is_correct": true, "explanation": "正确：杯子因同频振动而跟着振动，才会发出声音，“共振”正合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色本身不会引起振动，“因颜色而发出声音”不符合事实。"}, {"text": "香气", "is_correct": false, "explanation": "搭配：“香气”不能作为杯子发出声音的原因，词语之间搭配不通。"}, {"text": "光照", "is_correct": false, "explanation": "语义：光照一般不会使杯子发出声音，句中的原因应指振动。"}], "explanations": {"共振": "正确：杯子因同频振动而跟着振动，才会发出声音，“共振”正合句意。", "颜色": "语义：颜色本身不会引起振动，“因颜色而发出声音”不符合事实。", "香气": "搭配：“香气”不能作为杯子发出声音的原因，词语之间搭配不通。", "光照": "语义：光照一般不会使杯子发出声音，句中的原因应指振动。"}, "sentence_index": 0, "correct_answer": "共振"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他敲了一下鼓，旁边的鼓纹丝共振。", "explanation": "这里应该用〈纹丝不动〉。纹丝不动指一点也不晃动；共振指另一物跟着振动，与“不动”的意思正好相反，句中用错了。"}, {"text": "他敲了一下鼓，鼓槌共振飞了。", "explanation": "这里应该用〈弹飞〉。弹飞指被撞击后弹出去；共振指物体跟着同频振动，不表示位置的移动。"}, {"text": "我按下开关，灯就共振了。", "explanation": "这里应该用〈亮起〉。亮起指灯光开始发亮；共振指物体跟着振动，不表示灯光亮起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "共振", "is_correct": true, "explanation": "正确：小孩在桥上跳，桥面因同频振动而跟着振动，即共振。"}, {"text": "星光", "is_correct": false, "explanation": "语义：星光是天体发出的光，与桥面的振动无关，句中的现象不会因此出现。"}, {"text": "芳香", "is_correct": false, "explanation": "语义：桥面因小孩跳跃不会产生芳香，这一现象与振动无关。"}, {"text": "鸟鸣", "is_correct": false, "explanation": "搭配：“出现”一般不接“鸟鸣”，桥面也不会因跳跃而出现鸟的叫声。"}], "explanations": {"共振": "正确：小孩在桥上跳，桥面因同频振动而跟着振动，即共振。", "星光": "语义：星光是天体发出的光，与桥面的振动无关，句中的现象不会因此出现。", "芳香": "语义：桥面因小孩跳跃不会产生芳香，这一现象与振动无关。", "鸟鸣": "搭配：“出现”一般不接“鸟鸣”，桥面也不会因跳跃而出现鸟的叫声。"}, "sentence_index": 6, "correct_answer": "共振"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "杯子因为摔落而共振了。", "explanation": "这里应该用〈破碎〉。破碎指物体摔成碎块；共振是物体因同频振动而振幅增大，不会因摔落而使杯子碎裂，这里用错了。"}, {"text": "这台机器一开，桌子上的盒子共振到了地上。", "explanation": "这里应该用〈掉落〉。掉落指物体失去支撑而落下；共振指物体因同频振动而振幅增大，不表示位置的移动。"}, {"text": "他感冒了，一直共振。", "explanation": "这里应该用〈咳嗽〉。咳嗽指喉咙受刺激而急促地出气；共振指物体因同频振动而振幅增大，不能用来形容人的身体反应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "卡车经过时，窗户正在共振了。", "corrected_sentence": "卡车经过时，窗户正在共振。", "error_description": "体标错误：“正在”表示动作进行中，不能与“了”同用，应删去“了”。错误形式为“正在共振了”，正确形式为“正在共振”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "卡车经过时，窗户就会很共振。", "corrected_sentence": "卡车经过时，窗户就会共振。", "error_description": "副词「很」不能修饰动词「共振」，应删去「很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bea323cf-7c6c-4db7-9b65-b29244c1c14b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20986, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20986, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20986, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大家一起管理国家。", "primary_collocate": null, "pronunciation": "gòng hé", "ipa": "kʊŋ˥˩ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "厉王出奔后，周召二公共和执政。", "target_word": "共和", "complexity_tier": "T3", "furigana": "Lì wáng chū bēn hòu, Zhōu Shào èr gōng gòng hé zhí zhèng.", "sentence_source": "generated"}, {"text": "史书记载，那段时间由两位大臣共和执政。", "target_word": "共和", "complexity_tier": "T3", "furigana": "Shǐ shū jì zǎi, nà duàn shí jiān yóu liǎng wèi dà chén gòng hé zhí zhèng.", "sentence_source": "generated"}, {"text": "诸侯议定，暂时共和执政，不再立国君。", "target_word": "共和", "complexity_tier": "T3", "furigana": "Zhū hóu yì dìng, zàn shí gòng hé zhí zhèng, bù zài lì guó jūn.", "sentence_source": "generated"}, {"text": "他们主张共和执政，反对一人专权。", "target_word": "共和", "complexity_tier": "T3", "furigana": "Tā men zhǔ zhāng gòng hé zhí zhèng, fǎn duì yì rén zhuān quán.", "sentence_source": "generated"}, {"text": "两人共和执政，权力彼此制衡。", "target_word": "共和", "complexity_tier": "T3", "furigana": "Liǎng rén gòng hé zhí zhèng, quán lì bǐ cǐ zhì héng.", "sentence_source": "generated"}, {"text": "几位长老有时共和执政，互相牵制。", "target_word": "共和", "complexity_tier": "T3", "furigana": "Jǐ wèi zhǎng lǎo yǒu shí gòng hé zhí zhèng, hù xiāng qiān zhì.", "sentence_source": "generated"}, {"text": "史家认为，那是一段共和执政的时期。", "target_word": "共和", "complexity_tier": "T3", "furigana": "Shǐ jiā rèn wéi, nà shì yí duàn gòng hé zhí zhèng de shí qī.", "sentence_source": "generated"}, {"text": "他们约定共同治理国事，这就是共和执政。", "target_word": "共和", "complexity_tier": "T3", "furigana": "Tā men yuē dìng gòng tóng zhì lǐ guó shì, zhè jiù shì gòng hé zhí zhèng.", "sentence_source": "generated"}, {"text": "政局动荡之时，只得共和执政，维持秩序。", "target_word": "共和", "complexity_tier": "T3", "furigana": "Zhèng jú dòng dàng zhī shí, zhǐ dé gòng hé zhí zhèng, wéi chí zhì xù.", "sentence_source": "generated"}, {"text": "城邦之间若能共和执政，便可减少争端。", "target_word": "共和", "complexity_tier": "T3", "furigana": "Chéng bāng zhī jiān ruò néng gòng hé zhí zhèng, biàn kě jiǎn shǎo zhēng duān.", "sentence_source": "generated"}], "morphological_forms": [{"form": "共和制", "label": "复合"}, {"form": "共和国", "label": "复合"}], "register": "书面语", "sense_fingerprint": "不由君主一人说了算，而是大家一起管理国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcb27e5f-444c-42a7-80fe-3a6d050e1591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20986, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "独裁", "is_correct": false, "explanation": "语义：“独裁”指一人专断，与“周召二公”两人并列执政矛盾。"}, {"text": "共和", "is_correct": true, "explanation": "“共和执政”指多人共同管理国家，这里指周公与召公二人共同执政。"}, {"text": "出奔", "is_correct": false, "explanation": "语义：“出奔”指逃离国都，与“执政”不能同时成立。"}, {"text": "投降", "is_correct": false, "explanation": "配价：“投降”不能带“执政”作宾语，“周召二公投降执政”说不通。"}], "explanations": {"独裁": "语义：“独裁”指一人专断，与“周召二公”两人并列执政矛盾。", "共和": "“共和执政”指多人共同管理国家，这里指周公与召公二人共同执政。", "出奔": "语义：“出奔”指逃离国都，与“执政”不能同时成立。", "投降": "配价：“投降”不能带“执政”作宾语，“周召二公投降执政”说不通。"}, "sentence_index": 0, "correct_answer": "共和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两人的共和很默契，一起完成了任务。", "explanation": "义项错误：这里应该用〈团结〉。“共和”指共同管理国家，不指一般的团结或默契。"}, {"text": "他一个人共和执政，不许别人参与。", "explanation": "语义：“共和执政”指多人共同管理国家，“一个人”与之矛盾；只有一人执政应说〈独自执政〉。"}, {"text": "两人共和经营店铺，生意很好。", "explanation": "义项错误：这里应该用〈合伙〉。“共和”只用于共同管理国家，经营店铺应说〈合伙〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逃亡", "is_correct": false, "explanation": "语义：“逃亡”指离开本国躲避，与“执政的时期”不能搭配。"}, {"text": "共和", "is_correct": true, "explanation": "“共和执政的时期”指多人共同管理国家的时期，与句中“史家认为”的历史叙述一致。"}, {"text": "罢工", "is_correct": false, "explanation": "语义：“罢工”指停止工作，不能修饰“执政的时期”。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，不能带“执政”这样的对象，句子接不下去。"}], "explanations": {"逃亡": "语义：“逃亡”指离开本国躲避，与“执政的时期”不能搭配。", "共和": "“共和执政的时期”指多人共同管理国家的时期，与句中“史家认为”的历史叙述一致。", "罢工": "语义：“罢工”指停止工作，不能修饰“执政的时期”。", "游泳": "配价：“游泳”是不及物动词，不能带“执政”这样的对象，句子接不下去。"}, "sentence_index": 6, "correct_answer": "共和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "城邦之间若能共和做饭，便可减少争端。", "explanation": "用词错误：这里应该用〈合作〉。“共和”只用于共同管理国家，不能用于做饭等日常事务。"}, {"text": "这座山若能共和执政，便可减少争端。", "explanation": "语义：“共和执政”指人共同管理国家，不能以山这类事物作主语；这里应指〈大臣〉。"}, {"text": "城邦之间若能共和商店，便可减少争端。", "explanation": "语义：“共和”只用于共同治理国家，不能支配“商店”这类事物；这里应说“经营”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那几年里，两位大臣共和得执政，维持朝政。", "corrected_sentence": "那几年里，两位大臣共和执政，维持朝政。", "error_description": "助词错误：“得”引出补语，不能用在“共和”和“执政”之间，应去掉“得”，说“共和执政”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那段历史上，两位大臣曾经共和执政了。", "corrected_sentence": "那段历史上，两位大臣曾经共和执政过。", "error_description": "体标错误：表示经历应与“过”搭配，说“曾经共和执政过”；“了”表示完成，无时段成分时与“曾经”搭配不自然（“曾经…了一段时间”则可以）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
