INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20988, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20988, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人们把想说的话写在纸上，寄给别人，这种写下来的话就叫书信。", "primary_collocate": null, "pronunciation": "shū xìn", "ipa": "ʂu˥ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "我想给远方的朋友写一封书信。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的抽屉里放着一些旧书信。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书信写在纸上，要寄出去才行。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前人们常常用书信说心里话。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我收到了姐姐从国外寄来的书信。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天等着邮递员送来书信。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封书信写得很长，有三页纸。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么写书信。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把想说的话都写进了书信里。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈读完书信，笑了起来。", "target_word": "书信", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "封", "label": "量词"}, {"form": "书信集", "label": "复合"}], "register": "中性", "sense_fingerprint": "把想说的话写在纸上寄给别人的文字，即信件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcb27e5f-444c-42a7-80fe-3a6d050e1591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20988, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书信", "is_correct": true, "explanation": "正确：书信指写给亲友的书面信件，与“写一封”和“远方的朋友”相符。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能说“写一封礼物”。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不是寄给远方朋友的信。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“写”不能搭配“手机”，手机不是可以书写的文字。"}], "explanations": {"书信": "正确：书信指写给亲友的书面信件，与“写一封”和“远方的朋友”相符。", "礼物": "搭配：“写”的对象是文字，不能说“写一封礼物”。", "作业": "语义：作业是学习任务，不是寄给远方朋友的信。", "手机": "搭配：“写”不能搭配“手机”，手机不是可以书写的文字。"}, "sentence_index": 0, "correct_answer": "书信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站在台上唱书信。", "explanation": "这里应该用〈歌〉。唱的是歌，书信要写、寄、读。"}, {"text": "电视没有书信，画面是黑的。", "explanation": "这里应该用〈信号〉。电视画面黑是因为没有信号，书信是写在纸上寄送的信件，和电视无关。"}, {"text": "他每天晚上都给朋友打书信。", "explanation": "这里应该用〈电话〉。打的是电话，书信要写或寄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20988, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书信", "is_correct": true, "explanation": "正确：书信可以写得很长、有好几页纸，与句子描述相符。"}, {"text": "大衣", "is_correct": false, "explanation": "搭配：“写”不能搭配“大衣”，衣服不能“写得很长”。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是图形资料，不是可以写得很长的书面信件。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不能“写得很长”，与“三页纸”也对不上。"}], "explanations": {"书信": "正确：书信可以写得很长、有好几页纸，与句子描述相符。", "大衣": "搭配：“写”不能搭配“大衣”，衣服不能“写得很长”。", "地图": "语义：地图是图形资料，不是可以写得很长的书面信件。", "蛋糕": "语义：蛋糕是食物，不能“写得很长”，与“三页纸”也对不上。"}, "sentence_index": 6, "correct_answer": "书信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "回家后，我要把书信拿去报销。", "explanation": "这里应该用〈发票〉。报销的是发票，书信是写给亲友的信件，不能拿去报销。"}, {"text": "他用微信给朋友发书信，很快就收到了回复。", "explanation": "这里应该用〈消息〉。微信发的是消息，书信是写在纸上寄出去的。"}, {"text": "他急忙拍书信求救。", "explanation": "这里应该用〈电报〉。拍的是电报，书信不能拍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶把一个书信放进了抽屉。", "corrected_sentence": "奶奶把一封书信放进了抽屉。", "error_description": "量词错误：书信的量词是“封”，“个”不能用于书信。应说“一封书信”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些旧书信我全都读了完。", "corrected_sentence": "这些旧书信我全都读完了。", "error_description": "补语位置错误：结果补语“完”应紧跟动词“读”，说“读完了”，不能说“读了完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
