INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20990, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个国家就是一个地方，有很多很多人住在一起，有一个政府来管理。", "primary_collocate": null, "pronunciation": "guó jiā", "ipa": "kuo˧˥ tɕia˥", "syllable_count": 2, "sentences": [{"text": "中国是一个很大的国家。", "target_word": "国家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你去过几个国家？", "target_word": "国家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的冬天很冷。", "target_word": "国家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个国家都有自己的语言。", "target_word": "国家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家给孩子们建了新学校。", "target_word": "国家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去很多国家看一看。", "target_word": "国家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是哪个国家的人？", "target_word": "国家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家有一千多万人。", "target_word": "国家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱自己的国家是应该的。", "target_word": "国家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个国家的人坐在一起吃饭。", "target_word": "国家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "國家", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有土地、人民和政府的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d8b840b-ee01-4694-9784-5eb6724c58e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20990, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国家", "is_correct": true, "explanation": "正确：「国家」指有领土和政府的国家，与“中国是一个很大的”搭配，符合句意。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：「很大的」一般修饰可以用大小衡量的事物，不说“很大的时间”。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球是体育器材，不能把中国比作“一个很大的篮球”。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是房间，不能说中国是“一个很大的教室”。"}], "explanations": {"国家": "正确：「国家」指有领土和政府的国家，与“中国是一个很大的”搭配，符合句意。", "时间": "搭配：「很大的」一般修饰可以用大小衡量的事物，不说“很大的时间”。", "篮球": "语义：篮球是体育器材，不能把中国比作“一个很大的篮球”。", "教室": "语义：教室是房间，不能说中国是“一个很大的教室”。"}, "sentence_index": 0, "correct_answer": "国家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他住在北京这个国家，已经十年了。", "explanation": "这里应该用〈城市〉。「国家」指有领土和政府的国家，北京是城市，不能说成国家。"}, {"text": "我们国家今天去超市买菜。", "explanation": "这里应该用〈一家人〉。「国家」指有领土和政府的国家，不能指一家人，说家人一起去买菜要用〈一家人〉。"}, {"text": "这个国家一共有五个房间，我们住得很舒服。", "explanation": "这里应该用〈房子〉。「国家」指有领土和政府的地区，不能用来指房屋，说房间多少要用〈房子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20990, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国家", "is_correct": true, "explanation": "正确：「国家」指一个国家，“哪个国家的人”问的是国籍，符合句意。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格是人的特点，不能用来问人的来源，「哪个性格的人」不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能表示人的来源，「哪个颜色的人」不成立。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：「……的人」要用地方或群体名词，「星期」是时间词，不说“哪个星期的人”。"}], "explanations": {"国家": "正确：「国家」指一个国家，“哪个国家的人”问的是国籍，符合句意。", "性格": "语义：性格是人的特点，不能用来问人的来源，「哪个性格的人」不通。", "颜色": "语义：颜色不能表示人的来源，「哪个颜色的人」不成立。", "星期": "搭配：「……的人」要用地方或群体名词，「星期」是时间词，不说“哪个星期的人”。"}, "sentence_index": 6, "correct_answer": "国家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个国家只有一百户人家，大家都认识。", "explanation": "这里应该用〈村子〉。「国家」指拥有领土和政府的国家，规模太大，不能用来指只有一百户人家的地方。"}, {"text": "这个国家又高又瘦，每天都去跑步。", "explanation": "这里应该用〈女孩〉。「国家」指有领土和政府的地区，不能用来指人，“又高又瘦”和“去跑步”只能用于人。"}, {"text": "我们国家里住着六个学生，每天一起学习。", "explanation": "这里应该用〈宿舍〉。「国家」指国家，不指可以住人的房间，要用〈宿舍〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家国家的人口超过了十亿。", "corrected_sentence": "这个国家的人口超过了十亿。", "error_description": "错误：量词「家」用于商店、公司等，国家应该用「个」，即“这个国家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位国家的人很热情。", "corrected_sentence": "这个国家的人很热情。", "error_description": "错误：量词「位」用于人，国家应该用「个」，即“这个国家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
