INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21000, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "报纸和杂志合在一起，叫报刊。", "primary_collocate": null, "pronunciation": "bào kān", "ipa": "pɑʊ̯˥˩ kʰan˥", "syllable_count": 2, "sentences": [{"text": "报纸和杂志合起来叫报刊。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的报刊区在二楼。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在报刊上读到这个消息。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前人们主要靠报刊了解新闻。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报刊上的广告越来越少了。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人喜欢在公园里看报刊。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有一个报刊阅读小组。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把桌上的报刊放回架子上。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位记者常给报刊写文章。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国外的报刊也有中文版。", "target_word": "报刊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "報刊", "label": "繁体"}, {"form": "报刊亭", "label": "复合"}], "register": "中性", "sense_fingerprint": "报纸和杂志合在一起的叫法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a527533-d9b0-40ff-b560-df5dbf897fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21000, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报刊", "is_correct": true, "explanation": "报刊：报纸和杂志的合称，正是句中所定义的词。"}, {"text": "报社", "is_correct": false, "explanation": "搭配：“合起来叫”后的名称应是两者的合称，“报社”是出版机构，不能用来称呼报纸和杂志。"}, {"text": "书籍", "is_correct": false, "explanation": "语义：书籍是另一类出版物，不包括报纸，与“报纸和杂志合起来”的定义不符。"}, {"text": "广播", "is_correct": false, "explanation": "语义：广播是声音媒介，不是印刷的报纸和杂志，不能作为两者的合称。"}], "explanations": {"报刊": "报刊：报纸和杂志的合称，正是句中所定义的词。", "报社": "搭配：“合起来叫”后的名称应是两者的合称，“报社”是出版机构，不能用来称呼报纸和杂志。", "书籍": "语义：书籍是另一类出版物，不包括报纸，与“报纸和杂志合起来”的定义不符。", "广播": "语义：广播是声音媒介，不是印刷的报纸和杂志，不能作为两者的合称。"}, "sentence_index": 0, "correct_answer": "报刊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电视台每天播出很多报刊。", "explanation": "这里应该用〈报道〉。电视台播出的是节目或报道，报刊是印刷的报纸杂志，不能在电视上播出。"}, {"text": "电视上经常插播报刊。", "explanation": "这里应该用〈广告〉。插播的是广告，报刊是出版物，不能被插播。"}, {"text": "这位作家写了很多报刊。", "explanation": "这里应该用〈文章〉。“写”的对象是文章、作品，报刊是整份出版物，不能说“写报刊”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0699896b-5564-42a6-bae3-4971e7e622fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报刊", "is_correct": true, "explanation": "报刊：报纸和杂志是可以阅读的文字材料，可以组成报刊阅读小组。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“阅读”后接的应是文字材料，“音乐”不能与“阅读”搭配。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视节目是播放的影像，不是可以阅读的材料。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球是运动器材，不是可以阅读的材料。"}], "explanations": {"报刊": "报刊：报纸和杂志是可以阅读的文字材料，可以组成报刊阅读小组。", "音乐": "搭配：“阅读”后接的应是文字材料，“音乐”不能与“阅读”搭配。", "电视": "语义：电视节目是播放的影像，不是可以阅读的材料。", "篮球": "语义：篮球是运动器材，不是可以阅读的材料。"}, "sentence_index": 6, "correct_answer": "报刊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家门口有一座报刊。", "explanation": "这里应该用〈份〉。〈座〉用于山、房屋等大型固定物，报刊要用〈份〉或〈种〉来量。"}, {"text": "我的书包里有一只报刊。", "explanation": "这里应该用〈份〉。〈只〉多用于动物或成对的物品，报刊不能用〈只〉来量。"}, {"text": "他买回来一头报刊。", "explanation": "这里应该用〈份〉。〈头〉用于大型牲畜，报刊不能用〈头〉来量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0699896b-5564-42a6-bae3-4971e7e622fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天都看这棵报刊。", "corrected_sentence": "我每天都看这份报刊。", "error_description": "量词误用：“棵”用于植物，不能用来计量报刊，应用“份”。正确说法：我每天都看这份报刊。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0699896b-5564-42a6-bae3-4971e7e622fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他看了完那份报刊。", "corrected_sentence": "他看完了那份报刊。", "error_description": "补语位置错误：结果补语“完”应紧接动词“看”，“了”应放在“看完”之后。正确说法：他看完了那份报刊。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0699896b-5564-42a6-bae3-4971e7e622fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
