INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21012, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "很多人一个讲给另一个，一个又讲给下一个，这样传下去。", "primary_collocate": null, "pronunciation": "kǒu ěr xiāng chuán", "ipa": "kʰoʊ̯˨˩˦ ɚ˨˩˦ ɕjɑŋ˥ ʈʂʰwan˧˥", "syllable_count": 4, "sentences": [{"text": "老人们的故事一代又一代地口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "furigana": "lǎo rén men de gù shi yí dài yòu yí dài de kǒu ěr xiāng chuán", "sentence_source": "generated"}, {"text": "这首民歌没有谱子，全靠口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个好办法在朋友之间口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的家规不写在纸上，而是口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店的名气是口耳相传出来的。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民间药方多半是口耳相传的。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些古老的习俗至今还靠口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个笑话在学校里口耳相传，人人都知道。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅教徒弟时常常口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个传说没有书面记载，只能口耳相传。", "target_word": "口耳相传", "complexity_tier": "T3", "furigana": "zhè ge chuán shuō méi yǒu shū miàn jì zǎi, zhǐ néng kǒu ěr xiāng chuán。", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一个人讲给另一个人，一代代传下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a527533-d9b0-40ff-b560-df5dbf897fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口耳相传", "is_correct": true, "explanation": "口耳相传：靠口头讲述、一代代传下去，与“一代又一代”相符。"}, {"text": "网络直播", "is_correct": false, "explanation": "语义：“一代又一代”强调世代延续，“网络直播”是即时播出，不能表示世代流传。"}, {"text": "暂时保存", "is_correct": false, "explanation": "语义：“暂时”与“一代又一代”的长久延续相矛盾。"}, {"text": "闭门研究", "is_correct": false, "explanation": "搭配：“故事”可以讲述、流传，不说“闭门研究”。"}], "explanations": {"口耳相传": "口耳相传：靠口头讲述、一代代传下去，与“一代又一代”相符。", "网络直播": "语义：“一代又一代”强调世代延续，“网络直播”是即时播出，不能表示世代流传。", "暂时保存": "语义：“暂时”与“一代又一代”的长久延续相矛盾。", "闭门研究": "搭配：“故事”可以讲述、流传，不说“闭门研究”。"}, "sentence_index": 0, "correct_answer": "口耳相传"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份家规是他用毛笔口耳相传的。", "explanation": "这里应该用〈抄写〉。口耳相传是口头传递，用毛笔写下的家规不能用口耳相传来表示。"}, {"text": "他一个人在山上口耳相传。", "explanation": "这里应该用〈喊叫〉。口耳相传需要一人讲给另一人，不能形容一个人独自喊叫。"}, {"text": "这首曲子是他用钢琴口耳相传的。", "explanation": "这里应该用〈弹奏〉。曲子是通过乐器演奏的，不能用口耳相传来表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0699896b-5564-42a6-bae3-4971e7e622fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口耳相传", "is_correct": true, "explanation": "口耳相传：靠口头讲述代代传下来，与“古老的习俗”相符。"}, {"text": "严禁传播", "is_correct": false, "explanation": "语义：“严禁传播”与“至今还靠……”的传承意思相矛盾。"}, {"text": "出口销售", "is_correct": false, "explanation": "搭配：“习俗”是可以传承的风俗，不能与“出口销售”搭配。"}, {"text": "拆除重建", "is_correct": false, "explanation": "语义：“拆除重建”是对建筑的处理，与习俗无关，不能靠它流传下来。"}], "explanations": {"口耳相传": "口耳相传：靠口头讲述代代传下来，与“古老的习俗”相符。", "严禁传播": "语义：“严禁传播”与“至今还靠……”的传承意思相矛盾。", "出口销售": "搭配：“习俗”是可以传承的风俗，不能与“出口销售”搭配。", "拆除重建": "语义：“拆除重建”是对建筑的处理，与习俗无关，不能靠它流传下来。"}, "sentence_index": 6, "correct_answer": "口耳相传"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本教材是印刷厂口耳相传的。", "explanation": "这里应该用〈印刷〉。教材是印出来的书面材料，不能靠口耳相传。"}, {"text": "这段历史是用胶片口耳相传下来的。", "explanation": "这里应该用〈拍摄〉。胶片记录的是影像，口耳相传是靠口头讲述传递，二者不能互换。"}, {"text": "这份文件是用公章口耳相传的。", "explanation": "这里应该用〈盖〉。公章是盖在文件上的印记，不能用口耳相传来表示。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0699896b-5564-42a6-bae3-4971e7e622fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些歌谣是祖辈口耳相传下来。", "corrected_sentence": "这些歌谣是祖辈口耳相传下来的。", "error_description": "句式错误：“是……的”强调句式中漏掉了“的”，应说“这些歌谣是祖辈口耳相传下来的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0699896b-5564-42a6-bae3-4971e7e622fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些歌谣口耳相传很广。", "corrected_sentence": "这些歌谣口耳相传得很广。", "error_description": "补语错误：表示程度的补语前要用“得”连接，应说“口耳相传得很广”，漏掉“得”。正确说法：这些歌谣口耳相传得很广。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0699896b-5564-42a6-bae3-4971e7e622fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
