INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21016, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人和人之间说说话，分享想法。", "primary_collocate": null, "pronunciation": "jiāo liú", "ipa": "tɕjɑʊ˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "我喜欢和朋友交流自己的想法。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天晚上都和我交流一会儿。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱说话，很少和别人交流。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们俩交流得很愉快，聊了一下午。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子需要和父母多交流。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在网上交流让我认识了很多朋友。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和邻居交流之后，我们成了好朋友。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很会和陌生人交流。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们见面时用汉语交流。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多和家人交流，心情会好一些。", "target_word": "交流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交流了", "label": "体标"}, {"form": "交流过", "label": "体标"}, {"form": "交流交流", "label": "重叠"}, {"form": "交流会", "label": "复合"}], "register": "中性", "sense_fingerprint": "交流：人与人之间日常说话，分享想法和心情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a527533-d9b0-40ff-b560-df5dbf897fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21016, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交流", "is_correct": true, "explanation": "正确：交流指与朋友互相说话、分享想法，符合句意。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：隐瞒想法不是与朋友分享，与“我喜欢和朋友……”的语境相反。"}, {"text": "交易", "is_correct": false, "explanation": "搭配：“交易”的对象是货物，不能说“交易自己的想法”。"}, {"text": "打听", "is_correct": false, "explanation": "语义：打听是探问别人的情况，与“分享自己的想法”不符。"}], "explanations": {"交流": "正确：交流指与朋友互相说话、分享想法，符合句意。", "隐瞒": "语义：隐瞒想法不是与朋友分享，与“我喜欢和朋友……”的语境相反。", "交易": "搭配：“交易”的对象是货物，不能说“交易自己的想法”。", "打听": "语义：打听是探问别人的情况，与“分享自己的想法”不符。"}, "sentence_index": 0, "correct_answer": "交流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她坐在窗前交流了一下午的天空。", "explanation": "这里应该用〈眺望〉。交流指互相沟通或交换，不能用来指看天空。"}, {"text": "她交流了一堵墙，搬进了新房。", "explanation": "这里应该用〈粉刷〉。交流指互相沟通或交换，墙面是建筑的一部分，不能用交流来表示。"}, {"text": "他一个人交流了一下午。", "explanation": "这里应该用〈自言自语〉。交流需要双方或多方互相沟通，一个人独自说话不叫交流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0699896b-5564-42a6-bae3-4971e7e622fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交流", "is_correct": true, "explanation": "正确：交流之后成为好朋友，符合句意。"}, {"text": "绝交", "is_correct": false, "explanation": "语义：绝交之后不会成为好朋友，与句末“成了好朋友”矛盾。"}, {"text": "疏远", "is_correct": false, "explanation": "语义：疏远与“成了好朋友”的结果相反。"}, {"text": "搬家", "is_correct": false, "explanation": "配价：“搬家”不带“和……”的交互对象，不能说“和邻居搬家”。"}], "explanations": {"交流": "正确：交流之后成为好朋友，符合句意。", "绝交": "语义：绝交之后不会成为好朋友，与句末“成了好朋友”矛盾。", "疏远": "语义：疏远与“成了好朋友”的结果相反。", "搬家": "配价：“搬家”不带“和……”的交互对象，不能说“和邻居搬家”。"}, "sentence_index": 6, "correct_answer": "交流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天坐地铁交流上班，要花一个小时。", "explanation": "这里应该用〈通勤〉。交流指沟通意见或信息，不能用来指往返上下班的路途。"}, {"text": "他每天早上交流身体，很有精神。", "explanation": "这里应该用〈锻炼〉。交流指沟通意见或信息，不能用来指锻炼身体。"}, {"text": "她每天交流房间，把屋子收拾得很干净。", "explanation": "这里应该用〈打扫〉。交流指沟通意见或信息，不能用来指清理房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0699896b-5564-42a6-bae3-4971e7e622fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们俩常老师交流学习的问题。", "corrected_sentence": "我们俩常和老师交流学习的问题。", "error_description": "介词缺失：表示交流的对象要用“和……交流”，漏掉介词“和”，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0699896b-5564-42a6-bae3-4971e7e622fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "咱们今天交流的很顺利。", "corrected_sentence": "咱们今天交流得很顺利。", "error_description": "补语标记用错：表示程度的补语要用“交流得很顺利”，动词与补语之间的助词应是“得”，不能写成“的”。“的”用来连接定语和中心语，接在动词后不通，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0699896b-5564-42a6-bae3-4971e7e622fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
