INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21018, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "找东西，看文字找自己要的信息。", "primary_collocate": null, "pronunciation": "jiǎn suǒ", "ipa": "tɕjɛn˨˩ swɔ˨˩", "syllable_count": 2, "sentences": [{"text": "我想检索一下这篇文章里的日期。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在文件里检索客户的名字。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用电脑检索这份报告里的数字。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我检索了很久，才找到那条新闻。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在网页上用关键词检索很方便。", "target_word": "检索", "complexity_tier": "T3", "furigana": "zài wǎngyè shàng yòng guānjiàncí jiǎnsuǒ hěn fāngbiàn", "sentence_source": "generated"}, {"text": "他在书里检索需要的资料。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以先检索一下旧邮件。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用这个网站检索法律条文。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在档案里检索父亲的名字。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们去图书馆检索资料。", "target_word": "检索", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "检索了", "label": "体标"}, {"form": "检索过", "label": "体标"}, {"form": "检索结果", "label": "复合"}, {"form": "检索系统", "label": "复合"}], "register": "书面", "sense_fingerprint": "检索：在文字材料里查找自己需要的信息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a527533-d9b0-40ff-b560-df5dbf897fd9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "检索", "is_correct": true, "explanation": "“想检索一下这篇文章里的日期”：检索指在文字材料中查找所需信息，符合句意。"}, {"text": "扩建", "is_correct": false, "explanation": "搭配：“扩建”用于房屋、场地，不能用于文章中的日期。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：“缝补”用于衣物、布料，不能用于文章中的日期。"}, {"text": "播种", "is_correct": false, "explanation": "语义：“播种”指把种子撒在土里，与在文章中找日期毫无关系。"}], "explanations": {"检索": "“想检索一下这篇文章里的日期”：检索指在文字材料中查找所需信息，符合句意。", "扩建": "搭配：“扩建”用于房屋、场地，不能用于文章中的日期。", "缝补": "搭配：“缝补”用于衣物、布料，不能用于文章中的日期。", "播种": "语义：“播种”指把种子撒在土里，与在文章中找日期毫无关系。"}, "sentence_index": 0, "correct_answer": "检索"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上检索房间。", "explanation": "这里应该用〈打扫〉。检索用于查找资料和信息，清理房间是具体的动作，要用打扫。"}, {"text": "他向邻居检索搬家公司的电话。", "explanation": "这里应该用〈打听〉。检索是在资料中查找，向别人询问信息要用打听。"}, {"text": "师傅检索了漏雨的屋顶。", "explanation": "这里应该用〈修补〉。检索只用于查找信息，屋顶是实物，修补漏雨要用修补。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0699896b-5564-42a6-bae3-4971e7e622fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "检索", "is_correct": true, "explanation": "“你可以先检索一下旧邮件”：检索指在资料中找出所需信息，符合句意。"}, {"text": "烘烤", "is_correct": false, "explanation": "搭配：“烘烤”用于食物，不能用于邮件。"}, {"text": "晾晒", "is_correct": false, "explanation": "搭配：“晾晒”用于衣物、被褥，不能用于旧邮件。"}, {"text": "翻新", "is_correct": false, "explanation": "语义：“翻新”指把旧东西修整如新，与找旧邮件的意图不符。"}], "explanations": {"检索": "“你可以先检索一下旧邮件”：检索指在资料中找出所需信息，符合句意。", "烘烤": "搭配：“烘烤”用于食物，不能用于邮件。", "晾晒": "搭配：“晾晒”用于衣物、被褥，不能用于旧邮件。", "翻新": "语义：“翻新”指把旧东西修整如新，与找旧邮件的意图不符。"}, "sentence_index": 6, "correct_answer": "检索"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每晚检索孩子。", "explanation": "这里应该用〈陪伴〉。检索是在资料中查找信息，照看孩子是人与人之间的相处，要用陪伴。"}, {"text": "他每天检索桌子。", "explanation": "这里应该用〈擦拭〉。检索只用于查找资料，擦桌子是实物清洁，要用擦拭。"}, {"text": "园丁每天检索花园。", "explanation": "这里应该用〈浇灌〉。检索用于在资料中查找信息，给花园浇水要用浇灌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0699896b-5564-42a6-bae3-4971e7e622fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这些资料检索。", "corrected_sentence": "我把这些资料检索了一遍。", "error_description": "“把”字句中，动词后必须有补语或“了”等成分，不能只说“把资料检索”。应说“把资料检索了一遍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0699896b-5564-42a6-bae3-4971e7e622fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把关键词检索了这份报告。", "corrected_sentence": "我用关键词检索了这份报告。", "error_description": "介词误用：“用关键词”表示凭借的方式，应用“用”引出，不能用“把”。“把关键词检索了”把“关键词”当作被处置的对象，但关键词是检索的手段，句意不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0699896b-5564-42a6-bae3-4971e7e622fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
