INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21020, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "十八世纪是一段很长的时间，从1701年到1800年。", "primary_collocate": null, "pronunciation": "shí bā shì jì", "ipa": "ʂʅ˧˥ pa˥˥ ʂʅ˥˩ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "十八世纪一共有一百年。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷对十八世纪的历史很感兴趣。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十八世纪的衣服和现在很不一样。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画是十八世纪的一位画家画的。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们上周学了十八世纪的故事。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十八世纪的船比现在的船慢得多。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去看十八世纪留下来的老城堡。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十八世纪的时候，很多人住在小村子里。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一些十八世纪的杯子。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位音乐家生活在十八世纪。", "target_word": "十八世纪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "十八世纪初", "label": "复合"}, {"form": "十八世纪末", "label": "复合"}, {"form": "十八世紀", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从1701年到1800年的一百年时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dcb27e5f-444c-42a7-80fe-3a6d050e1591') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21020, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "十八世纪", "is_correct": true, "explanation": "正确：指一百年的历史时段，与“一共有一百年”相符。"}, {"text": "十八个月", "is_correct": false, "explanation": "语义：十八个月只有一年半，与“一百年”矛盾。"}, {"text": "十八年", "is_correct": false, "explanation": "语义：十八年与一百年数量不符，句子前后矛盾。"}, {"text": "十八辈子", "is_correct": false, "explanation": "语域：“十八辈子”是口语夸张说法，与这里的数量陈述不合。"}], "explanations": {"十八世纪": "正确：指一百年的历史时段，与“一共有一百年”相符。", "十八个月": "语义：十八个月只有一年半，与“一百年”矛盾。", "十八年": "语义：十八年与一百年数量不符，句子前后矛盾。", "十八辈子": "语域：“十八辈子”是口语夸张说法，与这里的数量陈述不合。"}, "sentence_index": 0, "correct_answer": "十八世纪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在国外住了十八世纪。", "explanation": "这里应该用〈一年〉。十八世纪是百年时段，不能用来说在国外住的时间。"}, {"text": "他的身高是十八世纪。", "explanation": "这里应该用〈一米八〉。身高要用长度，十八世纪是时段，不能说明人的身高。"}, {"text": "我每天早上十八世纪起床。", "explanation": "这里应该用〈七点〉。十八世纪是长时段，不能指具体的钟点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "十八世纪", "is_correct": true, "explanation": "正确：指一段历史时期，与“留下来的老城堡”相符。"}, {"text": "十八楼", "is_correct": false, "explanation": "搭配：“十八楼”指楼层，不能说“留下来的老城堡”。"}, {"text": "十八分钟", "is_correct": false, "explanation": "语义：十八分钟太短，不能留下老城堡这样的历史遗迹。"}, {"text": "十八号", "is_correct": false, "explanation": "语义：“十八号”指日期，不能指一段历史时期。"}], "explanations": {"十八世纪": "正确：指一段历史时期，与“留下来的老城堡”相符。", "十八楼": "搭配：“十八楼”指楼层，不能说“留下来的老城堡”。", "十八分钟": "语义：十八分钟太短，不能留下老城堡这样的历史遗迹。", "十八号": "语义：“十八号”指日期，不能指一段历史时期。"}, "sentence_index": 6, "correct_answer": "十八世纪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行用了十八世纪。", "explanation": "这里应该用〈三天〉。十八世纪是百年时段，不能用来计算旅行的时间。"}, {"text": "这台电脑的保修期是十八世纪。", "explanation": "这里应该用〈两年〉。保修期以年或月计，十八世纪的跨度太长，不能这样用。"}, {"text": "这部电影长十八世纪。", "explanation": "这里应该用〈两个小时〉。电影的长度用时长表示，十八世纪不能表示电影的长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一座十八世纪老房子。", "corrected_sentence": "这是一座十八世纪的老房子。", "error_description": "定语标记缺失：“十八世纪”修饰“老房子”时要用“的”，应说“一座十八世纪的老房子”，不能说“一座十八世纪老房子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位学者生活十八世纪的巴黎。", "corrected_sentence": "那位学者生活在十八世纪的巴黎。", "error_description": "介词缺失：表示居住地点和时代的“生活在”，“在”不能省，应说“生活在十八世纪的巴黎”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b1886dc-b7cf-4f28-9b33-106ab52e7b5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
