INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21022, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西关住，不让它出来。", "primary_collocate": null, "pronunciation": "fēng bì", "ipa": "fɤŋ˥ pi˥˩", "syllable_count": 2, "sentences": [{"text": "工人用水泥封闭了洞口。", "target_word": "封闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把罐子封闭好，别让气味跑出来。", "target_word": "封闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这坛酒封闭了三年，打开时很香。", "target_word": "封闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋子封闭着，里面又闷又热。", "target_word": "封闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂把有毒气体封闭在管子里。", "target_word": "封闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管子要封闭好，气体才不会漏出来。", "target_word": "封闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把旧照片封闭在铁盒里。", "target_word": "封闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小心地把瓶口封闭，不要让酒流出来。", "target_word": "封闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把水池封闭，不让水流出去。", "target_word": "封闭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅把炉子封闭好，火就不会跑出来。", "target_word": "封闭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "封闭了", "label": "完成体"}, {"form": "封闭着", "label": "持续体"}, {"form": "封闭式", "label": "复合"}], "register": "书面", "sense_fingerprint": "把某物严密关住或盖住，使里面的东西出不来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6f39da0-9e88-4222-8183-2237ea8e061c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21022, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "封闭", "is_correct": true, "explanation": "正确：封闭 fēng bì 是本词，意思是把东西严密关住或盖住。"}, {"text": "蜂蜜", "is_correct": false, "explanation": "蜂蜜 fēngmì 与 封闭 fēngbì 声母不同（m 与 b），意思是蜂蜜。"}, {"text": "风气", "is_correct": false, "explanation": "风气 fēngqì 与 封闭 fēngbì 声母不同（q 与 b），意思是风尚。"}, {"text": "分币", "is_correct": false, "explanation": "分币 fēnbì 与 封闭 fēngbì 韵母不同（n 与 ng），意思是一分的硬币。"}, {"text": "封笔", "is_correct": false, "explanation": "声调混淆：fēngbǐ 与 fēngbì 仅声调不同，意思是停止写作。"}], "explanations": {"封闭": "正确：封闭 fēng bì 是本词，意思是把东西严密关住或盖住。", "蜂蜜": "蜂蜜 fēngmì 与 封闭 fēngbì 声母不同（m 与 b），意思是蜂蜜。", "风气": "风气 fēngqì 与 封闭 fēngbì 声母不同（q 与 b），意思是风尚。", "分币": "分币 fēnbì 与 封闭 fēngbì 韵母不同（n 与 ng），意思是一分的硬币。", "封笔": "声调混淆：fēngbǐ 与 fēngbì 仅声调不同，意思是停止写作。"}, "sentence_index": null, "correct_answer": "封闭"}, "level_3": {"options": [{"text": "封闭", "is_correct": true, "explanation": "正确：用水泥把洞口盖住，符合“封闭”的意思。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是加热食物或液体的动作，不能用于用水泥处理洞口。"}, {"text": "烘干", "is_correct": false, "explanation": "搭配：烘干用于潮湿的东西，“烘干洞口”不搭配。"}, {"text": "点燃", "is_correct": false, "explanation": "配价：点燃需要带“火”之类的对象，“点燃洞口”不成立。"}], "explanations": {"封闭": "正确：用水泥把洞口盖住，符合“封闭”的意思。", "煮": "语义：煮是加热食物或液体的动作，不能用于用水泥处理洞口。", "烘干": "搭配：烘干用于潮湿的东西，“烘干洞口”不搭配。", "点燃": "配价：点燃需要带“火”之类的对象，“点燃洞口”不成立。"}, "sentence_index": 0, "correct_answer": "封闭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他睡觉前封闭了灯，屋子里一片漆黑。", "explanation": "这里应该用〈关〉。关灯是把灯关掉；封闭指用东西严密盖住或围住，不用于开关电灯。"}, {"text": "今天的天气很封闭，让人心情很好。", "explanation": "封闭用于空间或容器，不能形容天气。"}, {"text": "他用封闭的声音说话。", "explanation": "封闭用于空间或物体，不能用来形容声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21022, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "封闭", "is_correct": true, "explanation": "正确：封闭 fēng bì 是本词。"}, {"text": "风力", "is_correct": false, "explanation": "风力 fēnglì 与 封闭 fēngbì 声母不同（l 与 b），意思是风的力量。"}, {"text": "封笔", "is_correct": false, "explanation": "声调混淆：fēngbǐ 与 fēngbì 仅声调不同，意思是停止写作。"}, {"text": "封地", "is_correct": false, "explanation": "最小对立：封地 fēngdì 与 封闭 fēngbì 仅声母不同（d 与 b），意思是古代分封给诸侯的土地。"}], "explanations": {"封闭": "正确：封闭 fēng bì 是本词。", "风力": "风力 fēnglì 与 封闭 fēngbì 声母不同（l 与 b），意思是风的力量。", "封笔": "声调混淆：fēngbǐ 与 fēngbì 仅声调不同，意思是停止写作。", "封地": "最小对立：封地 fēngdì 与 封闭 fēngbì 仅声母不同（d 与 b），意思是古代分封给诸侯的土地。"}, "sentence_index": null, "correct_answer": "封闭"}, "level_3": {"options": [{"text": "封闭", "is_correct": true, "explanation": "正确：“把旧照片封闭在铁盒里”，把照片密封在盒子里，符合句意。"}, {"text": "晒", "is_correct": false, "explanation": "语义：晒是在阳光下放置，铁盒里没有阳光，这个动作说不通。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕是把东西弄碎或扯开，不能说撕在铁盒里。"}, {"text": "砸", "is_correct": false, "explanation": "配价：砸需要猛击的对象，“砸在铁盒里”搭配不成立。"}], "explanations": {"封闭": "正确：“把旧照片封闭在铁盒里”，把照片密封在盒子里，符合句意。", "晒": "语义：晒是在阳光下放置，铁盒里没有阳光，这个动作说不通。", "撕": "语义：撕是把东西弄碎或扯开，不能说撕在铁盒里。", "砸": "配价：砸需要猛击的对象，“砸在铁盒里”搭配不成立。"}, "sentence_index": 6, "correct_answer": "封闭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他封闭了眼睛，什么也看不见。", "explanation": "这里应该用〈闭上〉。眼睛要说“闭上”，封闭指把物体严密关住或盖住，不用于眼睛。"}, {"text": "窗帘封闭了阳光。", "explanation": "这里应该用〈挡住〉。封闭指把东西关住，挡住阳光才用“挡住”。"}, {"text": "他把苹果封闭在桌子上。", "explanation": "封闭要求把东西围住或盖住，放在桌面上不算封闭，这里应该用〈放〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把蒸汽封闭罐子里了。", "corrected_sentence": "工人把蒸汽封闭在罐子里了。", "error_description": "介词错误：“封闭”后接处所要用“在”引出，应说“封闭在罐子里”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被瓶口封闭好了。", "corrected_sentence": "他把瓶口封闭好了。", "error_description": "介词用错：“被”字句中“瓶口”成了施事，与语义不符；应用“把”引出被处置的“瓶口”，即“把瓶口封闭好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e9ae051-7401-4cbc-995b-8c9389f3cbb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
