INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21054, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用来表示有多少个东西的词，比如一、二、三。", "primary_collocate": null, "pronunciation": "shù zì", "ipa": "ʂu˥˩ tsɨ˥˩", "syllable_count": 2, "sentences": [{"text": "老师教孩子们学一、二、三这些数字。", "target_word": "数字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语的数字“一”到“十”很好写。", "target_word": "数字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个数字读出来。", "target_word": "数字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中文课上，我先学会了十个数字。", "target_word": "数字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“三”是一个很简单的数字。", "target_word": "数字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书教小孩认颜色和数字。", "target_word": "数字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数字“八”在中国人看来很吉利。", "target_word": "数字", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会用英语说这些数字吗？", "target_word": "数字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不会说法语的数字。", "target_word": "数字", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈教弟弟说一到十的数字。", "target_word": "数字", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "阿拉伯数字", "label": "复合词"}], "register": "中性", "sense_fingerprint": "一、二、三这类表示多少的数词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e176a57-3f09-4b1b-b4b5-6e20e7f24a43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21054, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "数字", "is_correct": true, "explanation": "数字：表示多少的数词，如一、二、三。"}, {"text": "数次", "is_correct": false, "explanation": "cì 与 zì 声母不同（c/z），意思是「几次」。"}, {"text": "数日", "is_correct": false, "explanation": "rì 与 zì 声母不同（r/z），意思是「几天」。"}, {"text": "数制", "is_correct": false, "explanation": "zhì 与 zì 声母不同（zh/z），意思是「进位制」。"}], "explanations": {"数字": "数字：表示多少的数词，如一、二、三。", "数次": "cì 与 zì 声母不同（c/z），意思是「几次」。", "数日": "rì 与 zì 声母不同（r/z），意思是「几天」。", "数制": "zhì 与 zì 声母不同（zh/z），意思是「进位制」。"}, "sentence_index": null, "correct_answer": "数字"}, "level_3": {"options": [{"text": "数字", "is_correct": true, "explanation": "正确：一、二、三这类表示多少的数词，可以填入空格。"}, {"text": "字母", "is_correct": false, "explanation": "语义：字母是文字符号，不是表示多少的数词，与“一、二、三”不同类。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不表示数量，“学一、二、三这些颜色”说不通。"}, {"text": "形状", "is_correct": false, "explanation": "搭配：“一、二、三”是数的名称，不能用来学习形状。"}], "explanations": {"数字": "正确：一、二、三这类表示多少的数词，可以填入空格。", "字母": "语义：字母是文字符号，不是表示多少的数词，与“一、二、三”不同类。", "颜色": "语义：颜色不表示数量，“学一、二、三这些颜色”说不通。", "形状": "搭配：“一、二、三”是数的名称，不能用来学习形状。"}, "sentence_index": 0, "correct_answer": "数字"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班有三十个数字。", "explanation": "这里应该用〈学生〉。数字是表示多少的数词，不指班里的人；说人数要用“学生”或“人”。"}, {"text": "我记住了一支数字。", "explanation": "这里应该用量词〈个〉，说「一个数字」；“支”用于笔、歌曲等。"}, {"text": "这首诗的作者是一个数字。", "explanation": "这里应该用〈诗人〉。数字是表示多少的数词，不能指人；说作者要用「诗人」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21054, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数字", "is_correct": true, "explanation": "正确：“八”是数字，可以填入空格。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”后不能接数字“八”，“颜色‘八’”不成立。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物不是数字，“动物“八”在中国人看来很吉利”说不通。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不是数字，句子语义不通。"}], "explanations": {"数字": "正确：“八”是数字，可以填入空格。", "颜色": "搭配：“颜色”后不能接数字“八”，“颜色‘八’”不成立。", "动物": "语义：动物不是数字，“动物“八”在中国人看来很吉利”说不通。", "饮料": "语义：饮料不是数字，句子语义不通。"}, "sentence_index": 6, "correct_answer": "数字"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈教弟弟说一根数字。", "explanation": "这里应该用量词〈个〉，说「一个数字」；“根”用于细长的东西。"}, {"text": "这个英语单词有五个数字。", "explanation": "这里应该用〈字母〉。数字是表示多少的数词，不指组成单词的字母。"}, {"text": "动物园里有三个数字。", "explanation": "这里应该用〈猴子〉。数字是表示多少的数词，不指动物；说动物园里的动物要用“猴子”等名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21054, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他学会了五本数字。", "corrected_sentence": "他学会了五个数字。", "error_description": "量词错误：“数字”的量词应为“个”，说「五本数字」是错的，“本”用于书籍。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21054, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈让我记住这三只数字。", "corrected_sentence": "妈妈让我记住这三个数字。", "error_description": "量词错误：“数字”的量词应为“个”，“只”用于动物，说「这三只数字」是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07e4d3-e5ec-4a99-b032-1d721a3c9427') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
