INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21062, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在田地里种菜、种粮食的人。", "primary_collocate": null, "pronunciation": "nóng mín", "ipa": "nʊŋ˧˥ min˧˥", "syllable_count": 2, "sentences": [{"text": "农民在田里种菜。", "target_word": "农民", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那位农民每天很早起床。", "target_word": "农民", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "农民们春天忙着种地。", "target_word": "农民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷是农民，住在乡下。", "target_word": "农民", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今年雨水多，农民的粮食长得很好。", "target_word": "农民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民把种好的菜卖到城里。", "target_word": "农民", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个农民有三头牛。", "target_word": "农民", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多农民秋天要收玉米。", "target_word": "农民", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他以前是老师，现在是农民。", "target_word": "农民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民伯伯用新机器种地。", "target_word": "农民", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位农民", "label": "量词"}, {"form": "农民们", "label": "复数"}, {"form": "农民工", "label": "复合"}, {"form": "農民", "label": "繁体"}], "register": "中性", "sense_fingerprint": "农民|concrete|在田地里种菜种粮食的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c39c2f0b-1c7d-4288-9529-c42fc1d1b19a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21062, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "农民", "is_correct": true, "explanation": "农民：在田地里种菜种粮的人，能作“种菜”的施事。"}, {"text": "汽车", "is_correct": false, "explanation": "配价：“种菜”需要能动的人作主语，汽车不能种菜，句子说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有种植的能力，“石头在田里种菜”不合常理。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不能在田里种菜，句子说不通。"}], "explanations": {"农民": "农民：在田地里种菜种粮的人，能作“种菜”的施事。", "汽车": "配价：“种菜”需要能动的人作主语，汽车不能种菜，句子说不通。", "石头": "语义：石头没有种植的能力，“石头在田里种菜”不合常理。", "电脑": "语义：电脑是机器，不能在田里种菜，句子说不通。"}, "sentence_index": 0, "correct_answer": "农民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我爷爷一直住在农民，很少出门。", "explanation": "这里应该用〈农村〉。“住在”后面要接地方，农民指种地的人，不能表示住的地方。"}, {"text": "他每天在农民上班，很辛苦。", "explanation": "这里应该用〈工厂〉。“在……上班”后面要接工作场所，农民指种地的人，不能作场所。"}, {"text": "我姐姐在农民工作，负责记账。", "explanation": "这里应该用〈农场〉。“在……工作”后面要接工作单位，农民是人，不能作单位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21062, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "农民", "is_correct": true, "explanation": "农民：是人，能拥有牛，与“这个农民有三头牛”相符。"}, {"text": "手机", "is_correct": false, "explanation": "配价：“有”的主语要能拥有东西，手机是物件，不能拥有三头牛。"}, {"text": "词典", "is_correct": false, "explanation": "语义：词典是书，不能拥有牛，句子说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，没有拥有牛的能力，句子说不通。"}], "explanations": {"农民": "农民：是人，能拥有牛，与“这个农民有三头牛”相符。", "手机": "配价：“有”的主语要能拥有东西，手机是物件，不能拥有三头牛。", "词典": "语义：词典是书，不能拥有牛，句子说不通。", "窗户": "语义：窗户是建筑部件，没有拥有牛的能力，句子说不通。"}, "sentence_index": 6, "correct_answer": "农民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门口停着一辆农民。", "explanation": "这里量词不对。“辆”用于车辆，农民是人，应该说〈位〉农民。"}, {"text": "院子里种着一棵农民。", "explanation": "这里量词不对。“棵”用于树木和植物，农民是人，应该说〈位〉农民。"}, {"text": "桌上放着一把农民。", "explanation": "这里量词不对。“把”用于有把手的器物，农民是人，应该说〈位〉农民。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21062, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民地生活很辛苦。", "corrected_sentence": "农民的生活很辛苦。", "error_description": "错误：“地”误用。“农民”修饰后面的名词时要用“的”，“地”只用于修饰动词。应说“农民的生活”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21062, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只农民很勤劳。", "corrected_sentence": "那位农民很勤劳。", "error_description": "量词错误：“只”多用于动物或小件物品，指人应用“位”。应说“那位农民”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '691f3f1c-d45d-444e-963e-277b3753efa6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
