INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21070, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "能够长期保持、一直做下去的特点。", "primary_collocate": null, "pronunciation": "kě chí xù xìng", "ipa": "kʰɤ˨˩˦ ʈʂʰɻ̩˧˥ ɕy˥˩ ɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这个项目很注重可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "furigana": "zhè gè xiàng mù hěn zhù zhòng kě chí xù xìng", "sentence_source": "generated"}, {"text": "我们要考虑农业的可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种做法缺少可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环保公司很看重产品的可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市发展要有可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂提高了生产的可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说这个计划没有可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用旧瓶子做花盆，有很好的可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请大家讨论能源的可持续性。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的方法有可持续性，不是一时的办法。", "target_word": "可持续性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可持续", "label": "形容词形式"}, {"form": "可持续发展", "label": "复合"}], "register": "书面语", "sense_fingerprint": "能够长期保持、一直做下去的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3365f9ac-881d-493f-88dc-1a13db791d52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可持续性", "is_correct": true, "explanation": "正确：“可持续性”指能长期保持的特点，与“很注重”搭配，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指冷暖阴晴，不是项目注重的对象，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是具体的物体，“注重”后接的应是抽象的重点，句意不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“注重”通常接“质量、效果、安全”等抽象重点，“脚步”不能作注重的对象。"}], "explanations": {"可持续性": "正确：“可持续性”指能长期保持的特点，与“很注重”搭配，句意通顺。", "天气": "语义：“天气”指冷暖阴晴，不是项目注重的对象，句意不通。", "石头": "语义：“石头”是具体的物体，“注重”后接的应是抽象的重点，句意不通。", "脚步": "搭配：“注重”通常接“质量、效果、安全”等抽象重点，“脚步”不能作注重的对象。"}, "sentence_index": 0, "correct_answer": "可持续性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次活动的可持续性很甜。", "explanation": "“甜”形容味道，不能用来形容可持续性。"}, {"text": "这种牛奶的可持续性很酸。", "explanation": "“酸”形容味道，不能用来形容可持续性。"}, {"text": "这只猫的可持续性很硬。", "explanation": "“硬”形容质地，不能用来形容可持续性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可持续性", "is_correct": true, "explanation": "正确：“可持续性”指计划能长期维持的特点，“没有”后接它，句意通顺。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指人或动物身体的热度，计划没有体温，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高矮，计划不能说没有身高，句意不通。"}, {"text": "性别", "is_correct": false, "explanation": "搭配：“性别”只用于人或动植物，不能用来说计划有没有性别。"}], "explanations": {"可持续性": "正确：“可持续性”指计划能长期维持的特点，“没有”后接它，句意通顺。", "体温": "语义：“体温”指人或动物身体的热度，计划没有体温，句意不通。", "身高": "语义：“身高”指人的高矮，计划不能说没有身高，句意不通。", "性别": "搭配：“性别”只用于人或动植物，不能用来说计划有没有性别。"}, "sentence_index": 6, "correct_answer": "可持续性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的可持续性很快。", "explanation": "这里应该用〈速度〉。可持续性不用来说快慢，车跑得快不快要用速度。"}, {"text": "这块石头的可持续性很重。", "explanation": "这里应该用〈重量〉。可持续性指能长期维持下去的特点，不能用来说轻重，石头有多重要用重量。"}, {"text": "这件衣服的可持续性很便宜。", "explanation": "这里应该用〈价格〉。可持续性不用来说价钱，衣服贵不贵要用价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农场很重视土地的一个可持续性。", "corrected_sentence": "农场很重视土地的可持续性。", "error_description": "错误：“一个可持续性”。“可持续性”表示能长期维持的特点，是不能直接计数的属性，不说“一个可持续性”，应直接说“土地的可持续性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个方案得可持续性很强。", "corrected_sentence": "这个方案的可持续性很强。", "error_description": "错误：“得可持续性”。“得”是补语标记，不能用来修饰名词，应用结构助词“的”，写作“方案的可持续性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
