INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21074, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "花园是种花和树的地方。", "primary_collocate": null, "pronunciation": "huā yuán", "ipa": "xua˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我们学校有一个小花园。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里种着很多花和树。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈喜欢在花园里种菜和花。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在花园里跑来跑去。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家的花园很干净。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里的树下有一把椅子。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，花园里的花更好看了。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在花园里喝茶、看书。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个花园不大，但是很安静。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园的墙边有一只小猫。", "target_word": "花园", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "后花园", "label": "复合"}, {"form": "花園", "label": "繁体"}], "register": "中性", "sense_fingerprint": "花园·名词·种花和树的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad8707b-b94c-4d2f-9bdd-fe5d9124629c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21074, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花园", "is_correct": true, "explanation": "正确：指种花和树的地方，「小」修饰它，符合「学校有一个小……」的语境。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：园丁是人，不是场所，句子需要的是一个地方。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：歌曲应用量词「首」，「一个小歌曲」不成立。"}, {"text": "汤", "is_correct": false, "explanation": "搭配：汤的量词是「碗」或「锅」，「一个小汤」不说。"}], "explanations": {"花园": "正确：指种花和树的地方，「小」修饰它，符合「学校有一个小……」的语境。", "园丁": "语义：园丁是人，不是场所，句子需要的是一个地方。", "歌曲": "搭配：歌曲应用量词「首」，「一个小歌曲」不成立。", "汤": "搭配：汤的量词是「碗」或「锅」，「一个小汤」不说。"}, "sentence_index": 0, "correct_answer": "花园"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校有一只花园。", "explanation": "这里应该用〈个〉或〈座〉。「只」用于动物或成对的器官，不用于花园。"}, {"text": "阳台上摆着一盆花园。", "explanation": "这里应该用〈块〉或〈个〉。「盆」用于盆栽植物，花园是地上的园地，不能说一盆。"}, {"text": "这家花园里养着几只老虎。", "explanation": "这里应该用〈动物园〉。花园是种花和树的地方，不养老虎，养野生动物应说〈动物园〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab5485f9-d7c9-4527-8302-2ad2d3088ebc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花园", "is_correct": true, "explanation": "正确：指种花和树的地方，「下雨以后」「花园里的花更好看」符合语境。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯是运送乘客的设备，与下雨后花的变化无关。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱里不会种花，也不会因为下雨而变得好看。"}, {"text": "课桌", "is_correct": false, "explanation": "搭配：「课桌里的花」不是常见说法，也不符合「下雨以后」的语境。"}], "explanations": {"花园": "正确：指种花和树的地方，「下雨以后」「花园里的花更好看」符合语境。", "电梯": "语义：电梯是运送乘客的设备，与下雨后花的变化无关。", "冰箱": "语义：冰箱里不会种花，也不会因为下雨而变得好看。", "课桌": "搭配：「课桌里的花」不是常见说法，也不符合「下雨以后」的语境。"}, "sentence_index": 6, "correct_answer": "花园"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家门口有一棵花园。", "explanation": "这里应该用〈座〉或〈个〉。「棵」用于树木，不用于花园这类场所。"}, {"text": "这个花园里生产着很多钢铁。", "explanation": "这里应该用〈工厂〉。花园是种花和树的地方，不生产钢铁，要说生产钢铁应该用〈工厂〉。"}, {"text": "我们买了一台花园。", "explanation": "这里应该用〈块〉或〈片〉。「台」用于机器、设备，不用于花园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab5485f9-d7c9-4527-8302-2ad2d3088ebc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社区里有一只小花园。", "corrected_sentence": "社区里有一个小花园。", "error_description": "量词错误：花园应用量词「个」或「座」，「只」用于动物或成对的器官，不能用于花园。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab5485f9-d7c9-4527-8302-2ad2d3088ebc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爷爷常花园里下棋。", "corrected_sentence": "爷爷常在花园里下棋。", "error_description": "介词缺失：表示地点要用「在」，应说「在花园里下棋」，不能省略「在」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab5485f9-d7c9-4527-8302-2ad2d3088ebc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
