INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21076, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "装东西的小盒子。", "primary_collocate": null, "pronunciation": "xiǎo xiāng zi", "ipa": "ɕiɑʊ˨˩ ɕiɑŋ˥ tsɿ", "syllable_count": 3, "sentences": [{"text": "孩子把玩具装进小箱子里。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小箱子用来放我的铅笔和尺子。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小箱子掉在地上，里面的东西都出来了。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸买了一个金属小箱子放工具。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把项链放在小箱子里，锁好了。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子下面有一个蓝色的小箱子。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的小箱子里是什么？", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用小箱子装零钱。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小箱子很重，我一个人拿不动。", "target_word": "小箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把信和照片都放进了那个小箱子里。", "target_word": "小箱子", "complexity_tier": "T3", "furigana": "tā bǎ xìn hé zhàopiàn dōu fàng jìn le nà ge xiǎo xiāng zi lǐ", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个小箱子", "label": "量词"}, {"form": "一只小箱子", "label": "量词"}], "register": "口语", "sense_fingerprint": "装东西的小盒子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0818d17e-d628-4110-8069-5cbf9f1c9288') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21076, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小箱子", "is_correct": true, "explanation": "正确：小箱子是装东西的小盒子，孩子可以把玩具装进去。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不是可以装东西的容器，“装进……里”后不能接它。"}, {"text": "云朵", "is_correct": false, "explanation": "语义：云朵不是能装东西的器具，“装进”后不能接它。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“装进”后接的应是可以装东西的容器，大海不能用来装玩具。"}], "explanations": {"小箱子": "正确：小箱子是装东西的小盒子，孩子可以把玩具装进去。", "阳光": "语义：阳光不是可以装东西的容器，“装进……里”后不能接它。", "云朵": "语义：云朵不是能装东西的器具，“装进”后不能接它。", "大海": "搭配：“装进”后接的应是可以装东西的容器，大海不能用来装玩具。"}, "sentence_index": 0, "correct_answer": "小箱子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸把小箱子当作车子，一路骑着去上班。", "explanation": "这里应该用〈自行车〉。自行车可以骑行；小箱子是装东西的容器，不能骑。"}, {"text": "妈妈用小箱子烧水，水很快就开了。", "explanation": "这里应该用〈水壶〉。水壶能放在火上烧水；小箱子不能用来烧水。"}, {"text": "他把小箱子穿在身上，当作雨衣挡雨。", "explanation": "这里应该用〈雨衣〉。雨衣可以穿在身上挡雨；小箱子不能穿在身上挡雨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24710ba0-4c1c-4870-b5dc-222cae72c191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21076, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小箱子", "is_correct": true, "explanation": "正确：小箱子是装东西的容器，“你的小箱子里”可以放东西。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不是能装东西的容器，“里是什么”不成立。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不能用来装东西，“你的名字里是什么”句意不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“里”后接的应是可以装东西的地方，“脚步”不是。"}], "explanations": {"小箱子": "正确：小箱子是装东西的容器，“你的小箱子里”可以放东西。", "影子": "语义：影子不是能装东西的容器，“里是什么”不成立。", "名字": "语义：名字不能用来装东西，“你的名字里是什么”句意不通。", "脚步": "搭配：“里”后接的应是可以装东西的地方，“脚步”不是。"}, "sentence_index": 6, "correct_answer": "小箱子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把小箱子系在腰上，当作围裙围着做饭。", "explanation": "这里应该用〈围裙〉。围裙系在身上挡油污；小箱子是容器，不能当围裙用。"}, {"text": "她把小箱子穿在脚上，穿着它在雨里走路。", "explanation": "这里应该用〈鞋子〉。鞋子穿在脚上走路；小箱子是容器，不能当鞋穿。"}, {"text": "她把小箱子放在火上，烧起了一锅热汤。", "explanation": "这里应该用〈锅〉。锅能放在火上煮汤；小箱子不能放在火上烧汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24710ba0-4c1c-4870-b5dc-222cae72c191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把钥匙放进了一块小箱子里。", "corrected_sentence": "妈妈把钥匙放进了一个小箱子里。", "error_description": "量词错误：箱子应用“个”或“只”，不能用“块”；“块”多用于块状的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24710ba0-4c1c-4870-b5dc-222cae72c191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家有三小箱子放在柜子上。", "corrected_sentence": "我家有三个小箱子放在柜子上。", "error_description": "量词缺失：数词后应加量词，应说“三个小箱子”，不能直接说“三小箱子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24710ba0-4c1c-4870-b5dc-222cae72c191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21084, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无聊", "is_correct": true, "explanation": "正确：在“好玩”表示有趣的意义上，“无聊”与之意思相对，是反义词。"}, {"text": "严格", "is_correct": false, "explanation": "无关：“严格”形容要求或态度，与“好玩”没有反义关系。"}, {"text": "陌生", "is_correct": false, "explanation": "无关：“陌生”指不熟悉，与“好玩”没有反义关系。"}, {"text": "简单", "is_correct": false, "explanation": "无关：“简单”指不复杂，与“好玩”没有反义关系。"}], "correct_answer": "无聊", "explanations": {"无聊": "正确：在“好玩”表示有趣的意义上，“无聊”与之意思相对，是反义词。", "严格": "无关：“严格”形容要求或态度，与“好玩”没有反义关系。", "陌生": "无关：“陌生”指不熟悉，与“好玩”没有反义关系。", "简单": "无关：“简单”指不复杂，与“好玩”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24710ba0-4c1c-4870-b5dc-222cae72c191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21084, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无聊", "is_correct": true, "explanation": "正确：在“好玩”表示开心有趣的意义上，“无聊”与之意思相对，是反义词。"}, {"text": "热情", "is_correct": false, "explanation": "无关：“热情”形容态度，与“好玩”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "无关：“安静”形容声音或环境，与“好玩”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "无关：“聪明”形容智力，与“好玩”没有反义关系。"}], "correct_answer": "无聊", "explanations": {"无聊": "正确：在“好玩”表示开心有趣的意义上，“无聊”与之意思相对，是反义词。", "热情": "无关：“热情”形容态度，与“好玩”没有反义关系。", "安静": "无关：“安静”形容声音或环境，与“好玩”没有反义关系。", "聪明": "无关：“聪明”形容智力，与“好玩”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24710ba0-4c1c-4870-b5dc-222cae72c191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21084, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好玩就是做事情很开心，像玩游戏一样。", "primary_collocate": null, "pronunciation": "hǎo wán", "ipa": "xɑʊ˨˩ wan˧˥", "syllable_count": 2, "sentences": [{"text": "我们一起做饼干，太好玩了。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学画画很好玩，孩子们都喜欢。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用手机拍照片好玩极了。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做科学小实验好玩又有用。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一起堆雪人真好玩！", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打扫房间也可以很好玩。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们用唱歌的方式学汉字，很好玩。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑自行车去海边，一路上都很好玩。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样学数学，好玩多了。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和朋友一起做手工，真好玩。", "target_word": "好玩", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好玩儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "做事情开心、像玩游戏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0818d17e-d628-4110-8069-5cbf9f1c9288') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21084, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好玩", "is_correct": true, "explanation": "正确：好玩指做事情很开心、像玩游戏一样，是目标词。"}, {"text": "考完", "is_correct": false, "explanation": "声母不同（k 与 h），kǎo wán 意思是考试结束，与 hǎo wán 只差声母。"}, {"text": "搞完", "is_correct": false, "explanation": "声母不同（g 与 h），gǎo wán 意思是做完，与 hǎo wán 只差声母。"}, {"text": "炒完", "is_correct": false, "explanation": "声母不同（ch 与 h），chǎo wán 意思是炒完，与 hǎo wán 只差声母。"}], "explanations": {"好玩": "正确：好玩指做事情很开心、像玩游戏一样，是目标词。", "考完": "声母不同（k 与 h），kǎo wán 意思是考试结束，与 hǎo wán 只差声母。", "搞完": "声母不同（g 与 h），gǎo wán 意思是做完，与 hǎo wán 只差声母。", "炒完": "声母不同（ch 与 h），chǎo wán 意思是炒完，与 hǎo wán 只差声母。"}, "sentence_index": null, "correct_answer": "好玩"}, "level_3": {"options": [{"text": "好玩", "is_correct": true, "explanation": "正确：“好玩”说做事情很开心，与“一起做饼干”相符。"}, {"text": "孤单", "is_correct": false, "explanation": "语义：“一起做”却感到孤单，句意自相矛盾。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”指没有人气，与“一起做饼干”矛盾。"}, {"text": "难看", "is_correct": false, "explanation": "体貌：“难看”形容外表，不能用来评价做饼干的过程。"}], "explanations": {"好玩": "正确：“好玩”说做事情很开心，与“一起做饼干”相符。", "孤单": "语义：“一起做”却感到孤单，句意自相矛盾。", "冷清": "语义：“冷清”指没有人气，与“一起做饼干”矛盾。", "难看": "体貌：“难看”形容外表，不能用来评价做饼干的过程。"}, "sentence_index": 0, "correct_answer": "好玩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考试前，我的手心出汗，心里很好玩。", "explanation": "这里应该用〈紧张〉。紧张形容心理状态；好玩说事情有趣，不能用来形容心里的感觉。"}, {"text": "这个消息让他心里很好玩。", "explanation": "这里应该用〈难过〉。难过表示伤心；好玩表示有趣，不能用来形容伤心的心情。"}, {"text": "吃了太多油炸食品，我的身体很好玩。", "explanation": "这里应该用〈健康〉。健康说身体状况好；好玩说有趣，不能用来形容身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24710ba0-4c1c-4870-b5dc-222cae72c191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21084, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "好玩", "is_correct": true, "explanation": "正确：好玩指做事情很开心、像玩游戏一样，是目标词。"}, {"text": "跑完", "is_correct": false, "explanation": "声母不同（p 与 h），pǎo wán 意思是跑完全程，与 hǎo wán 只差声母。"}, {"text": "倒完", "is_correct": false, "explanation": "声母不同（d 与 h），dǎo wán 意思是倒完，与 hǎo wán 只差声母。"}, {"text": "扫完", "is_correct": false, "explanation": "声母不同（s 与 h），sǎo wán 意思是扫完，与 hǎo wán 只差声母。"}], "explanations": {"好玩": "正确：好玩指做事情很开心、像玩游戏一样，是目标词。", "跑完": "声母不同（p 与 h），pǎo wán 意思是跑完全程，与 hǎo wán 只差声母。", "倒完": "声母不同（d 与 h），dǎo wán 意思是倒完，与 hǎo wán 只差声母。", "扫完": "声母不同（s 与 h），sǎo wán 意思是扫完，与 hǎo wán 只差声母。"}, "sentence_index": null, "correct_answer": "好玩"}, "level_3": {"options": [{"text": "好玩", "is_correct": true, "explanation": "正确：“好玩”说学习方式让人开心，与句意相符。"}, {"text": "冷酷", "is_correct": false, "explanation": "语义：“冷酷”形容人的态度，不用来评价学习方式。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容温度，不用来评价用唱歌学汉字的方式。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容体型或外形，不用来评价学习方式。"}], "explanations": {"好玩": "正确：“好玩”说学习方式让人开心，与句意相符。", "冷酷": "语义：“冷酷”形容人的态度，不用来评价学习方式。", "寒冷": "语义：“寒冷”形容温度，不用来评价用唱歌学汉字的方式。", "高大": "体貌：“高大”形容体型或外形，不用来评价学习方式。"}, "sentence_index": 6, "correct_answer": "好玩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子很好玩，四条腿都摇摇晃晃。", "explanation": "这里应该用〈结实〉。结实说东西牢固；好玩说有趣，不能用来形容桌子牢不牢固。"}, {"text": "这台电脑很好玩，开机要等半个小时。", "explanation": "这里应该用〈慢〉。慢说速度低；好玩说有趣，不能用来形容速度。"}, {"text": "这碗汤很好玩，咸得没法喝。", "explanation": "这里应该用〈难喝〉。难喝说味道不好；好玩说有趣，不能用来形容汤的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24710ba0-4c1c-4870-b5dc-222cae72c191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一个好玩活动，大家都愿意参加。", "corrected_sentence": "这是一个好玩的活动，大家都愿意参加。", "error_description": "结构助词缺失：“好玩”修饰名词时要加“的”，应说“好玩的活动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24710ba0-4c1c-4870-b5dc-222cae72c191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种活动一点也好玩，我不想参加。", "corrected_sentence": "这种活动一点也不好玩，我不想参加。", "error_description": "否定缺失：“一点也”后要用“不”，应说“一点也不好玩”，不能说“一点也好玩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24710ba0-4c1c-4870-b5dc-222cae72c191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
