INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21086, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "从过去到现在。", "primary_collocate": null, "pronunciation": "zhì jīn", "ipa": "ʈʂɻ̩˥˩ tɕin˥", "syllable_count": 2, "sentences": [{"text": "他十年前去了国外，至今没回来。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题至今没有答案。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老店至今还在。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我至今记得第一次见她的样子。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她至今一个人住。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那本书我至今没看完。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥建于明代，至今还能用。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的话我至今忘不了。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的名字我至今记得很清楚。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个谜至今没人能解开。", "target_word": "至今", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "从过去某时一直到现在，常与没、还、记得等连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35b906f-46d6-4de6-ad17-6696c52b793f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21086, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "至今", "is_correct": true, "explanation": "正确：“至今没回来”表示从过去到现在一直没回来，与“十年前去了国外”相符。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指很近的时间，与“十年前”矛盾。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与“十年前去了国外”这种长期情况不合。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示进行中，不能与“没回来”的完结否定搭配，不说“正在没回来”。"}], "explanations": {"至今": "正确：“至今没回来”表示从过去到现在一直没回来，与“十年前去了国外”相符。", "刚刚": "语义：“刚刚”指很近的时间，与“十年前”矛盾。", "立刻": "语义：“立刻”表示马上，与“十年前去了国外”这种长期情况不合。", "正在": "搭配：“正在”表示进行中，不能与“没回来”的完结否定搭配，不说“正在没回来”。"}, "sentence_index": 0, "correct_answer": "至今"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天我至今去北京。", "explanation": "这里应该用〈将〉。“至今”只能指从过去持续到现在，不能用于将来的“明天”；说将来要用“将”。"}, {"text": "他昨天至今回家了。", "explanation": "这里应该用〈已经〉。“至今”强调持续到现在，不能与“昨天……回家了”这种过去完成的事件搭配。"}, {"text": "我至今的朋友都在北京。", "explanation": "“至今”是副词，不能直接修饰名词；这里应说“直到现在认识的朋友”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "至今", "is_correct": true, "explanation": "正确：“至今还能用”表示桥从建成到现在仍可以用，与“建于明代”相符。"}, {"text": "最近", "is_correct": false, "explanation": "语义：“最近”指不久以前，与“建于明代”的久远历史矛盾。"}, {"text": "不久", "is_correct": false, "explanation": "语义：“不久”表示时间很近，与“建于明代”的语境不合。"}, {"text": "尽快", "is_correct": false, "explanation": "搭配：“尽快”表示快速完成某事，不用于描述桥的持续状态。"}], "explanations": {"至今": "正确：“至今还能用”表示桥从建成到现在仍可以用，与“建于明代”相符。", "最近": "语义：“最近”指不久以前，与“建于明代”的久远历史矛盾。", "不久": "语义：“不久”表示时间很近，与“建于明代”的语境不合。", "尽快": "搭配：“尽快”表示快速完成某事，不用于描述桥的持续状态。"}, "sentence_index": 6, "correct_answer": "至今"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你至今把门关上。", "explanation": "“至今”表示从过去持续到现在，不能用于命令；这里应说“从现在起”。"}, {"text": "这个方法至今是在去年发明的。", "explanation": "这里应该用〈早在〉。“至今”指持续到现在，不能与指过去某一时点的“去年”搭配；说过去某时已经发生，要用“早在”。"}, {"text": "我至今昨天到家了。", "explanation": "这里应该用〈就〉。“至今”指从过去持续到现在，不能与具体的过去时间“昨天”搭配；说昨天已到家，应说“我昨天就到家了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个秘密很至今没有人知道。", "corrected_sentence": "这个秘密至今没有人知道。", "error_description": "“至今”是时间副词，不能受程度副词“很”修饰，应去掉“很”，说“这个秘密至今没有人知道”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的病至今了还没好。", "corrected_sentence": "他的病至今还没好。", "error_description": "“至今”后面不能直接加“了”，应去掉，说“至今还没好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
