INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21090, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手去做事情。", "primary_collocate": null, "pronunciation": "dòng shǒu", "ipa": "tʊŋ˥˩ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这张桌子是爸爸自己动手做的。", "target_word": "动手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到问题，先动脑，再动手。", "target_word": "动手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起动手包饺子吧。", "target_word": "动手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别说话了，快动手干活。", "target_word": "动手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们动手做了一个小房子。", "target_word": "动手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想学会做饭，就要多动手。", "target_word": "动手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他动手修好了旧自行车。", "target_word": "动手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让学生自己动手做实验。", "target_word": "动手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不用帮忙，我自己动手。", "target_word": "动手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢动手做小礼物。", "target_word": "动手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "动了手", "label": "离合（了）"}, {"form": "动动手", "label": "重叠"}], "register": "中性", "sense_fingerprint": "亲自用手去做、去操作某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3365f9ac-881d-493f-88dc-1a13db791d52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21090, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动手", "is_correct": true, "explanation": "正确：“动手”指亲自用手去做，“自己……做的”与此相符。"}, {"text": "动口", "is_correct": false, "explanation": "语义：“动口”是用嘴说话，桌子不能靠说话做出来，句意不通。"}, {"text": "请", "is_correct": false, "explanation": "配价：“请”要带人作宾语，“自己请做的”不成立。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是现成的商品，不能说购买做的，与“自己做”矛盾。"}], "explanations": {"动手": "正确：“动手”指亲自用手去做，“自己……做的”与此相符。", "动口": "语义：“动口”是用嘴说话，桌子不能靠说话做出来，句意不通。", "请": "配价：“请”要带人作宾语，“自己请做的”不成立。", "购买": "搭配：“购买”的对象是现成的商品，不能说购买做的，与“自己做”矛盾。"}, "sentence_index": 0, "correct_answer": "动手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "火车已经动手了。", "explanation": "这里应该用〈启动〉。动手指亲手做事，车辆、机器开动要用启动，火车不能说动手。"}, {"text": "他们两人说着说着就动手了。", "explanation": "这里“动手”指开始打架，是这个词的另一个意思，不是用手做事。"}, {"text": "我们明天就动手去北京。", "explanation": "这里应该用〈动身〉。动手指亲手做事，去某地出发要用动身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动手", "is_correct": true, "explanation": "正确：“动手”指亲自动手去做，与“修好了旧自行车”的动作相符。"}, {"text": "罢手", "is_correct": false, "explanation": "语义：“罢手”是停止、不再做的意思，与“修好”的动作矛盾，句意不通。"}, {"text": "动身", "is_correct": false, "explanation": "语义：“动身”指出发，修车不是出发，句意不通。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”不能带宾语，“睡修好了”不成立。"}], "explanations": {"动手": "正确：“动手”指亲自动手去做，与“修好了旧自行车”的动作相符。", "罢手": "语义：“罢手”是停止、不再做的意思，与“修好”的动作矛盾，句意不通。", "动身": "语义：“动身”指出发，修车不是出发，句意不通。", "睡": "配价：“睡”不能带宾语，“睡修好了”不成立。"}, "sentence_index": 6, "correct_answer": "动手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段真挚的话让我动手了。", "explanation": "这里应该用〈动容〉。动手指亲手做事，被话语感动要用动容，不能用动手。"}, {"text": "这份优厚的待遇让他动手了。", "explanation": "这里应该用〈动心〉。动手指亲手做事，被条件打动、心里想要行动要用动心，不能说动手。"}, {"text": "他们明天动手去西安。", "explanation": "这里应该用〈启程〉。动手指亲手做事，出发去远方要用启程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很喜欢动手了修东西。", "corrected_sentence": "他很喜欢动手修东西。", "error_description": "错误：“动手了修东西”。“很喜欢”表示习惯，句中不需要“了”，“动手”后不应插入“了”，应写作“动手修东西”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们先的动手，再想办法。", "corrected_sentence": "我们先动手，再想办法。", "error_description": "错误：“先的动手”。副词“先”修饰动词“动手”时不用“的”，应直接说“先动手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
