INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21092, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有用，好用的。", "primary_collocate": null, "pronunciation": "shí yòng", "ipa": "ʂɻ̩˧˥ yʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个小工具便宜又实用。", "target_word": "实用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房里的这把刀很实用，切菜特别快。", "target_word": "实用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给我买了一件实用的外套，下雨也能穿。", "target_word": "实用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我更喜欢实用的东西，不喜欢太漂亮的。", "target_word": "实用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件很实用，帮我找到了回家的路。", "target_word": "实用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教的这个办法简单，也很实用。", "target_word": "实用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种杯子能保温，非常实用。", "target_word": "实用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的建议很实用，我马上就用上了。", "target_word": "实用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家的时候，我只带实用的东西。", "target_word": "实用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本字典里的例句很实用，我常常看。", "target_word": "实用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "实用性", "label": "复合"}, {"form": "实用主义", "label": "复合"}, {"form": "不实用", "label": "否定"}], "register": "中性", "sense_fingerprint": "东西有用、好用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c55708a7-2145-4fac-8727-49a1b4830a21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21092, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实用", "is_correct": true, "explanation": "实用：有用，好用的。"}, {"text": "使用", "is_correct": false, "explanation": "声调不同：shǐ（第三声）与 shí（第二声）只差声调，意思是运用、用，不是东西好用。"}, {"text": "试用", "is_correct": false, "explanation": "声调不同：shì（第四声）与 shí（第二声）只差声调，意思是先试着用。"}, {"text": "施用", "is_correct": false, "explanation": "声调不同：shī（第一声）与 shí（第二声）只差声调，意思是施加使用，如施肥。"}, {"text": "失用", "is_correct": false, "explanation": "shī（第一声）与 shí（第二声）只差声调，意思是功能因长期不用而减退，如失用性萎缩。"}], "explanations": {"实用": "实用：有用，好用的。", "使用": "声调不同：shǐ（第三声）与 shí（第二声）只差声调，意思是运用、用，不是东西好用。", "试用": "声调不同：shì（第四声）与 shí（第二声）只差声调，意思是先试着用。", "施用": "声调不同：shī（第一声）与 shí（第二声）只差声调，意思是施加使用，如施肥。", "失用": "shī（第一声）与 shí（第二声）只差声调，意思是功能因长期不用而减退，如失用性萎缩。"}, "sentence_index": null, "correct_answer": "实用"}, "level_3": {"options": [{"text": "实用", "is_correct": true, "explanation": "实用：有使用价值，与“便宜又实用”的评价相符。"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：“昂贵”与前面的“便宜”意思相反，前后矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容体形，与“小工具”的体积相反。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：“沉重”指分量大，与“小工具”的特点不符。"}], "explanations": {"实用": "实用：有使用价值，与“便宜又实用”的评价相符。", "昂贵": "语义：“昂贵”与前面的“便宜”意思相反，前后矛盾。", "高大": "体貌：“高大”形容体形，与“小工具”的体积相反。", "沉重": "语义：“沉重”指分量大，与“小工具”的特点不符。"}, "sentence_index": 0, "correct_answer": "实用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜很实用，我每天都想吃。", "explanation": "这里应该用〈好吃〉。实用说东西有用，菜的味道要用“好吃”来评价。"}, {"text": "她的唱功很实用，台下的观众都听醉了。", "explanation": "这里应该用〈精湛〉。实用说东西有用，唱功的高超要用“精湛”来评价，实用不用来形容技艺。"}, {"text": "他的声音很实用，大家都喜欢。", "explanation": "这里应该用〈好听〉。实用不用于形容声音，声音的好坏要用“好听”来评价。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21092, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "实用", "is_correct": true, "explanation": "实用：有使用价值，与“能保温”的功能相符。"}, {"text": "花哨", "is_correct": false, "explanation": "语义：“花哨”强调外观，与“能保温”的功能不符。"}, {"text": "笨重", "is_correct": false, "explanation": "语义：“笨重”是负面评价，与“非常”带出的赞扬语气相矛盾。"}, {"text": "高雅", "is_correct": false, "explanation": "语域：“高雅”是书面的审美评价，不用来评价杯子的功能。"}], "explanations": {"实用": "实用：有使用价值，与“能保温”的功能相符。", "花哨": "语义：“花哨”强调外观，与“能保温”的功能不符。", "笨重": "语义：“笨重”是负面评价，与“非常”带出的赞扬语气相矛盾。", "高雅": "语域：“高雅”是书面的审美评价，不用来评价杯子的功能。"}, "sentence_index": 6, "correct_answer": "实用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部小说很实用，我一口气读完了。", "explanation": "这里应该用〈有趣〉。小说的好看程度要用“有趣”来评价，实用说东西的使用价值。"}, {"text": "这幅画很实用，挂在客厅里很好看。", "explanation": "这里应该用〈优美〉。画的美感要用“优美”来评价，实用不用来形容画。"}, {"text": "这场比赛很实用，大家都看得入迷。", "explanation": "这里应该用〈精彩〉。比赛的好看程度要用“精彩”来评价，实用不用来形容比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21092, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台烤箱有实用，我常用。", "corrected_sentence": "这台烤箱很实用，我常用。", "error_description": "错误：“有实用”；正确：“很实用”。“实用”是形容词，前面要用“很”这类程度副词，“有”后面应接名词，如“有实用价值”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21092, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把折叠椅很实用性，出门带着方便。", "corrected_sentence": "这把折叠椅很实用，出门带着方便。", "error_description": "错误：“实用性”；正确：“实用”。“实用性”是名词，不能直接受“很”修饰，形容词应说“很实用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
