INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21094, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做饭和放锅碗瓢盆的房间。", "primary_collocate": null, "pronunciation": "chú fáng", "ipa": "ʈʂʰu˧˥ faŋ˧˥", "syllable_count": 2, "sentences": [{"text": "妈妈在厨房做饭。", "target_word": "厨房", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家的厨房很小。", "target_word": "厨房", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "厨房里有一个大冰箱。", "target_word": "厨房", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把菜拿到厨房去了。", "target_word": "厨房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间厨房又干净又明亮。", "target_word": "厨房", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你帮我拿一下厨房的盐。", "target_word": "厨房", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房的灯开着，奶奶还在做饭。", "target_word": "厨房", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢在厨房里和爸爸一起做饭。", "target_word": "厨房", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房太热了，我想出去走走。", "target_word": "厨房", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你去厨房看看，汤好了没有？", "target_word": "厨房", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "间", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词：家里做饭的房间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a7a5ac5-16ea-4b03-b6bf-b31c050a3381') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21094, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": true, "explanation": "正确。妈妈在厨房做饭，厨房是做饭的地方。"}, {"text": "卧室", "is_correct": false, "explanation": "语义：卧室是睡觉休息的房间，不是做饭的地方，与“做饭”不符。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，与“做饭”毫无关系。"}, {"text": "厕所", "is_correct": false, "explanation": "搭配：“做饭”一般不在厕所进行，与“做饭”的场所搭配不当。"}], "explanations": {"厨房": "正确。妈妈在厨房做饭，厨房是做饭的地方。", "卧室": "语义：卧室是睡觉休息的房间，不是做饭的地方，与“做饭”不符。", "教室": "语义：教室是上课的地方，与“做饭”毫无关系。", "厕所": "搭配：“做饭”一般不在厕所进行，与“做饭”的场所搭配不当。"}, "sentence_index": 0, "correct_answer": "厨房"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是我们家的厨房。", "explanation": "这里应该用〈厨师〉。厨房指做饭的地方，不指人。"}, {"text": "我们把厨房吃掉了。", "explanation": "这里用错了对象。厨房是房间，不能被吃掉，应说“我们把饭菜吃掉了”。"}, {"text": "这张厨房很干净。", "explanation": "这里应该用〈间〉。厨房的量词是“间”，不说“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21094, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厨房", "is_correct": true, "explanation": "正确。奶奶还在做饭，所以厨房的灯开着。"}, {"text": "书房", "is_correct": false, "explanation": "语义：书房是看书学习的地方，与“奶奶还在做饭”不符。"}, {"text": "办公室", "is_correct": false, "explanation": "语义：办公室是工作的地方，与做饭无关。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借阅书籍的地方，与“奶奶还在做饭”的线索冲突。"}], "explanations": {"厨房": "正确。奶奶还在做饭，所以厨房的灯开着。", "书房": "语义：书房是看书学习的地方，与“奶奶还在做饭”不符。", "办公室": "语义：办公室是工作的地方，与做饭无关。", "图书馆": "语义：图书馆是借阅书籍的地方，与“奶奶还在做饭”的线索冲突。"}, "sentence_index": 6, "correct_answer": "厨房"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的厨房开会去了。", "explanation": "这里用错了主语。厨房是场所，不会开会，应说“今天的厨房很忙”。"}, {"text": "这个厨房去年考上了大学。", "explanation": "这里用错了主语。厨房是场所，不会考试或上学。"}, {"text": "我把厨房穿在了身上。", "explanation": "这里用错了对象。厨房是房间，不能穿在身上，应说“我穿着这件衣服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在厨房着做饭。", "corrected_sentence": "妈妈在厨房里做饭。", "error_description": "错误：多出的“着”不能插在“厨房”与“做饭”之间，应去掉。正确：在厨房（里）做饭。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一起去在厨房帮忙吧。", "corrected_sentence": "我们一起去厨房帮忙吧。", "error_description": "错误：“去”后直接接处所，不能加“在”。正确：去厨房帮忙。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
