INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21098, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房子的外面，有栏杆的、可以出去的平台。", "primary_collocate": null, "pronunciation": "yáng tái", "ipa": "jaŋ˧˥ tʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "我家的阳台很大，可以放很多花。", "target_word": "阳台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上在阳台上喝茶。", "target_word": "阳台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把衣服挂在阳台上。", "target_word": "阳台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳台上有一只小猫在睡觉。", "target_word": "阳台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我们坐在阳台看月亮。", "target_word": "阳台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳台的门开着，风吹进来了。", "target_word": "阳台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在阳台种了几盆花。", "target_word": "阳台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，快把阳台的衣服收进来。", "target_word": "阳台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从阳台可以看见楼下的小河。", "target_word": "阳台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在阳台上给朋友打电话。", "target_word": "阳台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个阳台", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词，楼房伸出墙外、有栏杆、人可以站在上面的平台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ddbf6c1-65b5-4c28-9abb-1fe3d7a1f8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21098, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阳台", "is_correct": true, "explanation": "正确：“我家的阳台很大，可以放很多花”，阳台是可以摆放花的平台，符合语境。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的小物件，不能用来放很多花，句意不通。"}, {"text": "铅笔", "is_correct": false, "explanation": "搭配：“很大”一般不用来形容铅笔这类细长物件，搭配不当。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱的功能是冷藏食物，不适合像阳台那样摆放很多花，句意不通。"}], "explanations": {"阳台": "正确：“我家的阳台很大，可以放很多花”，阳台是可以摆放花的平台，符合语境。", "钥匙": "语义：钥匙是开锁的小物件，不能用来放很多花，句意不通。", "铅笔": "搭配：“很大”一般不用来形容铅笔这类细长物件，搭配不当。", "冰箱": "语义：冰箱的功能是冷藏食物，不适合像阳台那样摆放很多花，句意不通。"}, "sentence_index": 0, "correct_answer": "阳台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把阳台缝好了。", "explanation": "这里应该用〈衣服〉。缝的是衣服，阳台是建筑的一部分，不能缝。"}, {"text": "他推开阳台，走了进去。", "explanation": "这里应该用〈门〉。推开的是门，阳台是露在外面的平台，不能推开。"}, {"text": "他手里拿着阳台，走了出去。", "explanation": "这里应该用〈钥匙〉。“拿着”的东西要能被拿起，阳台是建筑的一部分，不能拿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21098, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阳台", "is_correct": true, "explanation": "正确：“我在阳台种了几盆花”，阳台是可以种花的地方，符合语境。"}, {"text": "床", "is_correct": false, "explanation": "语义：床不是种植花卉的地方，“我在床种了几盆花”句意不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不能用来种花，句意不通。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：“种”后面的处所应是能栽培植物的地方，“钢笔”与“种”搭配不当。"}], "explanations": {"阳台": "正确：“我在阳台种了几盆花”，阳台是可以种花的地方，符合语境。", "床": "语义：床不是种植花卉的地方，“我在床种了几盆花”句意不通。", "书包": "语义：书包是装东西的袋子，不能用来种花，句意不通。", "钢笔": "搭配：“种”后面的处所应是能栽培植物的地方，“钢笔”与“种”搭配不当。"}, "sentence_index": 6, "correct_answer": "阳台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套房子的阳台被他吃掉了。", "explanation": "这里应该用〈食物〉。“吃”的对象是食物，阳台是建筑的一部分，不能吃。"}, {"text": "他一口气喝光了阳台。", "explanation": "这里应该用〈饮料〉。“喝”的对象是饮料，阳台是建筑的一部分，不能喝。"}, {"text": "阳台很陡，要小心。", "explanation": "这里应该用〈楼梯〉。“陡”形容楼梯、山坡等有坡度的地方，阳台是平的，不能说陡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在一只阳台上晾衣服。", "corrected_sentence": "妈妈在一个阳台上晾衣服。", "error_description": "错误：“一只阳台”；正确：“一个阳台”。“只”多用于动物及成对物品中的一件，阳台应用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套房子有一扇宽敞的阳台。", "corrected_sentence": "这套房子有一个宽敞的阳台。", "error_description": "错误：“一扇阳台”；正确：“一个阳台”。“扇”多用于门窗，阳台应用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
