INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21100, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指要做的某件事或工作。", "primary_collocate": null, "pronunciation": "xiàng mù", "ipa": "ɕjɑŋ˥˩ mu˥˩", "syllable_count": 2, "sentences": [{"text": "我们公司有一个新项目。", "target_word": "项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目下个月开始。", "target_word": "项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在负责一个大项目。", "target_word": "项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目要做三个月。", "target_word": "项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们完成了这个项目。", "target_word": "项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目的经费不够了。", "target_word": "项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目需要十个人一起做。", "target_word": "项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她参加过很多国际项目。", "target_word": "项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，大家一起讨论了新项目。", "target_word": "项目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把这个项目交给了小李。", "target_word": "项目", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "項目", "label": "繁体"}, {"form": "项目经理", "label": "复合"}, {"form": "项目组", "label": "复合"}], "register": "中性", "sense_fingerprint": "要做的某项工作或事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3365f9ac-881d-493f-88dc-1a13db791d52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21100, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "项目", "is_correct": true, "explanation": "“新项目”指新的工作或事务，与“一个新”搭配自然，句子通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是气象状况，不能说“我们公司有一个新天气”，句子不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指人体的温度，不能作为公司的“新……”，句子不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不说“新年龄”，“有一个新年龄”不通。"}], "explanations": {"项目": "“新项目”指新的工作或事务，与“一个新”搭配自然，句子通顺。", "天气": "语义：“天气”是气象状况，不能说“我们公司有一个新天气”，句子不通。", "体温": "语义：“体温”指人体的温度，不能作为公司的“新……”，句子不通。", "年龄": "搭配：“年龄”不说“新年龄”，“有一个新年龄”不通。"}, "sentence_index": 0, "correct_answer": "项目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这门项目要学三个月。", "explanation": "这里应该用〈课程〉。“学”的对象是课程，“项目”不能这样使用。"}, {"text": "我们公司有一首新项目。", "explanation": "这里量词应该用〈个〉（一个项目）。“首”用于诗歌、歌曲等，不能用来数“项目”。"}, {"text": "这个项目要走三个月。", "explanation": "这里应该用〈旅程〉。“走”搭配旅程、路程，“项目”指要做的工作，不能用“走”来表示经历的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21100, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "项目", "is_correct": true, "explanation": "“项目”是需要多人合作完成的工作，与“十个人一起做”相符，句意通顺。"}, {"text": "答案", "is_correct": false, "explanation": "语义：“答案”是问题的解，不能由十个人一起做，句子不通。"}, {"text": "电话", "is_correct": false, "explanation": "语义：“电话”是通讯工具，不能由十个人一起做，句子不通。"}, {"text": "脸色", "is_correct": false, "explanation": "搭配：“脸色”不能作为“需要十个人一起做”的对象，句意不通。"}], "explanations": {"项目": "“项目”是需要多人合作完成的工作，与“十个人一起做”相符，句意通顺。", "答案": "语义：“答案”是问题的解，不能由十个人一起做，句子不通。", "电话": "语义：“电话”是通讯工具，不能由十个人一起做，句子不通。", "脸色": "搭配：“脸色”不能作为“需要十个人一起做”的对象，句意不通。"}, "sentence_index": 6, "correct_answer": "项目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个项目要写三年。", "explanation": "这里应该用〈论文〉。“写”的对象可以是论文，“项目”一般说“做”或“执行”，不说“写”。"}, {"text": "这个项目要创作三年。", "explanation": "这里应该用〈作品〉。“创作”的对象是作品，“项目”不能这样用，应说“做”或“执行”。"}, {"text": "这个项目唱了三个小时。", "explanation": "这里“唱”的对象是歌曲，“项目”不能这样搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21100, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司接了一只新项目。", "corrected_sentence": "我们公司接了一个新项目。", "error_description": "量词错误：“项目”应用量词“个”（一个项目），不能用“只”。“只”多用于动物或成对的东西，“一只项目”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21100, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们接了一个大了项目。", "corrected_sentence": "他们接了一个大项目。", "error_description": "错误：“大了项目”。“了”表示变化，不能加在修饰名词的形容词“大”后面，应写作“一个大项目”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
