INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21102, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "扔掉没用的东西。", "primary_collocate": null, "pronunciation": "fèi qì wù", "ipa": "feɪ˥˩ tɕʰi˥˩ u˥˩", "syllable_count": 3, "sentences": [{"text": "工厂的废弃物要放在专门的地方。", "target_word": "废弃物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把废弃物扔进河里。", "target_word": "废弃物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些废弃物可以做成新东西。", "target_word": "废弃物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在清理房子里的废弃物。", "target_word": "废弃物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "废弃物太多，会让空气变差。", "target_word": "废弃物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市每天都会产生很多废弃物。", "target_word": "废弃物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把废弃物分成了几种。", "target_word": "废弃物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的废弃物很危险。", "target_word": "废弃物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校旁边有一个废弃物处理站。", "target_word": "废弃物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "废弃物不能随便倒在路边。", "target_word": "废弃物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工业废弃物", "label": "复合"}, {"form": "廢棄物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "被丢掉不再使用的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e0cc0c3-2668-4386-9dc2-289c59985202') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21102, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "废弃物", "is_correct": true, "explanation": "“废弃物”指被丢弃的东西，适合“放在专门的地方”。"}, {"text": "梦想", "is_correct": false, "explanation": "语义：“梦想”是抽象的心愿，不能被“放在专门的地方”存放。"}, {"text": "工人", "is_correct": false, "explanation": "语义：工人是人，不能被“放在专门的地方”当作物品存放。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不是实体，不能被“放在专门的地方”。"}], "explanations": {"废弃物": "“废弃物”指被丢弃的东西，适合“放在专门的地方”。", "梦想": "语义：“梦想”是抽象的心愿，不能被“放在专门的地方”存放。", "工人": "语义：工人是人，不能被“放在专门的地方”当作物品存放。", "声音": "语义：声音不是实体，不能被“放在专门的地方”。"}, "sentence_index": 0, "correct_answer": "废弃物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他骂我是个废弃物。", "explanation": "这里应该用〈废物〉。骂人没用时说“废物”，“废弃物”只指被丢弃的东西。"}, {"text": "他把废弃物存进了银行。", "explanation": "这里应该用〈钱〉。存进银行的是钱，“废弃物”指被丢弃、没有价值的东西。"}, {"text": "这些废弃物对我很重要，我舍不得扔。", "explanation": "这里应该用〈旧物〉。“废弃物”指被丢弃、不再使用的东西，不能指仍然重要的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21102, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废弃物", "is_correct": true, "explanation": "“废弃物”是可以分类的具体物品，与“分成几种”搭配。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：孩子是人，不能被当作物品“分成几种”。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛是器官，不适合被“分成几种”进行分类。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：“月亮”是天体，不能像废弃物那样被“分成几种”进行分类。"}], "explanations": {"废弃物": "“废弃物”是可以分类的具体物品，与“分成几种”搭配。", "孩子": "语义：孩子是人，不能被当作物品“分成几种”。", "眼睛": "语义：眼睛是器官，不适合被“分成几种”进行分类。", "月亮": "语义：“月亮”是天体，不能像废弃物那样被“分成几种”进行分类。"}, "sentence_index": 6, "correct_answer": "废弃物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们今天的晚饭吃了很多废弃物。", "explanation": "这里应该用〈食物〉。晚饭吃的是食物，“废弃物”指被丢弃、没有价值的东西，不能吃。"}, {"text": "他送我一份废弃物作为生日礼物。", "explanation": "这里应该用〈礼物〉。送人的东西要有价值，“废弃物”是被丢弃的东西，不能用来送人。"}, {"text": "他每天早上都要喝废弃物。", "explanation": "这里应该用〈牛奶〉。早上喝的是牛奶，“废弃物”指被丢弃、没有价值的东西，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里堆着很多废弃物们。", "corrected_sentence": "院子里堆着很多废弃物。", "error_description": "错误在于“废弃物”后加了“们”。“废弃物”是物质类名词，不能加“们”表示复数，应直接说“废弃物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一只废弃物要尽快清理。", "corrected_sentence": "这一堆废弃物要尽快清理。", "error_description": "错误在于量词：“废弃物”常以堆计，应用“堆”，不宜用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb151336-7222-40c5-a287-147726e4414a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
