INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21106, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西吃完后剩下的部分。", "primary_collocate": null, "pronunciation": "zhā", "ipa": "ʈʂa˥", "syllable_count": 1, "sentences": [{"text": "小孩吃饼干，桌子上掉了很多渣。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块蛋糕很干，吃的时候桌上到处都是渣。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃完水果，盘子里只剩下一点渣。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他吃完饼，手上还有渣。", "target_word": "渣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "吃螃蟹时，别把壳和渣放在桌上。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把桌上的渣擦干净。", "target_word": "渣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我吃完薯片，衣服上全是渣。", "target_word": "渣", "complexity_tier": "T3", "furigana": "wǒ chī wán shǔ piàn, yī fu shàng quán shì zhā.", "sentence_source": "generated"}, {"text": "吃饼干的时候，渣掉进了书里。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他吃得很干净，碗里一点渣也没有。", "target_word": "渣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗在地上找吃剩的渣。", "target_word": "渣", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "面包渣", "label": "复合"}], "register": "中性", "sense_fingerprint": "吃东西时掉下或吃完后剩下的碎屑、残余，如饼干渣、骨头渣", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d079ee5-3e48-4f10-9b81-1c61d5a1cf7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21106, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "渣", "is_correct": true, "explanation": "正确。渣（zhā）指东西吃完后掉下或剩下的碎屑。"}, {"text": "炸", "is_correct": false, "explanation": "zhà（第四声）与 zhā（第一声）声调不同，意思是“油炸”。"}, {"text": "叉", "is_correct": false, "explanation": "chā 与 zhā 声母不同（ch 与 zh），意思是“叉子”。"}, {"text": "张", "is_correct": false, "explanation": "zhāng 与 zhā 韵母不同（ang 与 a），意思是“张开”。"}, {"text": "遮", "is_correct": false, "explanation": "zhē 与 zhā 韵母不同（e 与 a），意思是“遮挡”。"}, {"text": "眨", "is_correct": false, "explanation": "zhǎ（第三声）与 zhā（第一声）声调不同，意思是“眨眼”。"}], "explanations": {"渣": "正确。渣（zhā）指东西吃完后掉下或剩下的碎屑。", "炸": "zhà（第四声）与 zhā（第一声）声调不同，意思是“油炸”。", "叉": "chā 与 zhā 声母不同（ch 与 zh），意思是“叉子”。", "张": "zhāng 与 zhā 韵母不同（ang 与 a），意思是“张开”。", "遮": "zhē 与 zhā 韵母不同（e 与 a），意思是“遮挡”。", "眨": "zhǎ（第三声）与 zhā（第一声）声调不同，意思是“眨眼”。"}, "sentence_index": null, "correct_answer": "渣"}, "level_3": {"options": [{"text": "渣", "is_correct": true, "explanation": "正确。吃饼干时掉下的碎屑正是“渣”，与语境相符。"}, {"text": "电线", "is_correct": false, "explanation": "语义：吃饼干时掉下的是碎屑，不会是电线。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“掉”后面一般不接大件家电，“掉了很多冰箱”不成立。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是大型乐器，“掉了很多钢琴”不合常理，与吃饼干的场景不符。"}], "explanations": {"渣": "正确。吃饼干时掉下的碎屑正是“渣”，与语境相符。", "电线": "语义：吃饼干时掉下的是碎屑，不会是电线。", "冰箱": "搭配：“掉”后面一般不接大件家电，“掉了很多冰箱”不成立。", "钢琴": "语义：钢琴是大型乐器，“掉了很多钢琴”不合常理，与吃饼干的场景不符。"}, "sentence_index": 0, "correct_answer": "渣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃饼干时，最香的部分是渣。", "explanation": "这里应该用〈饼干〉。渣是吃完后剩下的碎屑，最香的应是饼干本身，不能说“渣”最香。"}, {"text": "这杯可乐上面都是渣。", "explanation": "这里应该用〈泡沫〉。渣指吃完后剩下的碎屑，可乐表面的气泡要说“泡沫”，不能说“渣”。"}, {"text": "这碗面的渣很鲜。", "explanation": "这里应该用〈汤汁〉。渣指吃完后剩下的碎屑，有鲜味的汤汁不能说成“渣”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21106, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "渣", "is_correct": true, "explanation": "正确。渣（zhā）指东西吃完后掉下或剩下的碎屑。"}, {"text": "榨", "is_correct": false, "explanation": "zhà（第四声）与 zhā（第一声）声调不同，意思是“压出汁液”。"}, {"text": "插", "is_correct": false, "explanation": "chā 与 zhā 声母不同（ch 与 zh），意思是“插入”。"}, {"text": "章", "is_correct": false, "explanation": "zhāng 与 zhā 韵母不同（ang 与 a），意思是“文章”或“图章”。"}, {"text": "闸", "is_correct": false, "explanation": "zhá（第二声）与 zhā（第一声）声调不同，意思是“闸门”。"}], "explanations": {"渣": "正确。渣（zhā）指东西吃完后掉下或剩下的碎屑。", "榨": "zhà（第四声）与 zhā（第一声）声调不同，意思是“压出汁液”。", "插": "chā 与 zhā 声母不同（ch 与 zh），意思是“插入”。", "章": "zhāng 与 zhā 韵母不同（ang 与 a），意思是“文章”或“图章”。", "闸": "zhá（第二声）与 zhā（第一声）声调不同，意思是“闸门”。"}, "sentence_index": null, "correct_answer": "渣"}, "level_3": {"options": [{"text": "渣", "is_correct": true, "explanation": "正确。吃薯片后衣服上沾满的碎屑正是“渣”。"}, {"text": "血", "is_correct": false, "explanation": "语义：吃薯片不会让衣服上沾满血。"}, {"text": "雪", "is_correct": false, "explanation": "语义：吃薯片的语境下，衣服上不会是雪。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“玻璃”是锋利的碎片，与吃薯片后沾在衣服上的碎屑不搭配。"}], "explanations": {"渣": "正确。吃薯片后衣服上沾满的碎屑正是“渣”。", "血": "语义：吃薯片不会让衣服上沾满血。", "雪": "语义：吃薯片的语境下，衣服上不会是雪。", "玻璃": "搭配：“玻璃”是锋利的碎片，与吃薯片后沾在衣服上的碎屑不搭配。"}, "sentence_index": 6, "correct_answer": "渣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "盘子里还剩一根渣。", "explanation": "这里应该用〈点〉。“根”用于细长的东西，碎屑不能用“根”计量。"}, {"text": "桌上有一只渣。", "explanation": "这里应该用〈点〉。“只”多用于动物或成对的物品，碎屑不用“只”来计量。"}, {"text": "他的衣服上沾了一条渣。", "explanation": "这里应该用〈点〉。“条”用于细长的物品，碎屑不能用“条”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "裤子上还有一根渣。", "corrected_sentence": "裤子上还有一点渣。", "error_description": "量词错误：“根”用于细长的东西，渣是细碎的碎屑，不能用“根”计量，应说“一点渣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小狗在桌子底下找吃剩渣。", "corrected_sentence": "小狗在桌子底下找吃剩的渣。", "error_description": "错误形式：“吃剩渣”；正确形式：“吃剩的渣”。“吃剩”后面接名词作定语时要加“的”，不能直接说“吃剩渣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
