INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21108, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "这个词表示事情是真的，不是假的。", "primary_collocate": null, "pronunciation": "qí shí", "ipa": "tɕʰi˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "他看起来很凶，其实人很好。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为这很难，其实一点也不难。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说她二十岁，其实她已经三十了。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服看着很贵，其实只要五十块。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说他不会做饭，其实他做得很好。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我说没问题，其实心里有点怕。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店看着很小，其实里面很大。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人觉得英语难，其实多说就会了。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说没事，其实她很难过。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家以为他是老师，其实他是医生。", "target_word": "其实", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，指出事情真实的情况，常与前面看起来或以为的情况相反", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ddbf6c1-65b5-4c28-9abb-1fe3d7a1f8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21108, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "其实", "is_correct": true, "explanation": "正确。“其实”表示事情真实的情况，与前面的看法相反。"}, {"text": "七十", "is_correct": false, "explanation": "第一音节 qī（第一声）与 qí（第二声）声调不同，意思是七十。"}, {"text": "骑士", "is_correct": false, "explanation": "第二音节 shì（第四声）与 shí（第二声）声调不同，意思是骑士。"}, {"text": "启示", "is_correct": false, "explanation": "两个音节声调都不同：qǐ（第三声）、shì（第四声），意思是启示。"}], "explanations": {"其实": "正确。“其实”表示事情真实的情况，与前面的看法相反。", "七十": "第一音节 qī（第一声）与 qí（第二声）声调不同，意思是七十。", "骑士": "第二音节 shì（第四声）与 shí（第二声）声调不同，意思是骑士。", "启示": "两个音节声调都不同：qǐ（第三声）、shì（第四声），意思是启示。"}, "sentence_index": null, "correct_answer": "其实"}, "level_3": {"options": [{"text": "果然", "is_correct": false, "explanation": "语义：“果然”表示与预料相符，不能表示与“看起来很凶”相反的情况。"}, {"text": "其实", "is_correct": true, "explanation": "正确。“其实”引出与“看起来很凶”相反的真实情况，形成转折。"}, {"text": "反正", "is_correct": false, "explanation": "语义：“反正”表示不论怎样，与前面的印象没有转折关系。"}, {"text": "诚然", "is_correct": false, "explanation": "语域：“诚然”是书面语，口语中一般用“其实”或“的确”。"}], "explanations": {"果然": "语义：“果然”表示与预料相符，不能表示与“看起来很凶”相反的情况。", "其实": "正确。“其实”引出与“看起来很凶”相反的真实情况，形成转折。", "反正": "语义：“反正”表示不论怎样，与前面的印象没有转折关系。", "诚然": "语域：“诚然”是书面语，口语中一般用“其实”或“的确”。"}, "sentence_index": 0, "correct_answer": "其实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "其实你明天来吗？", "explanation": "这里应该用〈真的〉。“其实”用于陈述真实情况，不用于询问；问别人是否真的要来，应说“你真的明天来吗”。"}, {"text": "请你其实坐下。", "explanation": "这里不用〈其实〉。“其实”用于说明真实情况，不能修饰请求或命令，放在祈使句里与请求的语气不相容。"}, {"text": "如果明天下雨，其实我们就不去了。", "explanation": "这里不用〈其实〉。“其实”引出已经存在的真实情况，不能用在假设的条件句里；假设只用“如果……就……”来表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21108, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "其实", "is_correct": true, "explanation": "正确。“其实”表示事情真实的情况，与前面的看法相反。"}, {"text": "奇事", "is_correct": false, "explanation": "第二音节 shì（第四声）与 shí（第二声）声调不同，意思是奇怪的事。"}, {"text": "启事", "is_correct": false, "explanation": "两个音节声调都不同：qǐ（第三声）、shì（第四声），意思是公告。"}, {"text": "气势", "is_correct": false, "explanation": "两个音节声调都不同：qì（第四声）、shì（第四声），意思是气派和声势。"}], "explanations": {"其实": "正确。“其实”表示事情真实的情况，与前面的看法相反。", "奇事": "第二音节 shì（第四声）与 shí（第二声）声调不同，意思是奇怪的事。", "启事": "两个音节声调都不同：qǐ（第三声）、shì（第四声），意思是公告。", "气势": "两个音节声调都不同：qì（第四声）、shì（第四声），意思是气派和声势。"}, "sentence_index": null, "correct_answer": "其实"}, "level_3": {"options": [{"text": "幸亏", "is_correct": false, "explanation": "语义：“幸亏”表示因某种情况而避免了坏结果，与这里的转折不符。"}, {"text": "其实", "is_correct": true, "explanation": "正确。“其实”引出与“看着很小”相反的真实情况，形成转折。"}, {"text": "总算", "is_correct": false, "explanation": "语义：“总算”表示经过努力终于有了结果，与“看着很小”的对比无关。"}, {"text": "固然", "is_correct": false, "explanation": "配价：“固然”后面要接“但是”或“却”等转折词，这里没有。"}], "explanations": {"幸亏": "语义：“幸亏”表示因某种情况而避免了坏结果，与这里的转折不符。", "其实": "正确。“其实”引出与“看着很小”相反的真实情况，形成转折。", "总算": "语义：“总算”表示经过努力终于有了结果，与“看着很小”的对比无关。", "固然": "配价：“固然”后面要接“但是”或“却”等转折词，这里没有。"}, "sentence_index": 6, "correct_answer": "其实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你其实别再等了。", "explanation": "这里不用〈其实〉。“其实”用于说明真实情况，不能修饰请求或命令，劝对方别等时不能用它。"}, {"text": "其实你叫什么名字？", "explanation": "这里不用〈其实〉。“其实”要引出与前面看法相反的真实情况，这句是新的提问，前文没有可以相对的看法。"}, {"text": "如果你不来，其实我们就去公园。", "explanation": "这里不用〈其实〉。“其实”引出已经存在的真实情况，不能用在假设的条件句里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区看着很旧，其实的环境很好。", "corrected_sentence": "这个小区看着很旧，其实环境很好。", "error_description": "错误在“其实的”：“其实”是副词，不能加“的”修饰名词；应去掉“的”，写作“其实环境很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "表面上看他很安静，其实了很爱说话。", "corrected_sentence": "表面上看他很安静，其实很爱说话。", "error_description": "错误在“其实了”：“其实”是副词，后面不能加“了”；应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
