INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21110, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示一件事是最开始的部分。", "primary_collocate": null, "pronunciation": "shǒu xiān", "ipa": "ʂoʊ̯˨˩˦ ɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "做这道菜，首先要洗菜。", "target_word": "首先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首先，请大家安静一下。", "target_word": "首先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们首先去买票，然后去吃饭。", "target_word": "首先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉语首先要多听多说。", "target_word": "首先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首先我要谢谢大家。", "target_word": "首先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到家以后，首先应该洗手。", "target_word": "首先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首先，把米洗干净，再放进锅里。", "target_word": "首先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首先要想好，再动手做。", "target_word": "首先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他首先打开了窗户，然后坐下来。", "target_word": "首先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时，首先由经理说话。", "target_word": "首先", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "列举顺序中的第一项、最先", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ceb66b7-4790-48b5-8313-3c93963dc888') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21110, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "首先", "is_correct": true, "explanation": "正确。首先表示做菜的第一步，后面接“要洗菜”，符合句意。"}, {"text": "终于", "is_correct": false, "explanation": "语义：终于表示经过一段时间后出现的结果，与“做这道菜”的开始步骤矛盾。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：忽然表示突然发生，洗菜是有计划的第一步，不能用忽然。"}, {"text": "已经", "is_correct": false, "explanation": "语义：已经表示事情已经发生，与“做这道菜”的第一步不合，洗菜还没有做。"}], "explanations": {"首先": "正确。首先表示做菜的第一步，后面接“要洗菜”，符合句意。", "终于": "语义：终于表示经过一段时间后出现的结果，与“做这道菜”的开始步骤矛盾。", "忽然": "语义：忽然表示突然发生，洗菜是有计划的第一步，不能用忽然。", "已经": "语义：已经表示事情已经发生，与“做这道菜”的第一步不合，洗菜还没有做。"}, "sentence_index": 0, "correct_answer": "首先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经过三年的努力，他首先拿到了博士学位。", "explanation": "这里应该用〈终于〉。首先表示顺序上最开始，三年后取得结果要用终于。"}, {"text": "大家都离开以后，他首先走出了会场。", "explanation": "这里应该用〈最后〉。首先表示最开始，大家都走了以后才离开要用最后。"}, {"text": "他一直很平静，首先大笑起来。", "explanation": "这里应该用〈突然〉。首先表示顺序在前，没有前情的情绪爆发要用突然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "首先", "is_correct": true, "explanation": "正确。首先引出第一步，后面接“把米洗干净”，符合句意。"}, {"text": "其次", "is_correct": false, "explanation": "语义：其次表示第二项，句中没有第一项作铺垫，与“首先”引出第一步的句意不合。"}, {"text": "原来", "is_correct": false, "explanation": "语义：原来表示以前的情况，与洗米作为第一步的顺序不合。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续，不能与“把米洗干净”这种一次性动作搭配。"}], "explanations": {"首先": "正确。首先引出第一步，后面接“把米洗干净”，符合句意。", "其次": "语义：其次表示第二项，句中没有第一项作铺垫，与“首先”引出第一步的句意不合。", "原来": "语义：原来表示以前的情况，与洗米作为第一步的顺序不合。", "一直": "搭配：“一直”表示持续，不能与“把米洗干净”这种一次性动作搭配。"}, "sentence_index": 6, "correct_answer": "首先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他已经来过三次中国，这次首先来中国。", "explanation": "这里应该用〈再次〉。首先表示第一次，已经来过多次之后再来要用再次。"}, {"text": "经过很长时间，他首先拿到了驾照。", "explanation": "这里应该用〈终于〉。首先表示最开始，等了很久后取得结果要用终于。"}, {"text": "他一直很安静，首先大声喊了起来。", "explanation": "这里应该用〈忽然〉。首先表示顺序在前，没有前情的情绪爆发要用忽然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们首先先检查设备。", "corrected_sentence": "我们首先检查设备。", "error_description": "重复错误：“首先”和“先”都表示先后顺序，不能叠用。错误形式“首先先检查”，正确形式“首先检查”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我首先了去医院。", "corrected_sentence": "我首先去了医院。", "error_description": "错误形式：“首先了去医院”；正确形式：“首先去了医院”。动态助词“了”应放在动词“去”之后，表示动作已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
