INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21114, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "function", "definition": "不难就是很容易做到。", "primary_collocate": null, "pronunciation": "bù nán", "ipa": "pu˥˩ nan˧˥", "syllable_count": 2, "sentences": [{"text": "骑自行车不难，我一学就会。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找到他家不难，就在学校旁边。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比较两个手机，不难看到价格不同。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的字都很大，读起来不难。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想去北京工作并不难，你先学好汉语。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着说：“这个游戏不难。”", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要多练习，写好汉字不难。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这里走到车站不难，十分钟就到。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不难理解，他为什么不高兴。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说修椅子不难，他自己能做。", "target_word": "不难", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不难：很容易做到，不费力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5846132b-121e-4712-a287-c75705189ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21114, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "很难", "is_correct": false, "explanation": "语义：“很难”说骑车困难，与“我一学就会”矛盾。"}, {"text": "甚难", "is_correct": false, "explanation": "语域：“甚”是书面语，口语句子里不用；而且与“我一学就会”矛盾。"}, {"text": "不难", "is_correct": true, "explanation": "“不难”表示骑车容易做到，与“我一学就会”相符。"}, {"text": "很贵", "is_correct": false, "explanation": "语义：“很贵”说价钱高，与学骑车的难易无关，句子不通。"}], "explanations": {"很难": "语义：“很难”说骑车困难，与“我一学就会”矛盾。", "甚难": "语域：“甚”是书面语，口语句子里不用；而且与“我一学就会”矛盾。", "不难": "“不难”表示骑车容易做到，与“我一学就会”相符。", "很贵": "语义：“很贵”说价钱高，与学骑车的难易无关，句子不通。"}, "sentence_index": 0, "correct_answer": "不难"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他能有今天的成绩，真是来之不难。", "explanation": "这里应该用〈不易〉。“来之不易”是固定说法，指得来很艰难；“不难”不能这样用。"}, {"text": "天气干燥，大家都不难上火。", "explanation": "这里应该用〈容易〉。“容易上火”表示容易出现某种状况；“不难”只说事情不困难，不能表示容易出现某种状况。"}, {"text": "这里水电不难，居民经常停水停电。", "explanation": "这里应该用〈不便〉。“水电不便”描述供应条件差；“不难”只说事情不困难，不能用来描述水电供应条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很复杂", "is_correct": false, "explanation": "语义：“很复杂”说写字繁难，与“只要多练习”矛盾，多练习就会变容易。"}, {"text": "很费钱", "is_correct": false, "explanation": "搭配：写字不说“费钱”，“很费钱”与写汉字的意思不搭。"}, {"text": "不难", "is_correct": true, "explanation": "“不难”表示写好汉字并不困难，与“只要多练习”相符。"}, {"text": "甚苦", "is_correct": false, "explanation": "语域：“甚苦”是书面语，口语中不用；而且与“只要多练习”的语境矛盾。"}], "explanations": {"很复杂": "语义：“很复杂”说写字繁难，与“只要多练习”矛盾，多练习就会变容易。", "很费钱": "搭配：写字不说“费钱”，“很费钱”与写汉字的意思不搭。", "不难": "“不难”表示写好汉字并不困难，与“只要多练习”相符。", "甚苦": "语域：“甚苦”是书面语，口语中不用；而且与“只要多练习”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "不难"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个工作的工资不难，每个月能拿到很多钱。", "explanation": "这里应该用〈高〉。“不难”只说做事不费力，不能用来说工资的多少。"}, {"text": "这座房子的面积不难，住起来很宽敞。", "explanation": "这里应该用〈大〉。“不难”只说做事不费力，不能用来说面积的大小。"}, {"text": "这台手机的价格不难，学生都买得起。", "explanation": "这里应该用〈便宜〉。“不难”只说做事不费力，不能用来说价格高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "开车去郊区不不难，走高速就行。", "corrected_sentence": "开车去郊区不难，走高速就行。", "error_description": "否定词重复。“不难”本身已含否定，前面不能再加“不”，应说“开车去郊区不难”；“不不难”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这盏灯我装得不不难，半小时就好了。", "corrected_sentence": "这盏灯我装得不难，半小时就好了。", "error_description": "否定词重复。“不难”本身已含否定，前面不能再加“不”，应说“装得不难”；“装得不不难”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
