INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21116, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "要做什么事先做好安排。", "primary_collocate": null, "pronunciation": "zhǔn bèi", "ipa": "ʈʂwən˨˩ peɪ˥˩", "syllable_count": 2, "sentences": [{"text": "明天要考试，我今晚要好好准备。", "target_word": "准备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在厨房准备晚饭。", "target_word": "准备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你准备好了吗？我们要出门了。", "target_word": "准备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我下个月去北京旅行，要先准备好护照。", "target_word": "准备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人快到了，我们快准备饭菜吧。", "target_word": "准备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在准备明天的会议。", "target_word": "准备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们准备一份自我介绍。", "target_word": "准备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了这次比赛，她准备了很久。", "target_word": "准备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生日那天，爸爸给我准备了一个蛋糕。", "target_word": "准备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天要下雨，出门前我把雨伞准备好了。", "target_word": "准备", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "准备了", "label": "体标"}, {"form": "准备过", "label": "体标"}, {"form": "准备着", "label": "体标"}, {"form": "准备准备", "label": "重叠"}, {"form": "准备工作", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：为某事先做好安排或预备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb282ec0-1d20-4008-9f52-5b1110039fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21116, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "准备", "is_correct": true, "explanation": "准备：指今晚为明天的考试事先做好预备，与语境相符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：备考应当记住内容，“忘记”与“好好”和考前的目的相反。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与明天的考试没有关系，考前今晚不应以此为重点。"}, {"text": "开溜", "is_correct": false, "explanation": "语域：“开溜”是口语，指偷偷溜走，与“好好”和郑重的备考语境不协调。"}], "explanations": {"准备": "准备：指今晚为明天的考试事先做好预备，与语境相符。", "忘记": "语义：备考应当记住内容，“忘记”与“好好”和考前的目的相反。", "游泳": "语义：“游泳”与明天的考试没有关系，考前今晚不应以此为重点。", "开溜": "语域：“开溜”是口语，指偷偷溜走，与“好好”和郑重的备考语境不协调。"}, "sentence_index": 0, "correct_answer": "准备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "哥伦布准备了美洲。", "explanation": "这里应该用〈发现〉。“准备”指事先做好安排，已经存在的大陆只能说发现。"}, {"text": "这项研究准备了重大进展。", "explanation": "这里应该用〈取得〉。“准备”指事先做好安排，不能用来表示获得进展，应说取得。"}, {"text": "他的努力准备了大家的尊重。", "explanation": "这里应该用〈赢得〉。“准备”指事先做好安排，不能表示获得他人的尊重，应说赢得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "准备", "is_correct": true, "explanation": "准备：表示事先做好安排，与“老师让我们……一份自我介绍”的语境相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物等，不能说“洗一份自我介绍”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，“喝一份自我介绍”不成立。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃一份自我介绍”。"}], "explanations": {"准备": "准备：表示事先做好安排，与“老师让我们……一份自我介绍”的语境相符。", "洗": "搭配：“洗”的对象是衣物等，不能说“洗一份自我介绍”。", "喝": "搭配：“喝”的对象是液体，“喝一份自我介绍”不成立。", "吃": "搭配：“吃”的对象是食物，不能说“吃一份自我介绍”。"}, "sentence_index": 6, "correct_answer": "准备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个反应准备了大量气体。", "explanation": "这里应该用〈产生〉。化学反应不能有意“准备”，只能说产生气体。"}, {"text": "这场大雨准备了严重的损失。", "explanation": "这里应该用〈造成〉。“准备”需要有意的事先安排，大雨不能“准备”损失，只能说造成损失。"}, {"text": "工厂向河里准备了废水。", "explanation": "这里应该用〈排出〉。“准备”指人有意的事先安排，排放废水不是事先准备的，应说排出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议下个月举行，我们要先准备了材料。", "corrected_sentence": "会议下个月举行，我们要先准备材料。", "error_description": "“下个月”和“要”都指将来，“了”表示动作已经完成，前后矛盾；应去掉“了”，说“我们要先准备材料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天的聚会，我们要礼物准备好。", "corrected_sentence": "明天的聚会，我们要把礼物准备好。", "error_description": "“把”字句中，“礼物”是“准备”的宾语，要用“把”提到动词前，应说“把礼物准备好”；漏掉“把”，说“我们要礼物准备好”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c8d474c6-5243-4489-b129-456e059f3fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
