INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21118, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "放垃圾的桶子。", "primary_collocate": null, "pronunciation": "lā jī tǒng", "ipa": "la˥ tɕi˥ tʰʊŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "请把废纸扔进垃圾桶。", "target_word": "垃圾桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里有一个小垃圾桶。", "target_word": "垃圾桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾桶满了，快去倒垃圾。", "target_word": "垃圾桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家门口放着一个绿色的垃圾桶。", "target_word": "垃圾桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃完香蕉，把皮扔到垃圾桶里。", "target_word": "垃圾桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾桶太臭了，需要用水洗一洗。", "target_word": "垃圾桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里每隔几步就有一个垃圾桶。", "target_word": "垃圾桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾桶的盖子坏了，所以很臭。", "target_word": "垃圾桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把玩具扔进垃圾桶，妈妈让他捡出来。", "target_word": "垃圾桶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的垃圾桶分成可回收和不可回收两种。", "target_word": "垃圾桶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用来装垃圾的桶，放在家里或路边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d079ee5-3e48-4f10-9b81-1c61d5a1cf7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21118, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垃圾桶", "is_correct": true, "explanation": "正确。“废纸”是要丢弃的东西，垃圾桶是用来装废弃物的桶，符合句意。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶用来插花，不能用来装废纸，与“扔”的语境冲突。"}, {"text": "书架", "is_correct": false, "explanation": "搭配：“扔进”要接能盛放废弃物的容器，书架用来摆书，不说“扔进书架”。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：杯子用来盛装饮料，不用来装废纸，与句意不合。"}], "explanations": {"垃圾桶": "正确。“废纸”是要丢弃的东西，垃圾桶是用来装废弃物的桶，符合句意。", "花瓶": "语义：花瓶用来插花，不能用来装废纸，与“扔”的语境冲突。", "书架": "搭配：“扔进”要接能盛放废弃物的容器，书架用来摆书，不说“扔进书架”。", "杯子": "语义：杯子用来盛装饮料，不用来装废纸，与句意不合。"}, "sentence_index": 0, "correct_answer": "垃圾桶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "洗好的衣服要放进垃圾桶甩干。", "explanation": "这里应该用〈洗衣机〉。甩干要靠洗衣机，垃圾桶不能用来甩干衣服。"}, {"text": "烧好的开水要倒进垃圾桶，等凉了再喝。", "explanation": "这里应该用〈水壶〉。装开水要用能盛水的水壶，垃圾桶只用来装废弃物。"}, {"text": "冬天的毛衣叠好，放进垃圾桶收起来。", "explanation": "这里应该用〈衣柜〉。收放衣物要用衣柜，垃圾桶不用来收放衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21118, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "垃圾桶", "is_correct": true, "explanation": "正确。“每隔几步就有一个”指的是公园里的公共设施，垃圾桶符合句意。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯是建筑内的升降设备，公园里不会每隔几步就设一个，与句意不符。"}, {"text": "洗衣机", "is_correct": false, "explanation": "语义：洗衣机是家用电器，不会每隔几步就设在公园里，与句意不符。"}, {"text": "闹钟", "is_correct": false, "explanation": "搭配：“每隔几步就有一个”说的是公共设施，闹钟是个人物品，不搭配。"}], "explanations": {"垃圾桶": "正确。“每隔几步就有一个”指的是公园里的公共设施，垃圾桶符合句意。", "电梯": "语义：电梯是建筑内的升降设备，公园里不会每隔几步就设一个，与句意不符。", "洗衣机": "语义：洗衣机是家用电器，不会每隔几步就设在公园里，与句意不符。", "闹钟": "搭配：“每隔几步就有一个”说的是公共设施，闹钟是个人物品，不搭配。"}, "sentence_index": 6, "correct_answer": "垃圾桶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在书店买了一本垃圾桶。", "explanation": "这里应该用〈个〉。“本”用于书籍，垃圾桶是容器，量词用“个”。"}, {"text": "他新买了一块垃圾桶，放在门口。", "explanation": "这里应该用〈个〉。“块”用于块状的东西，垃圾桶是整体的容器，量词用“个”。"}, {"text": "厨房里摆着一辆垃圾桶。", "explanation": "这里应该用〈个〉。“辆”用于车辆，垃圾桶不是车，量词用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21118, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "厨房的角落里有一本垃圾桶。", "corrected_sentence": "厨房的角落里有一个垃圾桶。", "error_description": "量词错误：“本”用于书册，垃圾桶是容器，应说“一个垃圾桶”，不能说“一本垃圾桶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公交站旁边有一个垃圾桶们。", "corrected_sentence": "公交站旁边有一个垃圾桶。", "error_description": "词尾错误：“们”表示复数，只用于人，垃圾桶是物，应说“一个垃圾桶”，不能说“垃圾桶们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
