INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21120, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "塑料箱是用塑料做的箱子，可以放东西。", "primary_collocate": null, "pronunciation": "sù liào xiāng", "ipa": "su˥˩ liɑʊ˥˩ ɕiɑŋ˥", "syllable_count": 3, "sentences": [{"text": "他给我一个红色的塑料箱。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个塑料箱是妈妈买的。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把书放进塑料箱里。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料箱不怕水，可以放在外面。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明坐在塑料箱上等车。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室后面有两个大塑料箱，里面是球。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个塑料箱太小，放不下我的书。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塑料箱的盖子丢了，我要买新的。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐用塑料箱装了一些旧书。", "target_word": "塑料箱", "complexity_tier": "T3", "furigana": "sù liào xiāng", "sentence_source": "generated"}, {"text": "我们的玩具都在这个塑料箱里。", "target_word": "塑料箱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "用塑料做的、可以放东西的箱子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d079ee5-3e48-4f10-9b81-1c61d5a1cf7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "塑料箱", "is_correct": true, "explanation": "正确。“一个红色的”后接可以送人的物品，塑料箱符合句意。"}, {"text": "云", "is_correct": false, "explanation": "语义：云是天上的水汽，不能被送给别人，与“给我”的语境不合。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光线形成的，不是实物，不能被送给别人。"}, {"text": "海洋", "is_correct": false, "explanation": "配价：“给”要求可以转让的物品作宾语，海洋不能被给予。"}], "explanations": {"塑料箱": "正确。“一个红色的”后接可以送人的物品，塑料箱符合句意。", "云": "语义：云是天上的水汽，不能被送给别人，与“给我”的语境不合。", "影子": "语义：影子是光线形成的，不是实物，不能被送给别人。", "海洋": "配价：“给”要求可以转让的物品作宾语，海洋不能被给予。"}, "sentence_index": 0, "correct_answer": "塑料箱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "塑料箱不怕水，可以穿到外面。", "explanation": "这里应该用〈雨衣〉。“穿”要用衣物，塑料箱不能穿，“穿到外面”只能用于衣服。"}, {"text": "塑料箱不怕水，可以戴在头上。", "explanation": "这里应该用〈帽子〉。“戴”要用帽子之类的东西，塑料箱不能戴在头上。"}, {"text": "塑料箱不怕水，可以撑在外面。", "explanation": "这里应该用〈伞〉。“撑”要用伞，塑料箱不能撑开，不能说“撑在外面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "塑料箱", "is_correct": true, "explanation": "正确。塑料箱是可以装东西的容器，“放不下我的书”说的是它的容量，符合句意。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是用来装书的容器，“放不下我的书”说的是容量，与手机无关。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音没有容量，不能用来装书，“放不下我的书”说的是容器的容量，与声音无关。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：微笑是表情，没有容量，不能装书，与“放不下我的书”不合。"}], "explanations": {"塑料箱": "正确。塑料箱是可以装东西的容器，“放不下我的书”说的是它的容量，符合句意。", "手机": "语义：手机不是用来装书的容器，“放不下我的书”说的是容量，与手机无关。", "声音": "语义：声音没有容量，不能用来装书，“放不下我的书”说的是容器的容量，与声音无关。", "微笑": "语义：微笑是表情，没有容量，不能装书，与“放不下我的书”不合。"}, "sentence_index": 6, "correct_answer": "塑料箱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的玩具都在这张塑料箱里。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，塑料箱是立体的容器，量词用“个”。"}, {"text": "我们的玩具都在这本塑料箱里。", "explanation": "这里应该用〈个〉。“本”用于书册，塑料箱不是书，量词用“个”。"}, {"text": "我们的玩具都在这副塑料箱里。", "explanation": "这里应该用〈个〉。“副”用于成套的器具或眼镜等，塑料箱是单个的容器，量词用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐把旧衣服收进一本塑料箱里。", "corrected_sentence": "姐姐把旧衣服收进一个塑料箱里。", "error_description": "量词错误：“本”用于书册，塑料箱是容器，应说“一个塑料箱”，不能说“一本塑料箱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21120, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书架旁边有一个塑料箱们。", "corrected_sentence": "书架旁边有一个塑料箱。", "error_description": "词尾错误：“们”一般只加在指人或拟人化的名词后，塑料箱是物，应说“一个塑料箱”，不能说“塑料箱们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
