INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21122, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西有盖子盖着。", "primary_collocate": null, "pronunciation": "yǒu gài", "ipa": "joʊ˨˩˦ kaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这个桶有盖，雨水进不去。", "target_word": "有盖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "汤锅有盖，所以汤凉得慢。", "target_word": "有盖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个罐子有盖，里面的糖很干净。", "target_word": "有盖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的垃圾桶有盖，苍蝇飞不进去。", "target_word": "有盖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为茶杯有盖，茶放了很久还是热的。", "target_word": "有盖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "井口有盖，小孩不会掉进去。", "target_word": "有盖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个盒子有盖，你可以放心地装饼干。", "target_word": "有盖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请选有盖的米桶，米才不会受潮。", "target_word": "有盖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家的水缸有盖，里面的水很干净。", "target_word": "有盖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个箱子有盖，下雨也不怕。", "target_word": "有盖", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "有蓋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有盖：东西上有盖子盖着（多作谓语）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ac3a786-371a-4f7d-8564-033c6288d3f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21122, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有盖", "is_correct": true, "explanation": "正确：“有盖”说桶上有盖子，与“雨水进不去”的结果相符。"}, {"text": "无盖", "is_correct": false, "explanation": "语义：桶没有盖子，雨水会进去，与“雨水进不去”矛盾。"}, {"text": "敞开", "is_correct": false, "explanation": "语义：桶口敞开，雨水就能进去，与后半句矛盾。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人的身材，不用来形容桶。"}], "explanations": {"有盖": "正确：“有盖”说桶上有盖子，与“雨水进不去”的结果相符。", "无盖": "语义：桶没有盖子，雨水会进去，与“雨水进不去”矛盾。", "敞开": "语义：桶口敞开，雨水就能进去，与后半句矛盾。", "瘦": "体貌：“瘦”形容人的身材，不用来形容桶。"}, "sentence_index": 0, "correct_answer": "有盖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个亭子有盖，下雨也能坐。", "explanation": "这里应该用〈有顶〉。“有盖”指器物有盖子，亭子的遮蔽部分要说“有顶”。"}, {"text": "这把剑有盖，携带很方便。", "explanation": "这里应该用〈有鞘〉。“有盖”用于容器，剑的护套要说“有鞘”。"}, {"text": "这片草地有盖，踩上去很软。", "explanation": "这里应该用〈露天〉。“有盖”指器物盖着盖子，草地是露天的，不能说有盖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有盖", "is_correct": true, "explanation": "正确：盒子“有盖”，才能“放心地装饼干”，语义连贯。"}, {"text": "脏", "is_correct": false, "explanation": "语义：盒子脏了，就不能放心地装饼干，与句意矛盾。"}, {"text": "湿", "is_correct": false, "explanation": "搭配：“湿”多用于衣物、土地、纸张，不说盒子湿，且与“放心装饼干”矛盾。"}, {"text": "破", "is_correct": false, "explanation": "语义：盒子破了就装不住东西，与“放心地装饼干”矛盾。"}], "explanations": {"有盖": "正确：盒子“有盖”，才能“放心地装饼干”，语义连贯。", "脏": "语义：盒子脏了，就不能放心地装饼干，与句意矛盾。", "湿": "搭配：“湿”多用于衣物、土地、纸张，不说盒子湿，且与“放心装饼干”矛盾。", "破": "语义：盒子破了就装不住东西，与“放心地装饼干”矛盾。"}, "sentence_index": 6, "correct_answer": "有盖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只乌龟有盖，不怕敌人。", "explanation": "这里应该用〈有壳〉。“有盖”用于容器，乌龟背上的硬壳要说“有壳”。"}, {"text": "这扇柜门有盖，孩子拿不到。", "explanation": "这里应该用〈有锁〉。“有盖”指容器的盖子，柜门的锁要说“有锁”。"}, {"text": "这条裤子有盖，穿起来很暖和。", "explanation": "这里应该用〈袋盖〉。“有盖”指容器的盖子，裤子口袋上的翻盖要说“袋盖”，裤子整体不能说有盖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个木桶的有盖，雨水进不去。", "corrected_sentence": "这个木桶有盖，雨水进不去。", "error_description": "多加了“的”：“有盖”在这里作谓语，前面不能加“的”。应去掉“的”，说“这个木桶有盖”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个纸箱不有盖，装东西时很方便。", "corrected_sentence": "这个纸箱有盖，装东西时很方便。", "error_description": "否定词误用：“有”不能直接加“不”。句子表示肯定，应去掉“不”，说“有盖”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
