INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21124, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "两面墙碰在一起的地方。", "primary_collocate": null, "pronunciation": "jiǎo luò", "ipa": "tɕjɑʊ˨˩˦ lwo˥˩", "syllable_count": 2, "sentences": [{"text": "房间的四个角落都很干净。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子放在墙的角落。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让他站在教室的角落。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在客厅的角落放一盆花。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "角落里有一个小书架。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟从角落里拿出了球。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个角落太暗，要买盏灯。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书柜放在房间右边的角落。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蜘蛛在角落里织了一张网。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房的一个角落摆着一张小桌子。", "target_word": "角落", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "房间里两面墙相交的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d079ee5-3e48-4f10-9b81-1c61d5a1cf7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21124, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "角落", "is_correct": true, "explanation": "正确。两面墙相交的地方，房间的四个角落都可以是干净的。"}, {"text": "答案", "is_correct": false, "explanation": "语义：“答案”不是房间里的物体，与“房间的”这一限定冲突。"}, {"text": "地铁站", "is_correct": false, "explanation": "语义：地铁站不在房间里，与“房间的四个”的范围不符。"}, {"text": "角色", "is_correct": false, "explanation": "搭配：“干净”不能用来修饰“角色”，“房间的四个角色都很干净”搭配不当。"}], "explanations": {"角落": "正确。两面墙相交的地方，房间的四个角落都可以是干净的。", "答案": "语义：“答案”不是房间里的物体，与“房间的”这一限定冲突。", "地铁站": "语义：地铁站不在房间里，与“房间的四个”的范围不符。", "角色": "搭配：“干净”不能用来修饰“角色”，“房间的四个角色都很干净”搭配不当。"}, "sentence_index": 0, "correct_answer": "角落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在剧中扮演的角落很重要。", "explanation": "这里应该用〈角色〉。角落指墙相交的地方或隐蔽处，扮演的是角色，两词只是都带“角”字，不能互换。"}, {"text": "这次讨论的角落是学习方法。", "explanation": "这里应该用〈重点〉。角落不指事情的核心内容，说讨论的核心要用重点。"}, {"text": "老师从不同的角落解释这道题。", "explanation": "这里应该用〈角度〉。从不同方面解释问题要说角度，角落只指空间中的墙角或隐蔽处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "角落", "is_correct": true, "explanation": "正确。这个角落光线暗，所以要买盏灯，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能靠买灯照亮，与“要买盏灯”的前后文冲突。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“暗”不用来形容味道，“这个味道太暗”搭配不当。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是抽象的称呼，没有明暗的光线属性，与“太暗”冲突。"}], "explanations": {"角落": "正确。这个角落光线暗，所以要买盏灯，符合句意。", "天空": "语义：天空不能靠买灯照亮，与“要买盏灯”的前后文冲突。", "味道": "搭配：“暗”不用来形容味道，“这个味道太暗”搭配不当。", "名字": "语义：名字是抽象的称呼，没有明暗的光线属性，与“太暗”冲突。"}, "sentence_index": 6, "correct_answer": "角落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房的一条角落摆着一张小桌子。", "explanation": "这里应该用〈个〉。角落的量词是“个”，“条”用于长条形的东西，不能修饰角落。"}, {"text": "厨房的一把角落摆着一张小桌子。", "explanation": "这里应该用〈个〉。“把”用于有柄的器具，角落不用“把”来计量。"}, {"text": "厨房的一只角落摆着一张小桌子。", "explanation": "这里应该用〈个〉。“只”用于动物或成对物件中的一个，角落不用“只”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "阳台的一只角落里堆着几个纸箱。", "corrected_sentence": "阳台的一个角落里堆着几个纸箱。", "error_description": "错误：“角落”的量词用了“只”。正确应为“个”，“只”用于动物或成对物件中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把椅子放在角落里里了。", "corrected_sentence": "他把椅子放在角落里了。", "error_description": "错误：“里”重复。“角落里”已含方位词“里”，不能再加“里”，应说“放在角落里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05030ce3-f21a-44f9-bf39-9689e15e3392') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
