INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21128, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小孔就是一个小小的洞。", "primary_collocate": null, "pronunciation": "xiǎo kǒng", "ipa": "ɕjɑʊ̯˨˩˦ kʰʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "墙上有一个小孔，我能从那里看到外面。", "target_word": "小孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木板上有一个小孔，光线从小孔里透了过来。", "target_word": "小孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头上有个小孔，里面住着小虫。", "target_word": "小孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鞋底有一个小孔，下雨天脚会湿。", "target_word": "小孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在门上挖了一个小孔，想看看外面。", "target_word": "小孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水桶有个小孔，水一点一点流出来。", "target_word": "小孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗纸上有几个小孔，风吹了进来。", "target_word": "小孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在纸盒上开了一个小孔，把线穿过去。", "target_word": "小孔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布上的小孔是虫子咬的。", "target_word": "小孔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球上有个小孔，所以不能打气。", "target_word": "小孔", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "一个小小的洞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c5c45db-5c3c-48d5-93a0-704ede77efae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小孔", "is_correct": true, "explanation": "小孔：墙上的小洞，可以从中往外看，符合句意。"}, {"text": "挂钟", "is_correct": false, "explanation": "语义：挂钟是挂在墙上计时的钟表，没有可以“往外看”的孔洞。"}, {"text": "盖子", "is_correct": false, "explanation": "语义：盖子是用来遮盖容器的，不能让人从它往外看。"}, {"text": "海报", "is_correct": false, "explanation": "搭配：量词“个”不与“海报”搭配，应说“张”；且海报也不能让人从中往外看。"}], "explanations": {"小孔": "小孔：墙上的小洞，可以从中往外看，符合句意。", "挂钟": "语义：挂钟是挂在墙上计时的钟表，没有可以“往外看”的孔洞。", "盖子": "语义：盖子是用来遮盖容器的，不能让人从它往外看。", "海报": "搭配：量词“个”不与“海报”搭配，应说“张”；且海报也不能让人从中往外看。"}, "sentence_index": 0, "correct_answer": "小孔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "木板上有一根小孔，光线从那里透过来。", "explanation": "这里应该用〈个〉。“根”用于细长的东西，小孔不用“根”来计量。"}, {"text": "这个计划里有很多小孔，需要认真修改。", "explanation": "这里应该用〈缺陷〉。小孔指实物上的小洞，计划中的不足要说“缺陷”。"}, {"text": "他的推理有一个小孔，很容易被反驳。", "explanation": "这里应该用〈漏洞〉。小孔指实物上的小洞，推理中不严密的地方要说“漏洞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小孔", "is_correct": true, "explanation": "小孔：窗纸上的小洞，风能从中吹进来，符合句意。"}, {"text": "指纹", "is_correct": false, "explanation": "语义：指纹是手指留下的印迹，不是窗纸上的洞，“风吹了进来”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗纸上不能有窗户，句意说不通。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：窗纸上不会有台灯，与“风吹进来”毫无关系。"}], "explanations": {"小孔": "小孔：窗纸上的小洞，风能从中吹进来，符合句意。", "指纹": "语义：指纹是手指留下的印迹，不是窗纸上的洞，“风吹了进来”说不通。", "窗户": "语义：窗纸上不能有窗户，句意说不通。", "台灯": "语义：窗纸上不会有台灯，与“风吹进来”毫无关系。"}, "sentence_index": 6, "correct_answer": "小孔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布上有一只小孔，所以不能用。", "explanation": "这里应该用〈个〉。“只”用于动物，小孔不能用“只”来计量。"}, {"text": "他的手腕上被划了一个小孔，血流不止。", "explanation": "这里应该用〈伤口〉。小孔指物体上的洞，身体受伤的地方要说“伤口”。"}, {"text": "公司账上亏了一个小孔，需要尽快补上。", "explanation": "这里应该用〈窟窿〉。小孔指物体上的小洞，账目上的亏空要说“窟窿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门板上有一根小孔，透过它能看到外面。", "corrected_sentence": "门板上有一个小孔，透过它能看到外面。", "error_description": "量词错误：“小孔”应说“一个小孔”，“根”用于细长的东西，不能用于小孔。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "瓶盖中间有一个很小孔，液体才能慢慢流出来。", "corrected_sentence": "瓶盖中间有一个小孔，液体才能慢慢流出来。", "error_description": "程度副词错误：“小孔”是名词，前面不能直接加“很”，此处应说“一个小孔”；“很小”后面要加“的”，写作“很小的孔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
