INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21132, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让水流走。", "primary_collocate": null, "pronunciation": "pái shuǐ", "ipa": "pʰaɪ̯˧˥ ʂweɪ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "洗完澡，要拔掉塞子排水。", "target_word": "排水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后马路上有很多水，要快点排水。", "target_word": "排水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盆底有孔，浇水后能排水。", "target_word": "排水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下室进水了，工人正在排水。", "target_word": "排水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下水道堵了，没办法排水。", "target_word": "排水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "稻田里水太多，农民开了小沟排水。", "target_word": "排水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳池换水前，要先排水。", "target_word": "排水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台机器是用来排水的。", "target_word": "排水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屋顶是斜的，下雨时方便排水。", "target_word": "排水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花盆里的土要松，这样才好排水。", "target_word": "排水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "排了水", "label": "体标"}, {"form": "排过水", "label": "体标"}, {"form": "排水沟", "label": "复合"}], "register": "中性", "sense_fingerprint": "让水流走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c5c45db-5c3c-48d5-93a0-704ede77efae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21132, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "排水", "is_correct": true, "explanation": "排水（pái shuǐ）指让水流走，是正确答案。"}, {"text": "白水", "is_correct": false, "explanation": "bái（第二声）与 pái（第二声）声调相同，但声母由 p 变为 b，意思是白开水。"}, {"text": "抬水", "is_correct": false, "explanation": "tái（第二声）与 pái（第二声）声调相同，声母由 p 变为 t，意思是把水抬起来或挑水。"}, {"text": "拍水", "is_correct": false, "explanation": "pāi（第一声）与 pái（第二声）声调不同，意思是拍打水面。"}], "explanations": {"排水": "排水（pái shuǐ）指让水流走，是正确答案。", "白水": "bái（第二声）与 pái（第二声）声调相同，但声母由 p 变为 b，意思是白开水。", "抬水": "tái（第二声）与 pái（第二声）声调相同，声母由 p 变为 t，意思是把水抬起来或挑水。", "拍水": "pāi（第一声）与 pái（第二声）声调不同，意思是拍打水面。"}, "sentence_index": null, "correct_answer": "排水"}, "level_3": {"options": [{"text": "排水", "is_correct": true, "explanation": "排水：拔掉塞子就是为了让水流走，符合句意。"}, {"text": "注水", "is_correct": false, "explanation": "语义：拔掉塞子是为了放水，注水与此矛盾。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：句意是洗完澡后拔掉塞子让水流走，接“洗澡”不合句意。"}, {"text": "充电", "is_correct": false, "explanation": "语义：拔掉塞子与充电无关，句意不通。"}], "explanations": {"排水": "排水：拔掉塞子就是为了让水流走，符合句意。", "注水": "语义：拔掉塞子是为了放水，注水与此矛盾。", "洗澡": "语义：句意是洗完澡后拔掉塞子让水流走，接“洗澡”不合句意。", "充电": "语义：拔掉塞子与充电无关，句意不通。"}, "sentence_index": 0, "correct_answer": "排水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "皮肤干燥的时候，要多排水。", "explanation": "这里应该用〈补水〉。排水是把多余的水排出去，给身体补充水分要说“补水”。"}, {"text": "用勺子排水，把杯子装满。", "explanation": "这里应该用〈舀水〉。排水是让水流走，用勺子取水要说“舀水”。"}, {"text": "他提着桶到井边排水。", "explanation": "这里应该用〈打水〉。排水是让水流走，从井里取水要说“打水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "排水", "is_correct": true, "explanation": "排水：换水前要先把旧水排掉，符合句意。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：换水前先去游泳，与句意不符。"}, {"text": "进水", "is_correct": false, "explanation": "语义：换水前先进水，与“换水”的步骤矛盾。"}, {"text": "加热", "is_correct": false, "explanation": "语义：换水前先加热，与换水的步骤不符，句意不通。"}], "explanations": {"排水": "排水：换水前要先把旧水排掉，符合句意。", "游泳": "语义：换水前先去游泳，与句意不符。", "进水": "语义：换水前先进水，与“换水”的步骤矛盾。", "加热": "语义：换水前先加热，与换水的步骤不符，句意不通。"}, "sentence_index": 6, "correct_answer": "排水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他忽然朝我排水，弄得我全身湿透。", "explanation": "这里应该用〈泼水〉。排水是让水流走，朝人身上泼水要说“泼水”。"}, {"text": "消防车朝火场排水灭火。", "explanation": "这里应该用〈喷水〉。排水是让水流走，消防车向火场喷水要说“喷水”。"}, {"text": "来了客人，他急忙给客人排水。", "explanation": "这里应该用〈倒水〉。排水是让水流走，给人斟水要说“倒水”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下雨以后，我们给院子排水得很快。", "corrected_sentence": "下雨以后，我们给院子排水排得很快。", "error_description": "补语错误：“排水”是动宾结构，带“得”补语时要重复动词“排”，应说“排水排得很快”，不能说“排水得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个地下停车场很排水，雨一停就干了。", "corrected_sentence": "这个地下停车场很能排水，雨一停就干了。", "error_description": "程度副词错误：“很”不能直接修饰动作动词“排水”，须在“排水”前加能愿动词“能”，应说“很能排水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
