INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21134, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "铺是把东西平着放好。", "primary_collocate": null, "pronunciation": "pū", "ipa": "pʰu˥", "syllable_count": 1, "sentences": [{"text": "他把垫子铺平，然后坐了下来。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先在地上铺一张报纸，再刷墙。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶每天早上都先铺床。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把桌布铺好，客人快到了。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在沙发上铺了一条毯子。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在地上铺开了地图。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路面刚铺好，不要踩。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在操场上铺着垫子做操。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铺好床单后，她把枕头放上去。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他铺了一层塑料布，防止地板弄脏。", "target_word": "铺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "铺了", "label": "体标（完成）"}, {"form": "铺着", "label": "体标（持续）"}, {"form": "铺平", "label": "复合"}, {"form": "铺开", "label": "复合"}], "register": "中性", "sense_fingerprint": "把东西平整地摆放好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ac3a786-371a-4f7d-8564-033c6288d3f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21134, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "铺", "is_correct": true, "explanation": "正确答案：铺（pū），意思是把东西平整地摆放好。"}, {"text": "谱", "is_correct": false, "explanation": "谱（pǔ）与 pū 声调不同（第三声），意思是乐谱或图谱。"}, {"text": "脯", "is_correct": false, "explanation": "脯（pú）与 pū 声调不同（第二声），意思是肉干或胸脯。"}, {"text": "批", "is_correct": false, "explanation": "批（pī）与 pū 的韵母不同（i 与 u），意思是批准或批评。"}, {"text": "夫", "is_correct": false, "explanation": "夫（fū）与 pū 声母不同（f 与 p），意思是丈夫。"}], "explanations": {"铺": "正确答案：铺（pū），意思是把东西平整地摆放好。", "谱": "谱（pǔ）与 pū 声调不同（第三声），意思是乐谱或图谱。", "脯": "脯（pú）与 pū 声调不同（第二声），意思是肉干或胸脯。", "批": "批（pī）与 pū 的韵母不同（i 与 u），意思是批准或批评。", "夫": "夫（fū）与 pū 声母不同（f 与 p），意思是丈夫。"}, "sentence_index": null, "correct_answer": "铺"}, "level_3": {"options": [{"text": "铺", "is_correct": true, "explanation": "正确答案：铺。把垫子铺平，指把垫子平整地摆好。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕是扯破，会把垫子弄坏，不能把垫子弄平。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是抛掷，与“平”的结果不相符，句子不通。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：拆指拆开、分解，不能与“平”搭配表示把垫子弄平。"}], "explanations": {"铺": "正确答案：铺。把垫子铺平，指把垫子平整地摆好。", "撕": "语义：撕是扯破，会把垫子弄坏，不能把垫子弄平。", "扔": "语义：扔是抛掷，与“平”的结果不相符，句子不通。", "拆": "搭配：拆指拆开、分解，不能与“平”搭配表示把垫子弄平。"}, "sentence_index": 0, "correct_answer": "铺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把碗铺好，放在桌上。", "explanation": "这里更自然的是〈摆〉。碗是立体的器物，不能像布、纸一样展开平放，摆好更自然。"}, {"text": "请把杯子铺好，客人快到了。", "explanation": "这里应该用〈放〉。杯子不能展开成一片，应说放好。"}, {"text": "她把帽子铺好，挂在门口。", "explanation": "这里应该用〈挂〉。帽子不能平展铺开，挂在门口要说挂好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21134, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "铺", "is_correct": true, "explanation": "正确答案：铺（pū），意思是把东西平整地摆放好。"}, {"text": "普", "is_correct": false, "explanation": "普（pǔ）与 pū 声调不同（第三声），意思是普遍、普通。"}, {"text": "葡", "is_correct": false, "explanation": "葡（pú）与 pū 声调不同（第二声），常见于“葡萄”。"}, {"text": "趴", "is_correct": false, "explanation": "趴（pā）与 pū 的韵母不同（a 与 u），意思是伏在某物上。"}, {"text": "朴", "is_correct": false, "explanation": "朴（pǔ）与 pū 声调不同（第三声），意思是朴素。"}], "explanations": {"铺": "正确答案：铺（pū），意思是把东西平整地摆放好。", "普": "普（pǔ）与 pū 声调不同（第三声），意思是普遍、普通。", "葡": "葡（pú）与 pū 声调不同（第二声），常见于“葡萄”。", "趴": "趴（pā）与 pū 的韵母不同（a 与 u），意思是伏在某物上。", "朴": "朴（pǔ）与 pū 声调不同（第三声），意思是朴素。"}, "sentence_index": null, "correct_answer": "铺"}, "level_3": {"options": [{"text": "铺", "is_correct": true, "explanation": "正确答案：铺。路面刚铺好，指把材料平整地摊开铺成路面。"}, {"text": "剪", "is_correct": false, "explanation": "搭配：剪用于裁断布料、纸张等，不能用于路面。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：缝指用针线连接布料，不说缝路面。"}, {"text": "织", "is_correct": false, "explanation": "语义：织是编织线或布料的动作，与路面无关，句子不通。"}], "explanations": {"铺": "正确答案：铺。路面刚铺好，指把材料平整地摊开铺成路面。", "剪": "搭配：剪用于裁断布料、纸张等，不能用于路面。", "缝": "搭配：缝指用针线连接布料，不说缝路面。", "织": "语义：织是编织线或布料的动作，与路面无关，句子不通。"}, "sentence_index": 6, "correct_answer": "铺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把皮鞋铺亮了。", "explanation": "这里应该用〈擦〉。擦亮是用布摩擦使物体发光，皮鞋上光要说擦；铺只表示展开平放，不能使物体发亮。"}, {"text": "他在钢琴前铺了一首曲子。", "explanation": "这里应该用〈弹〉。弹是用手指按琴键演奏，一首曲子要弹；铺只表示展开平放，不能用于演奏。"}, {"text": "他在作业本上铺了三行字。", "explanation": "这里应该用〈写〉。写是用笔记录文字，三行字要写；铺只表示展开平放，不能用于写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把床单铺了平，再放枕头。", "corrected_sentence": "妈妈把床单铺平了，再放枕头。", "error_description": "错误形式：铺了平；正确形式：铺平了。“平”是结果补语，应紧跟在动词“铺”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "操场上铺了着一层红色的软垫。", "corrected_sentence": "操场上铺着一层红色的软垫。", "error_description": "错误形式：铺了着；正确形式：铺着。“铺”后的“了”和“着”不能同时使用，表示持续状态只用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
