INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21136, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "箱子最下面的那一部分。", "primary_collocate": null, "pronunciation": "xiāng dǐ", "ipa": "ɕjɑŋ˥ ti˨˩˦", "syllable_count": 2, "sentences": [{"text": "箱底有点湿，快把东西拿出来。", "target_word": "箱底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行李箱的箱底坏了。", "target_word": "箱底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在箱底放一张报纸。", "target_word": "箱底", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "箱底太薄，重东西会掉下来。", "target_word": "箱底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "纸箱的箱底要用胶带粘好。", "target_word": "箱底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫钻进箱子，睡在箱底。", "target_word": "箱底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "苹果掉到箱底去了，我拿不到。", "target_word": "箱底", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "箱底不平，箱子放不稳。", "target_word": "箱底", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把笔放在箱底，上面盖了衣服。", "target_word": "箱底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱底的螺丝松了，得拧紧。", "target_word": "箱底", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "箱底：箱子最下面的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ac3a786-371a-4f7d-8564-033c6288d3f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21136, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "箱底", "is_correct": true, "explanation": "正确答案：箱底（xiāng dǐ），指箱子最下面的部分。"}, {"text": "江底", "is_correct": false, "explanation": "jiāng 与 xiāng 声母不同（j 与 x），意思是江底，即河流的底部。"}, {"text": "相比", "is_correct": false, "explanation": "bǐ 与 dǐ 声母不同（b 与 d），意思是相比。"}, {"text": "乡里", "is_correct": false, "explanation": "lǐ 与 dǐ 声母不同（l 与 d），意思是乡里，即家乡。"}, {"text": "巷底", "is_correct": false, "explanation": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是小巷的尽头。"}], "explanations": {"箱底": "正确答案：箱底（xiāng dǐ），指箱子最下面的部分。", "江底": "jiāng 与 xiāng 声母不同（j 与 x），意思是江底，即河流的底部。", "相比": "bǐ 与 dǐ 声母不同（b 与 d），意思是相比。", "乡里": "lǐ 与 dǐ 声母不同（l 与 d），意思是乡里，即家乡。", "巷底": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是小巷的尽头。"}, "sentence_index": null, "correct_answer": "箱底"}, "level_3": {"options": [{"text": "箱底", "is_correct": true, "explanation": "箱底是箱子最下面的部分，箱底有点湿，就该把东西拿出来，与语境相符。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不是装东西的容器，“快把东西拿出来”与窗帘无关。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线不装东西，说它“有点湿，快把东西拿出来”没有道理。"}, {"text": "拉链", "is_correct": false, "explanation": "搭配：拉链是开合用的部件，不说“有点湿，快把东西拿出来”这样的话。"}], "explanations": {"箱底": "箱底是箱子最下面的部分，箱底有点湿，就该把东西拿出来，与语境相符。", "窗帘": "语义：窗帘不是装东西的容器，“快把东西拿出来”与窗帘无关。", "电线": "语义：电线不装东西，说它“有点湿，快把东西拿出来”没有道理。", "拉链": "搭配：拉链是开合用的部件，不说“有点湿，快把东西拿出来”这样的话。"}, "sentence_index": 0, "correct_answer": "箱底"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "箱底关不上了，里面的东西太多。", "explanation": "这里应该用〈箱盖〉。能关上、合上的是箱盖，箱底只是箱子最下面的部分，不能“关”。"}, {"text": "这只木桶的箱底太薄，装满水就会漏。", "explanation": "这里应该用〈桶底〉。箱底只指箱子最下面的部分，木桶的底部要说“桶底”。"}, {"text": "这双旧球鞋的箱底磨平了，得换一双。", "explanation": "这里应该用〈鞋底〉。箱底只指箱子最下面的部分，鞋的底部要说“鞋底”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "箱底", "is_correct": true, "explanation": "苹果掉到箱子最下面的部分，我拿不到，“箱底”与语境相符。"}, {"text": "箱盖", "is_correct": false, "explanation": "语义：箱盖在箱子的上面，苹果不会掉到箱盖去。"}, {"text": "箱锁", "is_correct": false, "explanation": "语义：箱锁是锁箱子的装置，苹果不会掉到箱锁上。"}, {"text": "箱带", "is_correct": false, "explanation": "语义：箱带是提拿或捆扎用的带子，苹果不会掉到箱带上。"}], "explanations": {"箱底": "苹果掉到箱子最下面的部分，我拿不到，“箱底”与语境相符。", "箱盖": "语义：箱盖在箱子的上面，苹果不会掉到箱盖去。", "箱锁": "语义：箱锁是锁箱子的装置，苹果不会掉到箱锁上。", "箱带": "语义：箱带是提拿或捆扎用的带子，苹果不会掉到箱带上。"}, "sentence_index": 6, "correct_answer": "箱底"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这口锅的箱底有一块焦痕，得刷干净。", "explanation": "这里应该用〈锅底〉。箱底只指箱子最下面的部分，锅的底部要说锅底。"}, {"text": "墙角的箱底裂了，要找人修。", "explanation": "这里应该用〈墙根〉。箱底只指箱子最下面的部分，墙的最下部要说“墙根”。"}, {"text": "桌子的箱底不稳，得垫一垫。", "explanation": "这里应该用〈桌脚〉。箱底只指箱子最下面的部分，桌子的腿要说“桌脚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用胶带把一条箱底粘好了。", "corrected_sentence": "我用胶带把箱底粘好了。", "error_description": "错误形式：一条箱底；正确形式：箱底。“条”用于细长的东西，箱底是箱子的一部分，不能用“条”计量，应去掉量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把两条箱底擦干净了。", "corrected_sentence": "他把箱底擦干净了。", "error_description": "错误形式：两条箱底；正确形式：箱底。“条”不能用来计量箱底，应直接说“箱底”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b6ee8fb-7afa-4781-bcae-c7113ae9aecc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
