INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21142, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把要加入或相加的东西全部放进去或算完。", "primary_collocate": null, "pronunciation": "jiā wán", "ipa": "tɕja˥ wan˧˥", "syllable_count": 2, "sentences": [{"text": "我加完水就走。", "target_word": "加完", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "车加完油，我们就出发了。", "target_word": "加完", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把糖都加完了，还是不甜。", "target_word": "加完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你加完盐，请马上告诉我。", "target_word": "加完", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些数我已经加完了，一共是一百。", "target_word": "加完", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我把这些数字加完。", "target_word": "加完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈加完最后一点醋，就去看电视。", "target_word": "加完", "complexity_tier": "T3", "furigana": "mā ma jiā wán zuìhòu yì diǎn cù, jiù qù kàn diànshì.", "sentence_source": "generated"}, {"text": "工人加完最后一桶水，回家了。", "target_word": "加完", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他加完这一行数字，写下了答案。", "target_word": "加完", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "机器里的水加完以后，要等十分钟。", "target_word": "加完", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "加完了", "label": "体标"}, {"form": "加不完", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "把要加的东西全部加完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a3d56dd-11e0-4e6c-9189-3f9142d08cf1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21142, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加完", "is_correct": true, "explanation": "“加完水”指水加完了，然后离开，符合句意。"}, {"text": "加强", "is_correct": false, "explanation": "搭配：“加强”说力量或程度，不能说“加强水”。"}, {"text": "加速", "is_correct": false, "explanation": "搭配：“加速”指速度变快，不能与“水”搭配。"}, {"text": "加重", "is_correct": false, "explanation": "语义：“加重”指分量或程度增加，与“水”的动作不符。"}], "explanations": {"加完": "“加完水”指水加完了，然后离开，符合句意。", "加强": "搭配：“加强”说力量或程度，不能说“加强水”。", "加速": "搭配：“加速”指速度变快，不能与“水”搭配。", "加重": "语义：“加重”指分量或程度增加，与“水”的动作不符。"}, "sentence_index": 0, "correct_answer": "加完"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我加完作业就睡觉。", "explanation": "这里应该用〈做完〉。作业是做的，不能用“加”。"}, {"text": "我加完澡就睡觉。", "explanation": "这里应该用〈洗完〉。澡是洗的，不能用“加”。"}, {"text": "我加完电影就回家。", "explanation": "这里应该用〈看完〉。电影是看的，不能用“加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21142, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加完", "is_correct": true, "explanation": "“加完最后一点醋”指醋都加入了，之后才去看电视，符合句意。"}, {"text": "拧", "is_correct": false, "explanation": "搭配：“拧”指扭转，不说“拧醋”。"}, {"text": "关", "is_correct": false, "explanation": "搭配：“关”不用于醋，不说“关醋”。"}, {"text": "剩", "is_correct": false, "explanation": "语义：“剩”表示剩余，与“就去看电视”所说的已加完不符。"}], "explanations": {"加完": "“加完最后一点醋”指醋都加入了，之后才去看电视，符合句意。", "拧": "搭配：“拧”指扭转，不说“拧醋”。", "关": "搭配：“关”不用于醋，不说“关醋”。", "剩": "语义：“剩”表示剩余，与“就去看电视”所说的已加完不符。"}, "sentence_index": 6, "correct_answer": "加完"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他加完桌子就走。", "explanation": "这里应该用〈擦完〉。桌子是擦的，不能用“加”。"}, {"text": "这篇作文我加完了。", "explanation": "这里应该用〈写完〉。作文是写的，不能用“加”。"}, {"text": "他加完门就走。", "explanation": "这里应该用〈关完〉。门是关的，不能用“加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把水加完过，就走了。", "corrected_sentence": "他把水加完了，就走了。", "error_description": "“加完”表示动作已完成，后面的体标应用“了”，不能用“过”，应说“加完了”，不说“加完过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还不加完盐，你先等等。", "corrected_sentence": "我还没加完盐，你先等等。", "error_description": "表示“完成”的否定要用“没”，应说“还没加完”，不能用“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2dc5da5-3bc2-4b6d-9400-be58d8a1e31b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
