INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21146, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做事情。", "primary_collocate": null, "pronunciation": "gàn", "ipa": "kan˥˩", "syllable_count": 1, "sentences": [{"text": "你今天在家干什么？", "target_word": "干", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他干得很认真，大家都喜欢他。", "target_word": "干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事你别干了，太危险。", "target_word": "干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种事我从来没干过。", "target_word": "干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作太累，我不想干了。", "target_word": "干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这么多活儿，我一个人干不完。", "target_word": "干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在工厂干了十年。", "target_word": "干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要干就好好干，别半途而废。", "target_word": "干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作我干了三年，已经习惯了。", "target_word": "干", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚了，你还在干什么呢？", "target_word": "干", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "干了", "label": "体标"}, {"form": "干过", "label": "体标"}, {"form": "干着", "label": "体标"}, {"form": "干活", "label": "复合"}, {"form": "苦干", "label": "复合"}, {"form": "幹", "label": "繁体"}], "register": "口语", "sense_fingerprint": "干:做、从事某事(gàn)", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2b68117-69f0-4db3-8b42-afed4406c8c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21146, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "干", "is_correct": true, "explanation": "正确答案：干（gàn），意思是做事情。"}, {"text": "看", "is_correct": false, "explanation": "kàn（第四声）与 gàn 声母不同（k/g），意思是看。"}, {"text": "汉", "is_correct": false, "explanation": "hàn（第四声）与 gàn 声母不同（h/g），意思是汉族。"}, {"text": "赶", "is_correct": false, "explanation": "gǎn（第三声）与 gàn 声调不同，意思是赶快。"}, {"text": "甘", "is_correct": false, "explanation": "gān（第一声）与 gàn 声调不同，意思是甘甜。"}], "explanations": {"干": "正确答案：干（gàn），意思是做事情。", "看": "kàn（第四声）与 gàn 声母不同（k/g），意思是看。", "汉": "hàn（第四声）与 gàn 声母不同（h/g），意思是汉族。", "赶": "gǎn（第三声）与 gàn 声调不同，意思是赶快。", "甘": "gān（第一声）与 gàn 声调不同，意思是甘甜。"}, "sentence_index": null, "correct_answer": "干"}, "level_3": {"options": [{"text": "干", "is_correct": true, "explanation": "正确：干在此指做事情，与问句“做什么”搭配。"}, {"text": "爬", "is_correct": false, "explanation": "搭配：“在家”里的活动不能用“爬”来组成这样的询问。"}, {"text": "游", "is_correct": false, "explanation": "语义：游需要水域或场地，在家里“游”不成立。"}, {"text": "飞", "is_correct": false, "explanation": "语义：飞是在空中移动，“在家飞什么”不成立，与问句不搭。"}], "explanations": {"干": "正确：干在此指做事情，与问句“做什么”搭配。", "爬": "搭配：“在家”里的活动不能用“爬”来组成这样的询问。", "游": "语义：游需要水域或场地，在家里“游”不成立。", "飞": "语义：飞是在空中移动，“在家飞什么”不成立，与问句不搭。"}, "sentence_index": 0, "correct_answer": "干"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都要干脸。", "explanation": "这里应该用〈洗〉。“干”指做事情，洗脸要说“洗”，“干”不能与“脸”搭配。"}, {"text": "我昨天干了一台电脑。", "explanation": "这里应该用〈买〉。“干”指做事情，买电脑要说“买”，“干”不能表示购买。"}, {"text": "妈妈在厨房里干了一个苹果，然后放进了冰箱。", "explanation": "这里误把“干”当作加工、弄干的意思用在苹果上。“干”作“做事情”讲时宾语只能是事情或工作，不能是苹果这样的物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e82f6a0-beb9-4f40-83b9-f068af0d5d6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21146, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "干", "is_correct": true, "explanation": "正确答案：干（gàn），意思是做事情。"}, {"text": "半", "is_correct": false, "explanation": "bàn（第四声）与 gàn 声母不同（b/g），意思是一半。"}, {"text": "感", "is_correct": false, "explanation": "gǎn（第三声）与 gàn 声调不同，意思是感觉。"}, {"text": "杆", "is_correct": false, "explanation": "gān（第一声）与 gàn 声调不同，意思是杆子。"}, {"text": "肝", "is_correct": false, "explanation": "gān（第一声）与 gàn 声调不同，意思是肝脏。"}], "explanations": {"干": "正确答案：干（gàn），意思是做事情。", "半": "bàn（第四声）与 gàn 声母不同（b/g），意思是一半。", "感": "gǎn（第三声）与 gàn 声调不同，意思是感觉。", "杆": "gān（第一声）与 gàn 声调不同，意思是杆子。", "肝": "gān（第一声）与 gàn 声调不同，意思是肝脏。"}, "sentence_index": null, "correct_answer": "干"}, "level_3": {"options": [{"text": "干", "is_correct": true, "explanation": "正确：干在此指从事工作，与“在工厂”和“十年”的语境一致。"}, {"text": "睡", "is_correct": false, "explanation": "语义：在工厂睡了十年，与工作的语境完全不符。"}, {"text": "哭", "is_correct": false, "explanation": "语义：在工厂哭了十年，不符合“工作”的意思。"}, {"text": "游", "is_correct": false, "explanation": "搭配：“游”需要水域，工厂里不能游，与“在工厂”不搭配。"}], "explanations": {"干": "正确：干在此指从事工作，与“在工厂”和“十年”的语境一致。", "睡": "语义：在工厂睡了十年，与工作的语境完全不符。", "哭": "语义：在工厂哭了十年，不符合“工作”的意思。", "游": "搭配：“游”需要水域，工厂里不能游，与“在工厂”不搭配。"}, "sentence_index": 6, "correct_answer": "干"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天晚上都在床上干觉。", "explanation": "这里应该用〈睡〉。“干”指做事情，“觉”要说“睡”，“干觉”不能这样用。"}, {"text": "我一晚上干了三篇作文。", "explanation": "这里应该用〈写〉。“作文”要说“写”，“干”不能与“作文”搭配。"}, {"text": "他每天晚上都在房间里干游戏。", "explanation": "这里应该用〈玩〉。“干”指做事情，玩游戏要说“玩”，“干”不能与“游戏”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e82f6a0-beb9-4f40-83b9-f068af0d5d6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21146, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天都在办公室活干。", "corrected_sentence": "他每天都在办公室干活。", "error_description": "错误：活干。正确：干活。“干活”是动宾式的复合词，顺序不能颠倒。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e82f6a0-beb9-4f40-83b9-f068af0d5d6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21146, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子干很快。", "corrected_sentence": "这个孩子干得很快。", "error_description": "错误：干很快。正确：干得很快。动词后带补语时要用“动词+得+补语”，漏掉“得”就不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e82f6a0-beb9-4f40-83b9-f068af0d5d6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
