INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21148, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地里长出来的没用的草。", "primary_collocate": null, "pronunciation": "zá cǎo", "ipa": "tsa³⁵ tsʰɑʊ²¹⁴", "syllable_count": 2, "sentences": [{"text": "地里的杂草比菜还高。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每个周末去地里拔杂草。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂草没用，还会抢菜的养分。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，杂草一下子长出来了。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片杂草要割掉。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的杂草开着小黄花。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "羊在山坡上吃杂草。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用锄头除掉了杂草。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花盆里长出了几根杂草。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把杂草扔进了垃圾桶。", "target_word": "杂草", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "雜草", "label": "繁体"}, {"form": "一片杂草", "label": "量词"}], "register": "中性", "sense_fingerprint": "地里长出来的没用的草", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89d4eb5e-197e-43d1-89cf-33f8c82390e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21148, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "杂草", "is_correct": true, "explanation": "正确。杂草长在地里，可以比菜还高。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不会长在地里，句意不通。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不是植物，不会长在地里。"}, {"text": "高度", "is_correct": false, "explanation": "搭配：“高度”指高矮的数值，不能作主语说它比菜还高。"}], "explanations": {"杂草": "正确。杂草长在地里，可以比菜还高。", "房子": "语义：房子不会长在地里，句意不通。", "电视": "语义：电视不是植物，不会长在地里。", "高度": "搭配：“高度”指高矮的数值，不能作主语说它比菜还高。"}, "sentence_index": 0, "correct_answer": "杂草"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "花农在园子里栽了很多杂草。", "explanation": "这里应该用〈玫瑰〉。杂草不会被有意栽种，栽种的应是花卉等植物。"}, {"text": "田边长出了一头杂草。", "explanation": "这里应该用量词〈片〉。“头”用于牲畜，杂草应说“一片杂草”。"}, {"text": "路边的土里冒出了一朵杂草。", "explanation": "这里应该用量词〈丛〉。“朵”用于花朵，杂草成丛生长，应说“一丛杂草”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21148, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杂草", "is_correct": true, "explanation": "正确。羊可以吃杂草，杂草是野生的草本植物。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是食物，羊不会吃手机。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不是食物，不能被吃。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“吃”多搭配食物，不说吃空气。"}], "explanations": {"杂草": "正确。羊可以吃杂草，杂草是野生的草本植物。", "手机": "语义：手机不是食物，羊不会吃手机。", "钥匙": "语义：钥匙不是食物，不能被吃。", "空气": "搭配：“吃”多搭配食物，不说吃空气。"}, "sentence_index": 6, "correct_answer": "杂草"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民把杂草煮成了米饭。", "explanation": "这里应该用〈稻谷〉。米饭要用稻谷煮，杂草不能煮成米饭。"}, {"text": "他烤了一盘杂草。", "explanation": "这里应该用〈饼干〉。烤的应是饼干之类的烘焙食品，杂草不是烤制食品的常规原料。"}, {"text": "她每天练习杂草。", "explanation": "这里应该用〈钢琴〉。“练习”的对象应是乐器、技能等，杂草不是可以练习的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "田里的杂草又长出了来了。", "corrected_sentence": "田里的杂草又长出来了。", "error_description": "错误：“长出了来了”，“了”放错了位置。正确：“长出来了”，趋向补语“出来”之间不能插入“了”，“了”只放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一块杂草扔进了垃圾桶。", "corrected_sentence": "他把一片杂草扔进了垃圾桶。", "error_description": "量词错误：杂草应用量词“片”，“块”一般不用于杂草。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
