INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21150, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "让人生病的小东西。", "primary_collocate": null, "pronunciation": "bìng yuán tǐ", "ipa": "piŋ⁵¹ ɥɛn³⁵ tʰi²¹⁴", "syllable_count": 3, "sentences": [{"text": "小孩爱吃手，容易吃进病原体。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病原体太小，眼睛看不见。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用开水煮可以杀死病原体。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脏水里有很多病原体。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病原体进了身体，人就会发烧。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这种病原体是细菌。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗菜时要洗掉上面的病原体。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "口罩能挡住一部分病原体。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病是因为感染了病原体。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手上的病原体用肥皂就能洗掉。", "target_word": "病原体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "病原體", "label": "繁体"}], "register": "科技", "sense_fingerprint": "让人生病的微小东西，如细菌、病毒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89d4eb5e-197e-43d1-89cf-33f8c82390e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21150, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病原体", "is_correct": true, "explanation": "正确。病原体是让人生病的小东西，小孩可能会把它吃进去。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不是实物，不能被吃进身体。"}, {"text": "故事", "is_correct": false, "explanation": "搭配：“吃进”多搭配食物或异物，不说吃进故事。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是东西，不能被吃进身体。"}], "explanations": {"病原体": "正确。病原体是让人生病的小东西，小孩可能会把它吃进去。", "声音": "语义：声音不是实物，不能被吃进身体。", "故事": "搭配：“吃进”多搭配食物或异物，不说吃进故事。", "颜色": "语义：颜色不是东西，不能被吃进身体。"}, "sentence_index": 0, "correct_answer": "病原体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑中了病原体。", "explanation": "这里应该用〈病毒〉。病原体是能让人生病的小东西，不能指电脑中的程序。"}, {"text": "桌上放着一张病原体。", "explanation": "这里应该用量词〈种〉。“张”用于纸张、桌子等平面的东西，病原体应说“一种病原体”。"}, {"text": "做面包要用病原体。", "explanation": "这里应该用〈酵母〉。做面包要用酵母发酵，病原体会让人生病，不能用来做面包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21150, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病原体", "is_correct": true, "explanation": "正确。病原体会附着在蔬菜上，洗菜时可以被洗掉。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不会附着在蔬菜上，句意不通。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜不会附着在蔬菜上，句意不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“洗掉”多搭配污物，不说洗掉味道。"}], "explanations": {"病原体": "正确。病原体会附着在蔬菜上，洗菜时可以被洗掉。", "手机": "语义：手机不会附着在蔬菜上，句意不通。", "蔬菜": "语义：蔬菜不会附着在蔬菜上，句意不通。", "味道": "搭配：“洗掉”多搭配污物，不说洗掉味道。"}, "sentence_index": 6, "correct_answer": "病原体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上刷了一层病原体。", "explanation": "这里应该用〈颜料〉。病原体是让人生病的小东西，不能用来刷墙。"}, {"text": "护士给他打了一针病原体。", "explanation": "这里应该用〈疫苗〉。打针用的是能预防疾病的疫苗，病原体会让人生病。"}, {"text": "妈妈在汤里放了一勺病原体。", "explanation": "这里应该用〈盐〉。汤里放的应是调味品，病原体不能用来调味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多病原体们进了身体，人就会发烧。", "corrected_sentence": "很多病原体进了身体，人就会发烧。", "error_description": "“们”只用于指人，病原体不是人，不能加“们”表示复数，应说“很多病原体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "手上的一块病原体用肥皂就能洗掉。", "corrected_sentence": "手上的一种病原体用肥皂就能洗掉。", "error_description": "量词错误：病原体应用量词“种”，“块”多用于成块的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21152, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "疏忽", "is_correct": true, "explanation": "反义：疏忽表示不小心、不留心，与“注意身体”的保重之意相对。"}, {"text": "思考", "is_correct": false, "explanation": "思考是动脑子想问题，与注意没有反义关系。"}, {"text": "发现", "is_correct": false, "explanation": "发现与注意是近义关系，不是反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳是一种运动，与注意没有语义上的对立关系。"}], "correct_answer": "疏忽", "explanations": {"疏忽": "反义：疏忽表示不小心、不留心，与“注意身体”的保重之意相对。", "思考": "思考是动脑子想问题，与注意没有反义关系。", "发现": "发现与注意是近义关系，不是反义关系。", "游泳": "游泳是一种运动，与注意没有语义上的对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
