INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21156, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "剩下的东西。", "primary_collocate": null, "pronunciation": "cán yú", "ipa": "tsʰan˧˥ y˧˥", "syllable_count": 2, "sentences": [{"text": "我把盘子里的残余倒进了垃圾桶。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子里还有一点咖啡的残余。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完蛋糕，我把残余放进冰箱。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在吃我们饭后的残余。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有一些纸的残余。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用布的残余做了一个小包。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水里有一些油的残余。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙角堆着一些旧木头的残余。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗澡以后，身上没有香皂的残余。", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些残余还能用吗？", "target_word": "残余", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "殘餘", "label": "繁体"}, {"form": "残余物", "label": "复合"}], "register": "书面", "sense_fingerprint": "用过、吃过之后剩下的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67f2682a-e0a1-440d-a581-92febfcf3326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21156, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "残余", "is_correct": true, "explanation": "正确答案。残余（cán yú）指用过、吃过之后剩下的东西。"}, {"text": "蚕育", "is_correct": false, "explanation": "蚕育（cányù）第二个音节声调不同（yù 第四声），意思是养育、培育，与残余无关。"}, {"text": "参与", "is_correct": false, "explanation": "参与（cānyǔ）两个音节的声调都不同，意思是参加，与残余（cán yú）声调不同。"}, {"text": "藏于", "is_correct": false, "explanation": "藏于（cángyú）与 cányú 的韵母不同（-ang 与 -an），意思是隐藏在某处。"}], "explanations": {"残余": "正确答案。残余（cán yú）指用过、吃过之后剩下的东西。", "蚕育": "蚕育（cányù）第二个音节声调不同（yù 第四声），意思是养育、培育，与残余无关。", "参与": "参与（cānyǔ）两个音节的声调都不同，意思是参加，与残余（cán yú）声调不同。", "藏于": "藏于（cángyú）与 cányú 的韵母不同（-ang 与 -an），意思是隐藏在某处。"}, "sentence_index": null, "correct_answer": "残余"}, "level_3": {"options": [{"text": "残余", "is_correct": true, "explanation": "残余指用过、吃过之后剩下的东西，与“盘子里”“倒进了垃圾桶”相合。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星不可能在盘子里，也不会被倒进垃圾桶，句中语境不合。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是盘子里的东西，也不能倒进垃圾桶，句中语境不合。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“倒进”的对象应是可以盛倒的东西，“窗户”不能与“倒进”搭配。"}], "explanations": {"残余": "残余指用过、吃过之后剩下的东西，与“盘子里”“倒进了垃圾桶”相合。", "星星": "语义：星星不可能在盘子里，也不会被倒进垃圾桶，句中语境不合。", "歌曲": "语义：歌曲不是盘子里的东西，也不能倒进垃圾桶，句中语境不合。", "窗户": "搭配：“倒进”的对象应是可以盛倒的东西，“窗户”不能与“倒进”搭配。"}, "sentence_index": 0, "correct_answer": "残余"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天残余三个小时看电视。", "explanation": "这里应该用〈花〉。残余是名词，不能当动词表示“花费”。"}, {"text": "他很残余，大家都不喜欢他。", "explanation": "残余是名词，不能用来形容人；这里应该用形容词，如〈自私〉。"}, {"text": "他残余地走进了房间。", "explanation": "残余是名词，不能加“地”作状语修饰动作；这里应该用〈悄悄〉之类的副词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21156, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残余", "is_correct": true, "explanation": "残余指油被处理后剩下的部分，与“河水里有一些油的”相合。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：河水里不会有“油的诗歌”这样的东西，句中语境不合。"}, {"text": "月光", "is_correct": false, "explanation": "语义：月光不能沾油，也不能说“一些油的月光”，与河水的语境不合。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“一些油的”一般修饰残余、油滴等，“窗帘”与河水的语境不搭配。"}], "explanations": {"残余": "残余指油被处理后剩下的部分，与“河水里有一些油的”相合。", "诗歌": "语义：河水里不会有“油的诗歌”这样的东西，句中语境不合。", "月光": "语义：月光不能沾油，也不能说“一些油的月光”，与河水的语境不合。", "窗帘": "搭配：“一些油的”一般修饰残余、油滴等，“窗帘”与河水的语境不搭配。"}, "sentence_index": 6, "correct_answer": "残余"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个残余的老师教得很好。", "explanation": "残余是名词，不能用来修饰指人的“老师”；这里应该用形容词，如〈优秀〉。"}, {"text": "我昨晚残余到十二点才睡。", "explanation": "这里应该用〈熬〉。残余是名词，不能当动词用。"}, {"text": "用十七除以五，商是三，残余了二。", "explanation": "这里应该用〈余〉。残余是名词，不能当动词用，除不尽的部分应说“余二”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那残余我都扔了。", "corrected_sentence": "那些残余我都扔了。", "error_description": "量词缺失：指示代词“那”后面要带量词，残余是物质，应说“那些残余”，不能说“那残余”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "锅底还有一些残余们，用水冲掉就行。", "corrected_sentence": "锅底还有一些残余，用水冲掉就行。", "error_description": "后缀错误：“们”只用于指人的名词，残余是物质，不能加“们”，正确的说法是“一些残余”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21158, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理性", "is_correct": true, "explanation": "反义：理性与动物性相对，指理智而非本能。"}, {"text": "石头", "is_correct": false, "explanation": "石头是矿物，与动物性没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流是自然景物，与动物性没有反义关系。"}, {"text": "书包", "is_correct": false, "explanation": "书包是日常用品，与动物性没有反义关系。"}], "correct_answer": "理性", "explanations": {"理性": "反义：理性与动物性相对，指理智而非本能。", "石头": "石头是矿物，与动物性没有反义关系。", "河流": "河流是自然景物，与动物性没有反义关系。", "书包": "书包是日常用品，与动物性没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21158, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理性", "is_correct": true, "explanation": "反义：理性与动物性相对，指理智而非本能。"}, {"text": "房屋", "is_correct": false, "explanation": "房屋是建筑物，与动物性没有反义关系。"}, {"text": "大海", "is_correct": false, "explanation": "大海是自然景物，与动物性没有语义上的对立关系。"}, {"text": "黑板", "is_correct": false, "explanation": "黑板是教学用具，与动物性没有反义关系。"}], "correct_answer": "理性", "explanations": {"理性": "反义：理性与动物性相对，指理智而非本能。", "房屋": "房屋是建筑物，与动物性没有反义关系。", "大海": "大海是自然景物，与动物性没有语义上的对立关系。", "黑板": "黑板是教学用具，与动物性没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21158, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指人和动物身体里像动物一样的本性，比如想吃饭、想玩。", "primary_collocate": null, "pronunciation": "dòng wù xìng", "ipa": "tʊŋ˥˩ u˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "想吃饭、想睡觉，都是动物性。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子爱玩，这是动物性。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人有动物性，也有想法。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一看到好吃的，动物性就出来了。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物性让我们饿了就想吃饭。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，人不能只有动物性。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩游戏的时候，他的动物性很明显。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，想玩是孩子的动物性。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她累了就想睡觉，这是动物性。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人和狗都有动物性。", "target_word": "动物性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "動物性", "label": "繁体"}, {"form": "动物性蛋白", "label": "复合"}], "register": "书面", "sense_fingerprint": "人和动物身体里像动物一样的本性，如想吃饭、想玩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67f2682a-e0a1-440d-a581-92febfcf3326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动物性", "is_correct": true, "explanation": "动物性指人和动物本能的需求，如吃饭、睡觉，与句意相符。"}, {"text": "理性", "is_correct": false, "explanation": "语义：理性指理智思考，与“想吃饭、想睡觉”这类本能需求不符。"}, {"text": "思想", "is_correct": false, "explanation": "语义：思想指意识活动，不是“想吃饭、想睡觉”这类本能。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：外貌指外表长相，与“想吃饭、想睡觉”这类需求无关。"}], "explanations": {"动物性": "动物性指人和动物本能的需求，如吃饭、睡觉，与句意相符。", "理性": "语义：理性指理智思考，与“想吃饭、想睡觉”这类本能需求不符。", "思想": "语义：思想指意识活动，不是“想吃饭、想睡觉”这类本能。", "外貌": "体貌：外貌指外表长相，与“想吃饭、想睡觉”这类需求无关。"}, "sentence_index": 0, "correct_answer": "动物性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的动物性很喜欢读书，一见到书就想看。", "explanation": "这里应该用〈爱好〉。动物性指本能需求，不指读书之类的兴趣爱好，应说“爱好”。"}, {"text": "孩子很动物性。", "explanation": "这里应该用〈天真〉。动物性指本能需求，不用来形容人的性格。"}, {"text": "他的动物性很勤奋地学习。", "explanation": "这里应该用〈努力〉。动物性指本能，不能用来形容学习的勤奋态度，应说“努力”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动物性", "is_correct": true, "explanation": "动物性指本能冲动，玩游戏时表现出的冲动符合句意。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学不能“很明显”地表现在玩游戏的行为中，与句意不符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户与玩游戏时的表现无关，不能“很明显”。"}, {"text": "形状", "is_correct": false, "explanation": "搭配：形状是外貌特征，不能用“很明显”来描述玩游戏时的行为。"}], "explanations": {"动物性": "动物性指本能冲动，玩游戏时表现出的冲动符合句意。", "数学": "语义：数学不能“很明显”地表现在玩游戏的行为中，与句意不符。", "窗户": "语义：窗户与玩游戏时的表现无关，不能“很明显”。", "形状": "搭配：形状是外貌特征，不能用“很明显”来描述玩游戏时的行为。"}, "sentence_index": 6, "correct_answer": "动物性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有丰富的动物性，所以写了很多论文。", "explanation": "这里应该用〈知识〉。动物性指本能，不指学问或知识，写论文靠的不是动物性。"}, {"text": "这个城市有悠久的动物性。", "explanation": "这里应该用〈文化〉。动物性不指历史传统，不能说“悠久”。"}, {"text": "他的动物性非常会讲故事。", "explanation": "这里应该用〈口才〉。动物性指本能，不指讲故事的能力，应说“口才好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "想玩是孩子动物性。", "corrected_sentence": "想玩是孩子的动物性。", "error_description": "错误：表示领属的名词修饰语“孩子”后漏掉了“的”。正确：应说“孩子的动物性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人有也动物性。", "corrected_sentence": "人也有动物性。", "error_description": "错误：副词“也”放错了位置。正确：应说“人也有动物性”，“也”放在主语后、动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
