INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21160, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "油和脂肪，可以吃，用来做菜不粘锅。", "primary_collocate": null, "pronunciation": "yóu zhī", "ipa": "joʊ˧˥ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "老式点心多用动物油脂，香味很浓。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "lǎo shì diǎn xin duō yòng dòng wù yóu zhī, xiāng wèi hěn nóng.", "sentence_source": "generated"}, {"text": "平底锅上涂一层油脂，蛋就不会粘底。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "píng dǐ guō shàng tú yì céng yóu zhī, dàn jiù bú huì zhān dǐ.", "sentence_source": "generated"}, {"text": "我们家做饭很少用动物油脂。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "wǒ men jiā zuò fàn hěn shǎo yòng dòng wù yóu zhī.", "sentence_source": "generated"}, {"text": "减肥的人要少吃油脂。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煎鱼用的油脂不能太少，否则鱼皮会粘锅。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "jiān yú yòng de yóu zhī bù néng tài shǎo, fǒu zé yú pí huì zhān guō.", "sentence_source": "generated"}, {"text": "这种食用油脂适合做中餐。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈先把热锅烧热，再倒入一点食用油脂。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "mā ma xiān bǎ rè guō shāo rè, zài dào rù yì diǎn shí yòng yóu zhī.", "sentence_source": "generated"}, {"text": "蛋糕里加了黄油这种油脂，味道很香。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师说，做这道红烧肉要用不少动物油脂。", "target_word": "油脂", "complexity_tier": "T3", "furigana": "chú shī shuō, zuò zhè dào hóng shāo ròu yào yòng bù shǎo dòng wù yóu zhī.", "sentence_source": "generated"}, {"text": "饭店的菜油脂太多，我吃不惯。", "target_word": "油脂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一点油脂", "label": "量词"}, {"form": "食用油脂", "label": "复合"}], "register": "中性", "sense_fingerprint": "做菜用的食用油和脂肪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67f2682a-e0a1-440d-a581-92febfcf3326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21160, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "油脂", "is_correct": true, "explanation": "正确答案。油脂（yóu zhī）指油和脂肪，可以用来做菜。"}, {"text": "优质", "is_correct": false, "explanation": "优质（yōuzhì）两个音节的声调都不同，意思是质量好，与油脂（yóuzhī）声调不同。"}, {"text": "油纸", "is_correct": false, "explanation": "油纸（yóuzhǐ）第二个音节声调不同（zhǐ 第三声），意思是涂了油的纸。"}, {"text": "有志", "is_correct": false, "explanation": "有志（yǒuzhì）两个音节的声调都不同，意思是有志向。"}], "explanations": {"油脂": "正确答案。油脂（yóu zhī）指油和脂肪，可以用来做菜。", "优质": "优质（yōuzhì）两个音节的声调都不同，意思是质量好，与油脂（yóuzhī）声调不同。", "油纸": "油纸（yóuzhǐ）第二个音节声调不同（zhǐ 第三声），意思是涂了油的纸。", "有志": "有志（yǒuzhì）两个音节的声调都不同，意思是有志向。"}, "sentence_index": null, "correct_answer": "油脂"}, "level_3": {"options": [{"text": "油脂", "is_correct": true, "explanation": "油脂指做点心用的食用油和脂肪，与“动物油脂”“香味很浓”相合。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不是动物的产物，“动物木头”与句意不合，点心也不用木头做。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不是动物的产物，点心里也不会用玻璃，句中语境不合。"}, {"text": "煤炭", "is_correct": false, "explanation": "搭配：做点心的原料要能食用，“煤炭”不能与“做点心”搭配，香味也不合。"}], "explanations": {"油脂": "油脂指做点心用的食用油和脂肪，与“动物油脂”“香味很浓”相合。", "木头": "语义：木头不是动物的产物，“动物木头”与句意不合，点心也不用木头做。", "玻璃": "语义：玻璃不是动物的产物，点心里也不会用玻璃，句中语境不合。", "煤炭": "搭配：做点心的原料要能食用，“煤炭”不能与“做点心”搭配，香味也不合。"}, "sentence_index": 0, "correct_answer": "油脂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆摩托车要加满油脂才能跑。", "explanation": "这里应该用〈汽油〉。油脂是食用的油和脂肪，给摩托车加的燃料要用汽油。"}, {"text": "汽车发动机要定期更换油脂。", "explanation": "这里应该用〈机油〉。油脂是食用的油和脂肪，发动机润滑要用机油。"}, {"text": "煤油炉要用油脂才能点着。", "explanation": "这里应该用〈煤油〉。煤油炉烧的是煤油，句中的油脂是可以吃的食用油脂，不能当炉子的燃料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "油脂", "is_correct": true, "explanation": "油脂指食用的油和脂肪，与“倒入一点食用”相合。"}, {"text": "油漆", "is_correct": false, "explanation": "语义：油漆不能食用，“食用油漆”与热锅的语境不合。"}, {"text": "肥皂", "is_correct": false, "explanation": "语义：肥皂不能食用，也不会倒进热锅里，句中语境不合。"}, {"text": "铁钉", "is_correct": false, "explanation": "搭配：“倒入一点”要求液体或颗粒，“铁钉”是固体，不能与“倒入”搭配。"}], "explanations": {"油脂": "油脂指食用的油和脂肪，与“倒入一点食用”相合。", "油漆": "语义：油漆不能食用，“食用油漆”与热锅的语境不合。", "肥皂": "语义：肥皂不能食用，也不会倒进热锅里，句中语境不合。", "铁钉": "搭配：“倒入一点”要求液体或颗粒，“铁钉”是固体，不能与“倒入”搭配。"}, "sentence_index": 6, "correct_answer": "油脂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一只油脂，准备炒菜。", "explanation": "量词错误：“只”多用于动物，油脂要用“点”或“勺”计量。"}, {"text": "我们正在给墙刷一层油脂，颜色很好看。", "explanation": "这里应该用〈油漆〉。油脂是可以吃的油和脂肪，刷墙要用油漆，不能用油脂。"}, {"text": "用油脂可以洗掉碗上的油污。", "explanation": "这里应该用〈洗洁精〉。油脂是可以吃的油和脂肪，本身就是油污的来源，洗掉碗上的油污要用洗洁精。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道菜的油脂太高，我吃不下。", "corrected_sentence": "这道菜的油脂含量太高，我吃不下。", "error_description": "搭配错误：说油脂的量多，要用“含量高”或“多”，“油脂太高”易被理解为油温太高。正确：“油脂含量太高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "锅里还剩一只油脂，别全倒掉。", "corrected_sentence": "锅里还剩一点油脂，别全倒掉。", "error_description": "量词错误：油脂是物质，不能用动物量词“只”计量，正确的说法是“一点油脂”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
