INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21162, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "没有空气时，一些很小的东西把食物变坏，产生气体。", "primary_collocate": null, "pronunciation": "yàn yǎng fā jiào", "ipa": "jɛn˥˩ jɑŋ˨˩˦ fa˥ tɕjɑʊ˥˩", "syllable_count": 4, "sentences": [{"text": "饭盒盖得太紧，里面会发生厌氧发酵。", "target_word": "厌氧发酵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "密封的罐头坏了，可能是厌氧发酵。", "target_word": "厌氧发酵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "剩菜放在袋子里太久，会有厌氧发酵。", "target_word": "厌氧发酵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "垃圾桶盖得很紧，里面容易出现厌氧发酵。", "target_word": "厌氧发酵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有空气，食物里就会有厌氧发酵。", "target_word": "厌氧发酵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厌氧发酵会让食物变臭，还会产生气体。", "target_word": "厌氧发酵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这罐泡菜鼓起来了，是厌氧发酵造成的。", "target_word": "厌氧发酵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，厌氧发酵不需要空气。", "target_word": "厌氧发酵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "袋子里没有空气，就会发生厌氧发酵。", "target_word": "厌氧发酵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厌氧发酵的气体有一股臭味。", "target_word": "厌氧发酵", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "厭氧發酵", "label": "繁体"}, {"form": "厌氧发酵罐", "label": "复合"}], "register": "中性", "sense_fingerprint": "没有空气时微生物使食物变坏并产生气体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f49f6dc-9e85-4217-b5c9-16c1472b39b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21162, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厌氧发酵", "is_correct": true, "explanation": "正确。句意是饭盒盖得太紧，里面会发生厌氧发酵。"}, {"text": "日食", "is_correct": false, "explanation": "语义：日食是天文现象，不会在饭盒里发生。"}, {"text": "体操", "is_correct": false, "explanation": "搭配：“发生”后接事件或现象，“体操”是体育活动，不能说“里面会发生体操”。"}, {"text": "交通事故", "is_correct": false, "explanation": "语义：交通事故与饭盒盖紧、食物内部的变化无关，句中指的是食物变化。"}], "explanations": {"厌氧发酵": "正确。句意是饭盒盖得太紧，里面会发生厌氧发酵。", "日食": "语义：日食是天文现象，不会在饭盒里发生。", "体操": "搭配：“发生”后接事件或现象，“体操”是体育活动，不能说“里面会发生体操”。", "交通事故": "语义：交通事故与饭盒盖紧、食物内部的变化无关，句中指的是食物变化。"}, "sentence_index": 0, "correct_answer": "厌氧发酵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件红衬衫洗多了会厌氧发酵。", "explanation": "这里应该用〈褪色〉。衬衫洗多了颜色变淡是染料脱落，厌氧发酵是微生物分解食物等有机物的过程，与染料无关。"}, {"text": "铁门放在潮湿的地方容易厌氧发酵。", "explanation": "这里应该用〈生锈〉。铁生锈是铁与氧气、水发生的氧化反应，厌氧发酵是微生物的分解过程，不能用于金属。"}, {"text": "学生们在教室里厌氧发酵，老师很生气。", "explanation": "这里应该用〈打闹〉。厌氧发酵是微生物分解食物的过程，不能用来指学生的行为，应该用“打闹”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21162, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厌氧发酵", "is_correct": true, "explanation": "正确。句意是泡菜鼓起来是厌氧发酵造成的。"}, {"text": "冷藏", "is_correct": false, "explanation": "语义：冷藏会抑制微生物繁殖，不会使泡菜鼓起来，与句中“造成鼓起”的因果不符。"}, {"text": "广告", "is_correct": false, "explanation": "语义：广告不会使泡菜鼓起来，与句中的发酵变化无关。"}, {"text": "节日", "is_correct": false, "explanation": "搭配：“造成”的主语应是引发变化的原因，“节日”不能使泡菜鼓起来，搭配不当。"}], "explanations": {"厌氧发酵": "正确。句意是泡菜鼓起来是厌氧发酵造成的。", "冷藏": "语义：冷藏会抑制微生物繁殖，不会使泡菜鼓起来，与句中“造成鼓起”的因果不符。", "广告": "语义：广告不会使泡菜鼓起来，与句中的发酵变化无关。", "节日": "搭配：“造成”的主语应是引发变化的原因，“节日”不能使泡菜鼓起来，搭配不当。"}, "sentence_index": 6, "correct_answer": "厌氧发酵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "湖水在夏天会厌氧发酵。", "explanation": "这里应该用〈蒸发〉。水在高温下变成水汽是物理变化，厌氧发酵是微生物分解有机物的过程，不能用来描述湖水。"}, {"text": "池塘的水冬天会厌氧发酵。", "explanation": "这里应该用〈结冰〉。水遇冷变成冰是物态变化，厌氧发酵与池塘结冰无关。"}, {"text": "酒精放在桌上会厌氧发酵。", "explanation": "这里应该用〈挥发〉。酒精在常温下会挥发，这是物理变化；厌氧发酵是微生物分解有机物的过程，不指液体蒸发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "饭盒盖得太紧，这条厌氧发酵很快就开始了。", "corrected_sentence": "饭盒盖得太紧，这次厌氧发酵很快就开始了。", "error_description": "量词错误：“厌氧发酵”是过程，应用“次”，不能用“条”。正确说法是“这次厌氧发酵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "食物放在袋子里，很厌氧发酵，产生气体。", "corrected_sentence": "食物放在袋子里，会发生厌氧发酵，产生气体。", "error_description": "错误形式：“很厌氧发酵”；正确形式：“会厌氧发酵”或“会发生厌氧发酵”。“很”是程度副词，不能修饰“厌氧发酵”这样的动词性词语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21164, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "防止", "is_correct": true, "explanation": "防止与引致意思相反：一个是让事情发生，一个是不让事情发生。"}, {"text": "观察", "is_correct": false, "explanation": "观察与引致没有反义关系，二者意思无关。"}, {"text": "搬运", "is_correct": false, "explanation": "搬运与引致没有反义关系，二者意思无关。"}, {"text": "讲述", "is_correct": false, "explanation": "讲述与引致没有反义关系，二者意思无关。"}], "correct_answer": "防止", "explanations": {"防止": "防止与引致意思相反：一个是让事情发生，一个是不让事情发生。", "观察": "观察与引致没有反义关系，二者意思无关。", "搬运": "搬运与引致没有反义关系，二者意思无关。", "讲述": "讲述与引致没有反义关系，二者意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
