INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21164, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让一件事发生。", "primary_collocate": null, "pronunciation": "yǐn zhì", "ipa": "in˨˩˦ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "小事不处理好，会引致大麻烦。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机开车太快，引致了这次事故。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的粗心引致了比赛失败。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过度节食可能引致身体变差。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的看法引致了一场争论。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电线老化引致房子起火。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个决定引致了很多问题。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一句玩笑话引致了她的误会。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恶劣天气引致航班大量延误。", "target_word": "引致", "complexity_tier": "T3", "furigana": "yǐn zhì", "sentence_source": "generated"}, {"text": "价格上涨引致销量下降。", "target_word": "引致", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "引致了", "label": "体标"}, {"form": "引致着", "label": "体标"}], "register": "书面", "sense_fingerprint": "某件事使另一件事随之发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '67f2682a-e0a1-440d-a581-92febfcf3326') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21164, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "引致", "is_correct": true, "explanation": "引致（yǐn zhì）是本词，表示让一件事发生。"}, {"text": "印制", "is_correct": false, "explanation": "印制（yìn zhì）与引致（yǐn zhì）第一个音节声调不同，意思是印刷、制作。"}, {"text": "银制", "is_correct": false, "explanation": "银制（yín zhì）与引致（yǐn zhì）第一个音节声调不同，意思是用银制成。"}, {"text": "音质", "is_correct": false, "explanation": "音质（yīn zhì）与引致（yǐn zhì）第一个音节声调不同，意思是声音的质量。"}], "explanations": {"引致": "引致（yǐn zhì）是本词，表示让一件事发生。", "印制": "印制（yìn zhì）与引致（yǐn zhì）第一个音节声调不同，意思是印刷、制作。", "银制": "银制（yín zhì）与引致（yǐn zhì）第一个音节声调不同，意思是用银制成。", "音质": "音质（yīn zhì）与引致（yǐn zhì）第一个音节声调不同，意思是声音的质量。"}, "sentence_index": null, "correct_answer": "引致"}, "level_3": {"options": [{"text": "引致", "is_correct": true, "explanation": "引致：某件事使麻烦随之发生，符合句意。"}, {"text": "购买", "is_correct": false, "explanation": "语义：“购买”的对象是物品，不能说购买麻烦。"}, {"text": "提高", "is_correct": false, "explanation": "搭配：“提高”用于水平、效率，不能用于麻烦。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”的对象不能是麻烦，这句话语义不通。"}], "explanations": {"引致": "引致：某件事使麻烦随之发生，符合句意。", "购买": "语义：“购买”的对象是物品，不能说购买麻烦。", "提高": "搭配：“提高”用于水平、效率，不能用于麻烦。", "欣赏": "语义：“欣赏”的对象不能是麻烦，这句话语义不通。"}, "sentence_index": 0, "correct_answer": "引致"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他引致了一种新机器。", "explanation": "这里应该用〈发明〉。引致表示让某件事发生，不用于制造新机器。"}, {"text": "公司引致了一套新设备。", "explanation": "这里应该用〈引入〉。引致表示让某件事发生，不用于引进新的设备。"}, {"text": "坏人引致了那个孩子。", "explanation": "这里应该用〈引诱〉。引致不用于人与人之间的诱骗，要说引诱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引致", "is_correct": true, "explanation": "引致：某个决定使很多问题随之发生，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象不能是问题，这句话语义不通。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”针对场所、展览，不能用于问题。"}, {"text": "毕业", "is_correct": false, "explanation": "配价：“毕业”是不及物动词，后面不能带“问题”作宾语。"}], "explanations": {"引致": "引致：某个决定使很多问题随之发生，符合句意。", "吃": "语义：“吃”的对象不能是问题，这句话语义不通。", "参观": "语义：“参观”针对场所、展览，不能用于问题。", "毕业": "配价：“毕业”是不及物动词，后面不能带“问题”作宾语。"}, "sentence_index": 6, "correct_answer": "引致"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司引致了新员工。", "explanation": "这里应该用〈招聘〉。引致表示让某件事发生，不用于录用人员。"}, {"text": "学校引致了很多人才。", "explanation": "这里应该用〈培养〉。引致表示让某件事发生，不用于培育人才。"}, {"text": "老板引致了一项任务。", "explanation": "这里应该用〈分配〉。引致不用于派发任务，要说分配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "司机疲劳驾驶，引致着这次事故。", "corrected_sentence": "司机疲劳驾驶，引致了这次事故。", "error_description": "“引致”指已经发生的事件，应用“了”说“引致了”；“着”表示持续中的状态，“引致着这次事故”不符合事件已发生的说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个计划引致着了很多误会。", "corrected_sentence": "这个计划引致了很多误会。", "error_description": "体标错误：“引致”后的“着”与“了”不能同时使用，只保留“了”。正确：“这个计划引致了很多误会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
