INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21166, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "果皮是水果外面那层可以剥掉或吃掉的皮。", "primary_collocate": null, "pronunciation": "guǒ pí", "ipa": "kuo˨˩˦ pʰi˧˥", "syllable_count": 2, "sentences": [{"text": "他吃完苹果，把果皮放进了垃圾桶。", "target_word": "果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果的果皮很薄。", "target_word": "果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "果皮上有一点脏东西，先洗一洗。", "target_word": "果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有一块果皮，小心别滑倒。", "target_word": "果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "橙子的果皮可以用来泡茶。", "target_word": "果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢吃葡萄的果皮。", "target_word": "果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟把香蕉的果皮扔在了地上。", "target_word": "果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个西瓜的果皮是绿色的。", "target_word": "果皮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把果皮晒干，收在罐子里。", "target_word": "果皮", "complexity_tier": "T3", "furigana": "mā ma bǎ guǒ pí shài gān, shōu zài guàn zi lǐ.", "sentence_source": "generated"}, {"text": "果皮太厚，剥起来很慢。", "target_word": "果皮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块果皮", "label": "量词"}, {"form": "一片果皮", "label": "量词"}], "register": "中性", "sense_fingerprint": "水果外面的一层皮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be5ee50c-f9af-43f9-b71d-60fc13a41298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21166, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "果园", "is_correct": false, "explanation": "语义：果园是种果树的地方，不能被“放进垃圾桶”。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不是可以扔进垃圾桶的东西。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：“放进”多用于固体，液体一般说“倒进”，不说“放进垃圾桶”。"}, {"text": "果皮", "is_correct": true, "explanation": "正确：果皮是吃完水果后要扔掉的外皮，可以放进垃圾桶。"}], "explanations": {"果园": "语义：果园是种果树的地方，不能被“放进垃圾桶”。", "厨房": "语义：厨房是房间，不是可以扔进垃圾桶的东西。", "牛奶": "搭配：“放进”多用于固体，液体一般说“倒进”，不说“放进垃圾桶”。", "果皮": "正确：果皮是吃完水果后要扔掉的外皮，可以放进垃圾桶。"}, "sentence_index": 0, "correct_answer": "果皮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头的果皮很粗糙，上面有很多纹路。", "explanation": "这里应该用〈表面〉。果皮只指水果外面可剥掉的皮，石头的外层不说“果皮”。"}, {"text": "这个鸡蛋的果皮很薄，一碰就碎。", "explanation": "这里应该用〈蛋壳〉。果皮指水果外面可剥掉的皮，鸡蛋的外壳要说“蛋壳”。"}, {"text": "地上有一只果皮，小心别滑倒。", "explanation": "这里应该用〈块〉或〈片〉。“只”一般用于动物等，果皮要用“块”或“片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：价格是抽象的数值，不是实物，不能“扔在地上”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的属性，不能被扔在地上。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音无形，不能被扔在地上。"}, {"text": "果皮", "is_correct": true, "explanation": "正确：果皮是香蕉的外皮，弟弟扔的正是这个。"}], "explanations": {"价格": "语义：价格是抽象的数值，不是实物，不能“扔在地上”。", "颜色": "语义：颜色是事物的属性，不能被扔在地上。", "声音": "语义：声音无形，不能被扔在地上。", "果皮": "正确：果皮是香蕉的外皮，弟弟扔的正是这个。"}, "sentence_index": 6, "correct_answer": "果皮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的果皮很粗糙，脸上还有很多皱纹。", "explanation": "这里说的是人的皮肤，应该用〈皮肤〉。果皮只指水果外面的皮，不能用来指人。"}, {"text": "这棵大树的果皮很厚，我们用手摸了摸。", "explanation": "这里说的是树的外皮，应该用〈树皮〉。果皮只指水果外面的皮。"}, {"text": "这本旧书的果皮脱落了，只剩下书页。", "explanation": "这里说的是书的封面，应该用〈书皮〉或〈封面〉。果皮只指水果外层的皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌上有一只橘子的果皮。", "corrected_sentence": "桌上有一片橘子的果皮。", "error_description": "量词错误：果皮是薄片状的，应该用量词“片”（一片果皮），“只”一般用于动物，不能用于果皮。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐把橘子的果皮晒了干。", "corrected_sentence": "姐姐把橘子的果皮晒干了。", "error_description": "补语位置错误：结果补语“干”应紧接动词“晒”，句末再用“了”，应说“晒干了”，不能说“晒了干”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
