INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21168, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西变多，比如小虫子变多。", "primary_collocate": null, "pronunciation": "zī shēng", "ipa": "tsɹ̩˥ ʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "下过雨以后，水边的蚊子滋生得很快。", "target_word": "滋生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气一热，菜叶上就滋生了小虫子。", "target_word": "滋生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "垃圾堆旁边滋生着成群的苍蝇。", "target_word": "滋生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米放在潮湿的地方，很快就滋生出小虫。", "target_word": "滋生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "池塘的水不流动，里面滋生了很多蚊子。", "target_word": "滋生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天太冷，这些害虫很难滋生。", "target_word": "滋生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湿热的环境里，各种细菌迅速滋生。", "target_word": "滋生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家的厨房很脏，老鼠和蟑螂不停地滋生。", "target_word": "滋生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里杂草滋生，需要马上拔掉。", "target_word": "滋生", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "木头发霉后，上面滋生了白色的霉菌。", "target_word": "滋生", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "滋生了", "label": "体标（了）"}, {"form": "滋生着", "label": "体标（着）"}], "register": "书面", "sense_fingerprint": "小虫、细菌、杂草等数量变多（作不及物用法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026057aa-5864-49c0-96de-f25d5ea2ff13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21168, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "滋生", "is_correct": true, "explanation": "正确答案。滋生（zī shēng）指东西变多、数量增加。"}, {"text": "资深", "is_correct": false, "explanation": "资深（zī shēn）与滋生的韵母不同：shēng 为后鼻音 ng，shēn 为前鼻音 n，意思是资历深。"}, {"text": "私生", "is_correct": false, "explanation": "私生（sī shēng）与滋生的声母不同：s 与 z，意思是私人的生活，如“私生活”。"}, {"text": "自生", "is_correct": false, "explanation": "自生（zì shēng）第一个音节声调不同：zì 为第四声，zī 为第一声，意思是自己生长。"}, {"text": "吱声", "is_correct": false, "explanation": "吱声（zhī shēng）与滋生的声母不同：zh 与 z，意思是发出声音、作声。"}], "explanations": {"滋生": "正确答案。滋生（zī shēng）指东西变多、数量增加。", "资深": "资深（zī shēn）与滋生的韵母不同：shēng 为后鼻音 ng，shēn 为前鼻音 n，意思是资历深。", "私生": "私生（sī shēng）与滋生的声母不同：s 与 z，意思是私人的生活，如“私生活”。", "自生": "自生（zì shēng）第一个音节声调不同：zì 为第四声，zī 为第一声，意思是自己生长。", "吱声": "吱声（zhī shēng）与滋生的声母不同：zh 与 z，意思是发出声音、作声。"}, "sentence_index": null, "correct_answer": "滋生"}, "level_3": {"options": [{"text": "滋生", "is_correct": true, "explanation": "正确答案。“滋生”指数量变多，与“下过雨以后”的情境一致。"}, {"text": "蒸发", "is_correct": false, "explanation": "语义：“蒸发”指液体变为气体，蚊子不能“蒸发”，与句意不合。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：“冻结”需要低温，蚊子不能被冻结，与“下过雨以后”的情境不合。"}, {"text": "清理", "is_correct": false, "explanation": "配价：“清理”需带受事（如垃圾），句中没有可清理的对象，蚊子也不能作其施事。"}], "explanations": {"滋生": "正确答案。“滋生”指数量变多，与“下过雨以后”的情境一致。", "蒸发": "语义：“蒸发”指液体变为气体，蚊子不能“蒸发”，与句意不合。", "冻结": "语义：“冻结”需要低温，蚊子不能被冻结，与“下过雨以后”的情境不合。", "清理": "配价：“清理”需带受事（如垃圾），句中没有可清理的对象，蚊子也不能作其施事。"}, "sentence_index": 0, "correct_answer": "滋生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片田里滋生了很多庄稼。", "explanation": "这里应该用〈长出〉。滋生多指细菌、害虫繁殖或不良情况出现，庄稼不用滋生。"}, {"text": "这个孩子在家里滋生得很快。", "explanation": "这里应该用〈长〉。滋生用于生物繁殖或不良情况，不用于人的生长。"}, {"text": "这个方案滋生了很多好处。", "explanation": "这里应该用〈带来〉。滋生多指不良情况，不用于好处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21168, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滋生", "is_correct": true, "explanation": "正确答案。“滋生”指数量增多，与“湿热的环境里，各种细菌迅速”的语境一致。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：“冷却”指降温，与“湿热”的环境相反，细菌不会因此“冷却”。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：“结冰”需要低温，与“湿热的环境”矛盾。"}, {"text": "清扫", "is_correct": false, "explanation": "配价：“清扫”需带受事（如垃圾、地面），句中细菌不能作它的受事。"}], "explanations": {"滋生": "正确答案。“滋生”指数量增多，与“湿热的环境里，各种细菌迅速”的语境一致。", "冷却": "语义：“冷却”指降温，与“湿热”的环境相反，细菌不会因此“冷却”。", "结冰": "语义：“结冰”需要低温，与“湿热的环境”矛盾。", "清扫": "配价：“清扫”需带受事（如垃圾、地面），句中细菌不能作它的受事。"}, "sentence_index": 6, "correct_answer": "滋生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在黑板上滋生了一道题。", "explanation": "“出题”不是滋生的意思。滋生只用于生物繁殖或不良情况的出现，不用于出题。"}, {"text": "这家公司每年滋生了很多员工。", "explanation": "这里应该用〈招聘〉。员工是招来的，不会像虫子那样自行增多，滋生不用于人员的增加。"}, {"text": "这台机器滋生了很多零件。", "explanation": "这里应该用〈制造〉。零件是人工制造出来的，不是自行增多的，滋生不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21168, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "池塘里的蚊子滋生地很快。", "corrected_sentence": "池塘里的蚊子滋生得很快。", "error_description": "错误形式“滋生地很快”，正确形式“滋生得很快”。补语标志应用“得”，“地”用于状语，不能用于动词之后表示程度的补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21168, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋子里被滋生了很多蚊子。", "corrected_sentence": "屋子里滋生了很多蚊子。", "error_description": "错误形式“被滋生”，正确形式“滋生”。“滋生”是表示数量增多的不及物用法，不能用“被”字构成被动式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21170, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "一刀切", "is_correct": true, "explanation": "正确。“一刀切”指不分地方差异都用同一办法，与根据当地情况想办法相反。"}, {"text": "游泳", "is_correct": false, "explanation": "与因地制宜无关，不是反义词。"}, {"text": "跳舞", "is_correct": false, "explanation": "与因地制宜无关，不是反义词。"}, {"text": "散步", "is_correct": false, "explanation": "与因地制宜无关，不是反义词。"}], "correct_answer": "一刀切", "explanations": {"一刀切": "正确。“一刀切”指不分地方差异都用同一办法，与根据当地情况想办法相反。", "游泳": "与因地制宜无关，不是反义词。", "跳舞": "与因地制宜无关，不是反义词。", "散步": "与因地制宜无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21170, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "千篇一律", "is_correct": true, "explanation": "正确。“千篇一律”指所有事情都一个样、不分具体情况，与因地制宜相反。"}, {"text": "翻山越岭", "is_correct": false, "explanation": "与因地制宜无关，指越过山岭，不是反义词。"}, {"text": "雪中送炭", "is_correct": false, "explanation": "与因地制宜无关，指在别人急需时给予帮助，不是反义词。"}, {"text": "画蛇添足", "is_correct": false, "explanation": "与因地制宜无关，指多此一举，不是反义词。"}], "correct_answer": "千篇一律", "explanations": {"千篇一律": "正确。“千篇一律”指所有事情都一个样、不分具体情况，与因地制宜相反。", "翻山越岭": "与因地制宜无关，指越过山岭，不是反义词。", "雪中送炭": "与因地制宜无关，指在别人急需时给予帮助，不是反义词。", "画蛇添足": "与因地制宜无关，指多此一举，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21170, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "根据当地的情况，想出合适的办法。", "primary_collocate": null, "pronunciation": "yīn dì zhì yí", "ipa": "in˥ ti˥˩ ʈʂʐ̩˥˩ i˧˥", "syllable_count": 4, "sentences": [{"text": "海边风大，渔民因地制宜，把房子盖得很矮。", "target_word": "因地制宜", "complexity_tier": "T3", "furigana": "hǎi biān fēng dà， yú mín yīn dì zhì yí， bǎ fáng zi gài de hěn ǎi。", "sentence_source": "generated"}, {"text": "这里雨多，我们因地制宜，把屋顶修得很斜。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老农民因地制宜，在山坡上种了茶树。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个城市不同，处理垃圾应该因地制宜。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里缺水，当地人因地制宜，想了省水的办法。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能照搬外国经验，要因地制宜。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因地制宜，用旧木头做了一张桌子。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天特别冷的地方，取暖要因地制宜。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园因地制宜，把小山改成了儿童乐园。", "target_word": "因地制宜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因地制宜就是说，各地的办法应该不一样。", "target_word": "因地制宜", "complexity_tier": "T3", "furigana": "yīn dì zhì yí jiù shì shuō， gè dì de bàn fǎ yīng gāi bú yí yàng。", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "按当地情况想合适办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f49f6dc-9e85-4217-b5c9-16c1472b39b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因地制宜", "is_correct": true, "explanation": "正确。风大的海边，渔民根据当地情况，把房子盖矮，句意相符。"}, {"text": "打牌", "is_correct": false, "explanation": "语义：打牌与盖房子的做法没有关系，因果不通。"}, {"text": "讨价还价", "is_correct": false, "explanation": "语义：讨价还价指买卖时争论价格，与盖房子的做法无关。"}, {"text": "出海", "is_correct": false, "explanation": "语义：出海与“把房子盖得很矮”没有因果关系，因风大而盖矮房的逻辑不成立。"}], "explanations": {"因地制宜": "正确。风大的海边，渔民根据当地情况，把房子盖矮，句意相符。", "打牌": "语义：打牌与盖房子的做法没有关系，因果不通。", "讨价还价": "语义：讨价还价指买卖时争论价格，与盖房子的做法无关。", "出海": "语义：出海与“把房子盖得很矮”没有因果关系，因风大而盖矮房的逻辑不成立。"}, "sentence_index": 0, "correct_answer": "因地制宜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服是因地制宜做的，很合身。", "explanation": "这里应该用〈量体裁衣〉。因地制宜指根据当地情况想办法，按身材裁剪衣服要说“量体裁衣”。"}, {"text": "他没有经过同意，就因地制宜，擅自改了方案。", "explanation": "这里应该用〈自作主张〉。因地制宜指根据当地情况想办法，未经同意擅自改动要说“自作主张”。"}, {"text": "他在会上因地制宜，一开口就说个不停。", "explanation": "这里应该用〈滔滔不绝〉。因地制宜指根据当地情况想办法，说话不停要说“滔滔不绝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因地制宜", "is_correct": true, "explanation": "正确。用旧木头做桌子是就地取材，符合根据当地情况想办法，句意相符。"}, {"text": "挥霍", "is_correct": false, "explanation": "搭配：“挥霍”的对象是钱财等，不能说“挥霍，用旧木头做了一张桌子”。"}, {"text": "罢工", "is_correct": false, "explanation": "语义：罢工是停止工作，与“做了一张桌子”相矛盾。"}, {"text": "讲故事", "is_correct": false, "explanation": "语义：讲故事与做桌子无关，句子说不通。"}], "explanations": {"因地制宜": "正确。用旧木头做桌子是就地取材，符合根据当地情况想办法，句意相符。", "挥霍": "搭配：“挥霍”的对象是钱财等，不能说“挥霍，用旧木头做了一张桌子”。", "罢工": "语义：罢工是停止工作，与“做了一张桌子”相矛盾。", "讲故事": "语义：讲故事与做桌子无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "因地制宜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他趁人不注意，因地制宜，偷偷吃了一块蛋糕。", "explanation": "这里应该用〈偷吃〉。因地制宜指根据当地情况想办法，偷偷吃东西要说“偷吃”。"}, {"text": "他在比赛中因地制宜，故意撞倒了对手。", "explanation": "这里应该用〈犯规〉。因地制宜指根据当地情况想办法，故意撞人要说“犯规”。"}, {"text": "他因地制宜，把钱全都花光了。", "explanation": "这里应该用〈挥霍〉。因地制宜指根据当地情况想办法，把钱花光要说“挥霍”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老农民很因地制宜，想出适合本地的办法。", "corrected_sentence": "老农民要因地制宜，想出适合本地的办法。", "error_description": "程度副词“很”不能修饰“因地制宜”（动词性成语）。正确说法：老农民要因地制宜，想出适合本地的办法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "沙漠里水少，只有一个因地制宜，树才能活下来。", "corrected_sentence": "沙漠里水少，只有因地制宜，树才能活下来。", "error_description": "量词错误：“因地制宜”是动词性成语，不能直接加数量词“一个”。正确说法：沙漠里水少，只有因地制宜，树才能活下来。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
