INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21192, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "非常非常小的生物，用眼睛看不见。", "primary_collocate": null, "pronunciation": "wēi shēng wù", "ipa": "wei̯˥ ʂɤŋ˥ u˥˩", "syllable_count": 3, "sentences": [{"text": "微生物非常小，我们用眼睛看不见。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酸奶里有很多有用的微生物。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土地里住着很多微生物。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用显微镜看水里的微生物。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的微生物对人有好处，有的会让人生病。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食物放久了，上面会长出微生物。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "微生物让牛奶变成了酸奶。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗手可以洗掉手上的很多微生物。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海里也有微生物，它们小得看不见。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种微生物只在热水里生活。", "target_word": "微生物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "微生物学", "label": "复合"}], "register": "中性", "sense_fingerprint": "极小、肉眼看不见的生物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c5b1d1f-0031-45d5-a89b-428c11dec8c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微生物", "is_correct": true, "explanation": "“微生物”指极小的生物，符合“非常小、用眼睛看不见”的描述。"}, {"text": "大象", "is_correct": false, "explanation": "体貌：大象体型巨大，与句中“非常小”的描述相矛盾。"}, {"text": "高山", "is_correct": false, "explanation": "语义：高山体积庞大，与“用眼睛看不见”相矛盾。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：“小说”不是实体，不能说“用眼睛看不见”。"}], "explanations": {"微生物": "“微生物”指极小的生物，符合“非常小、用眼睛看不见”的描述。", "大象": "体貌：大象体型巨大，与句中“非常小”的描述相矛盾。", "高山": "语义：高山体积庞大，与“用眼睛看不见”相矛盾。", "小说": "搭配：“小说”不是实体，不能说“用眼睛看不见”。"}, "sentence_index": 0, "correct_answer": "微生物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜空中有很多微生物，一闪一闪的。", "explanation": "这里应该用〈星星〉。星星在夜空中一闪一闪地发光，“微生物”要用显微镜才能看见，不会在夜空中闪烁。"}, {"text": "她看着我，脸上带着微生物。", "explanation": "这里应该用〈微笑〉。脸上的表情要用“微笑”，“微生物”指极小的生物。"}, {"text": "这种微生物可以用来做玻璃。", "explanation": "这里应该用〈矿物〉。玻璃由矿物原料制成，微生物不能用来做玻璃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微生物", "is_correct": true, "explanation": "“微生物”能让牛奶发酵变成酸奶，符合句意。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油不能使牛奶发酵变成酸奶，句意不通。"}, {"text": "锤子", "is_correct": false, "explanation": "语义：锤子不能使牛奶发生这样的变化，句意不通。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“让”后的主语须能对牛奶施加作用，石头不能对牛奶施加这种作用。"}], "explanations": {"微生物": "“微生物”能让牛奶发酵变成酸奶，符合句意。", "汽油": "语义：汽油不能使牛奶发酵变成酸奶，句意不通。", "锤子": "语义：锤子不能使牛奶发生这样的变化，句意不通。", "石头": "配价：“让”后的主语须能对牛奶施加作用，石头不能对牛奶施加这种作用。"}, "sentence_index": 6, "correct_answer": "微生物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种微生物会叫，还会跑。", "explanation": "这里应该用〈动物〉。微生物极小，肉眼看不见，不会叫，也不会跑。"}, {"text": "这种微生物很硬，可以盖房子。", "explanation": "这里应该用〈岩石〉。岩石坚硬，可以盖房子；微生物没有这些特点。"}, {"text": "这种微生物很甜，孩子们都爱吃。", "explanation": "这里应该用〈水果〉。水果有甜味，可以吃；微生物肉眼看不见，不能当食物吃，这里不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只微生物，只能用显微镜看见。", "corrected_sentence": "这是一种微生物，只能用显微镜看见。", "error_description": "量词错误：“微生物”应使用量词“种”，“只”多用于动物，不能说“一只微生物”，应说“一种微生物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湖水里有很多微生物们。", "corrected_sentence": "湖水里有很多微生物。", "error_description": "“们”只用于指人的名词或代词之后，“微生物”不能加“们”，应说“很多微生物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22d97450-3653-4ba5-84e6-d64b3cc2ffe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21194, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失去", "is_correct": true, "explanation": "「失去」与「拥有」相反，指不再拥有某物。"}, {"text": "跑步", "is_correct": false, "explanation": "「跑步」指身体运动，与「拥有」没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "「写字」指书写活动，与「拥有」没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "「睡觉」指休息的动作，与「拥有」没有反义关系。"}], "correct_answer": "失去", "explanations": {"失去": "「失去」与「拥有」相反，指不再拥有某物。", "跑步": "「跑步」指身体运动，与「拥有」没有反义关系。", "写字": "「写字」指书写活动，与「拥有」没有反义关系。", "睡觉": "「睡觉」指休息的动作，与「拥有」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
