INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21194, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "有某样东西在自己这里。", "primary_collocate": null, "pronunciation": "yōng yǒu", "ipa": "yʊŋ˥ iou˨˩˦", "syllable_count": 2, "sentences": [{"text": "我拥有一本很旧的词典。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他现在拥有一辆新自行车。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明拥有很多玩具。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拥有一张去北京的票。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷拥有一块小小的地。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫拥有一个软软的小窝。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的钥匙只有他一个人拥有。", "target_word": "拥有", "complexity_tier": "T3", "furigana": "zhè jiā diàn de yào shi zhǐ yǒu tā yí gè rén yōng yǒu.", "sentence_source": "generated"}, {"text": "弟弟拥有一台旧电脑。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我拥有的东西不多。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拥有两个手机。", "target_word": "拥有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拥有了", "label": "体标"}, {"form": "拥有着", "label": "体标"}, {"form": "拥有过", "label": "体标"}], "register": "中性", "sense_fingerprint": "某样东西属于自己、在自己手里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d1a7d1-3aee-412f-b2bc-3fd1c3340546') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21194, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拥有", "is_correct": true, "explanation": "拥有（yōng yǒu）：有某样东西在自己这里，即本词条的读音与意思。"}, {"text": "应有", "is_correct": false, "explanation": "应有（yīng yǒu）与拥有（yōng yǒu）韵母不同：ing 与 ong，意思是「应该有的」。"}, {"text": "公有", "is_correct": false, "explanation": "公有（gōng yǒu）与拥有（yōng yǒu）声母不同：g 与 y，意思是共同所有。"}, {"text": "空有", "is_correct": false, "explanation": "空有（kōng yǒu）与拥有（yōng yǒu）声母不同：k 与 y，意思是徒有、白白有。"}], "explanations": {"拥有": "拥有（yōng yǒu）：有某样东西在自己这里，即本词条的读音与意思。", "应有": "应有（yīng yǒu）与拥有（yōng yǒu）韵母不同：ing 与 ong，意思是「应该有的」。", "公有": "公有（gōng yǒu）与拥有（yōng yǒu）声母不同：g 与 y，意思是共同所有。", "空有": "空有（kōng yǒu）与拥有（yōng yǒu）声母不同：k 与 y，意思是徒有、白白有。"}, "sentence_index": null, "correct_answer": "拥有"}, "level_3": {"options": [{"text": "拥有", "is_correct": true, "explanation": "「拥有」表示某物在自己手中，「一本很旧的词典」可以被领有，句子通顺。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能接词典作宾语，「吃一本很旧的词典」不成立。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」不能接词典作宾语，「喝一本很旧的词典」不成立。"}, {"text": "具备", "is_correct": false, "explanation": "语域：「具备」多用于能力、条件等抽象事物，不说「具备一本词典」。"}], "explanations": {"拥有": "「拥有」表示某物在自己手中，「一本很旧的词典」可以被领有，句子通顺。", "吃": "搭配：「吃」不能接词典作宾语，「吃一本很旧的词典」不成立。", "喝": "搭配：「喝」不能接词典作宾语，「喝一本很旧的词典」不成立。", "具备": "语域：「具备」多用于能力、条件等抽象事物，不说「具备一本词典」。"}, "sentence_index": 0, "correct_answer": "拥有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间里拥有一股奇怪的味道。", "explanation": "这里应该用〈存在〉。拥有表示领有，味道不是被人领有的东西，应说「存在」。"}, {"text": "全班同学都拥有他的建议。", "explanation": "这里应该用〈拥护〉。「拥有」表示领有，建议不能被领有，表示支持应说「拥护他的建议」。"}, {"text": "我拥有了一声巨响。", "explanation": "这里应该用〈听见〉。「拥有」表示领有，声音不能被领有，应说「听见一声巨响」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拥有", "is_correct": true, "explanation": "「只有他一个人拥有」表示只有他拥有这些钥匙，句子通顺。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」与钥匙没有关系，「只有他一个人唱这家店的钥匙」讲不通。"}, {"text": "切", "is_correct": false, "explanation": "搭配：「切」不能接钥匙作宾语，「切这家店的钥匙」不成立。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮」不能接钥匙作宾语，「煮这家店的钥匙」不成立。"}], "explanations": {"拥有": "「只有他一个人拥有」表示只有他拥有这些钥匙，句子通顺。", "唱": "语义：「唱」与钥匙没有关系，「只有他一个人唱这家店的钥匙」讲不通。", "切": "搭配：「切」不能接钥匙作宾语，「切这家店的钥匙」不成立。", "煮": "搭配：「煮」不能接钥匙作宾语，「煮这家店的钥匙」不成立。"}, "sentence_index": 6, "correct_answer": "拥有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们拥有了一次讨论。", "explanation": "这里应该用〈进行〉。讨论是活动，不能被领有，应说「进行一次讨论」。"}, {"text": "她拥有两场比赛。", "explanation": "这里应该用〈参加〉。比赛是活动，不能被领有，应说「参加两场比赛」。"}, {"text": "车站拥有了一件事。", "explanation": "这里应该用〈发生〉。事件是发生的，不能被车站领有，应说「车站发生了一件事」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很拥有两本词典。", "corrected_sentence": "我拥有两本词典。", "error_description": "错误在于「拥有」前多加了程度副词「很」。「很」不能修饰动词「拥有」，正确说法是「我拥有两本词典」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她拥有两只电脑。", "corrected_sentence": "她拥有两台电脑。", "error_description": "错误在于量词。「电脑」应用量词「台」，「只」多用于动物、成对的物件等，不能修饰「电脑」。正确说法是「她拥有两台电脑」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21196, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
