INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21196, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种很浓的液体，比水更稠。", "primary_collocate": null, "pronunciation": "nóng suō yè", "ipa": "noŋ˧˥ suɔ˥ jɛ˥˩", "syllable_count": 3, "sentences": [{"text": "这种浓缩液比水稠，倒得很慢。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶子里的浓缩液是深褐色的。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一点浓缩液倒进杯子里。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浓缩液很浓，喝之前要加水。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上那瓶浓缩液闻起来很甜。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，浓缩液会流到地上。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用浓缩液做了一杯橙汁。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这管浓缩液只要几块钱。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浓缩液像蜂蜜一样稠。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验室里有三瓶浓缩液。", "target_word": "浓缩液", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一瓶浓缩液", "label": "量词"}, {"form": "一管浓缩液", "label": "量词"}], "register": "中性", "sense_fingerprint": "很浓、比水更稠的液体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d1a7d1-3aee-412f-b2bc-3fd1c3340546') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21196, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浓缩液", "is_correct": true, "explanation": "正确：浓缩液比水稠，所以倒得很慢。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是气体，不存在比水稠的问题，也不能倒。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“倒”要求可以倾倒的液体或颗粒，“时间”不能被倒。"}, {"text": "铃声", "is_correct": false, "explanation": "语义：铃声是声音，没有稠稀之分，也不能倒。"}], "explanations": {"浓缩液": "正确：浓缩液比水稠，所以倒得很慢。", "空气": "语义：空气是气体，不存在比水稠的问题，也不能倒。", "时间": "搭配：“倒”要求可以倾倒的液体或颗粒，“时间”不能被倒。", "铃声": "语义：铃声是声音，没有稠稀之分，也不能倒。"}, "sentence_index": 0, "correct_answer": "浓缩液"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "爸爸买了一位浓缩液。", "explanation": "这里应该用〈瓶〉。〈位〉用于人，浓缩液是液体，应用〈瓶〉或〈管〉。"}, {"text": "这种浓缩液比水稀，倒得很快。", "explanation": "这里误把〈浓缩液〉当成比水稀薄的液体。浓缩液比水稠，应说〈稠〉。"}, {"text": "这瓶浓缩液硬邦邦的，可以用手拿。", "explanation": "这里误把〈浓缩液〉当成固体。浓缩液是液体，不能说“硬邦邦的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浓缩液", "is_correct": true, "explanation": "正确：妈妈用浓缩液调制了橙汁，浓缩液是可以用来做饮料的原料。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉不能用来调制橙汁。"}, {"text": "阳光", "is_correct": false, "explanation": "搭配：“用……做”要求具体的原料，“阳光”不能作为调制饮料的原料。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能用来做橙汁。"}], "explanations": {"浓缩液": "正确：妈妈用浓缩液调制了橙汁，浓缩液是可以用来做饮料的原料。", "面粉": "语义：面粉不能用来调制橙汁。", "阳光": "搭配：“用……做”要求具体的原料，“阳光”不能作为调制饮料的原料。", "石头": "语义：石头不能用来做橙汁。"}, "sentence_index": 6, "correct_answer": "浓缩液"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种浓缩液的浓度很低。", "explanation": "这里应该用〈溶液〉。浓缩液本身浓度很高，不能说“浓度很低”。"}, {"text": "实验室里有一朵浓缩液。", "explanation": "这里应该用〈瓶〉。〈朵〉用于花或云，浓缩液是液体，应用〈瓶〉或〈管〉。"}, {"text": "这种浓缩液没有黏性，倒出来像水一样。", "explanation": "这里误把〈浓缩液〉当成没有黏性的液体。浓缩液比水更稠，应说〈稠〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块浓缩液很稠。", "corrected_sentence": "这瓶浓缩液很稠。", "error_description": "错误：浓缩液是液体，量词应用“瓶”，“块”用于块状物。正确说法为“这瓶浓缩液很稠”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "桌上有两浓缩液。", "corrected_sentence": "桌上有两瓶浓缩液。", "error_description": "错误：浓缩液是液体，数量词与名词之间要加量词“瓶”，不能说“两浓缩液”。正确说法为“桌上有两瓶浓缩液”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
