INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21200, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "腐殖质是泥土里烂掉的树叶和草变成的东西，能让植物长得更好。", "primary_collocate": null, "pronunciation": "fǔ zhí zhì", "ipa": "fu˨˩˦ ʈʂɨ˧˥ ʈʂɨ˥˩", "syllable_count": 3, "sentences": [{"text": "地上的落叶烂了，就变成腐殖质。", "target_word": "腐殖质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "黑黑的泥土里有很多腐殖质。", "target_word": "腐殖质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷在花盆里放了一点腐殖质。", "target_word": "腐殖质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "草烂掉以后，会变成腐殖质。", "target_word": "腐殖质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有腐殖质的泥土很软，花也长得好。", "target_word": "腐殖质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明把烂树叶埋进土里，做成腐殖质。", "target_word": "腐殖质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这袋腐殖质是我从森林里拿来的。", "target_word": "腐殖质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花园里的腐殖质越多，植物长得越好。", "target_word": "腐殖质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，树下的腐殖质摸起来湿湿的。", "target_word": "腐殖质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在院子里挖了一层腐殖质，拿去种菜。", "target_word": "腐殖质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一层腐殖质", "label": "量词（层）"}, {"form": "一袋腐殖质", "label": "量词（袋）"}, {"form": "腐殖质层", "label": "复合"}], "register": "中性", "sense_fingerprint": "烂树叶、烂草在泥土里变成的东西，让植物长得好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026057aa-5864-49c0-96de-f25d5ea2ff13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21200, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "腐殖质", "is_correct": true, "explanation": "正确答案。落叶烂了以后变成的是腐殖质，与句意一致。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：落叶烂掉后变成的是腐殖质，不会变回树叶，与句意不合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：落叶不会变成石头，与“烂了”的情境不合。"}, {"text": "颜料", "is_correct": false, "explanation": "搭配：“变成”后的结果应是落叶腐烂的产物，“颜料”与此不搭。"}], "explanations": {"腐殖质": "正确答案。落叶烂了以后变成的是腐殖质，与句意一致。", "树叶": "语义：落叶烂掉后变成的是腐殖质，不会变回树叶，与句意不合。", "石头": "语义：落叶不会变成石头，与“烂了”的情境不合。", "颜料": "搭配：“变成”后的结果应是落叶腐烂的产物，“颜料”与此不搭。"}, "sentence_index": 0, "correct_answer": "腐殖质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿斧头劈了腐殖质。", "explanation": "这里应该用〈木头〉。劈用于木材等硬物，腐殖质是松散的泥土物质，不能用斧头劈。"}, {"text": "他把腐殖质用来盖房子。", "explanation": "这里应该用〈砖〉。砖是盖房子的材料，腐殖质是泥土里的物质，不能作建筑材料。"}, {"text": "腐殖质在地上长得很高。", "explanation": "这里应该用〈草〉。腐殖质是物质，不能“长得很高”，这只用于植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21200, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "腐殖质", "is_correct": true, "explanation": "正确答案。“这袋腐殖质”指装在袋中的土壤有机物，与“从森林里拿来”相符。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：水泥是建材，不会从森林里拿来，与句意不合。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉是食材，不会从森林里拿来，与句意不合。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：量词“袋”不搭配“手机”，应用“部”或“个”。"}], "explanations": {"腐殖质": "正确答案。“这袋腐殖质”指装在袋中的土壤有机物，与“从森林里拿来”相符。", "水泥": "语义：水泥是建材，不会从森林里拿来，与句意不合。", "面粉": "语义：面粉是食材，不会从森林里拿来，与句意不合。", "手机": "搭配：量词“袋”不搭配“手机”，应用“部”或“个”。"}, "sentence_index": 6, "correct_answer": "腐殖质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里的腐殖质开花了。", "explanation": "这里应该用〈植物〉。开花是植物才有的特征，腐殖质是土壤中的物质，不会开花。"}, {"text": "我每天早上喝一杯腐殖质。", "explanation": "这里应该用〈牛奶〉。腐殖质是土壤中的物质，不能喝。"}, {"text": "腐殖质在树上唱歌。", "explanation": "这里应该用〈小鸟〉。腐殖质是物质，不会唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在花盆里铺了一根腐殖质，花长得更好了。", "corrected_sentence": "妈妈在花盆里铺了一层腐殖质，花长得更好了。", "error_description": "错误形式“一根腐殖质”，正确形式“一层腐殖质”。“根”用于细长的东西，腐殖质是松散的物质，应用“层”“袋”“堆”等量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在花盆里放了一个腐殖质。", "corrected_sentence": "我们在花盆里放了一袋腐殖质。", "error_description": "错误形式“一个腐殖质”，正确形式“一袋腐殖质”。“个”用于独立的个体事物，腐殖质是松散的物质，应用“袋”“层”“堆”等量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21204, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆解", "is_correct": true, "explanation": "正确：“拆解”与“构建”相反，指把整体拆开。"}, {"text": "维护", "is_correct": false, "explanation": "与“构建”没有反义关系，“维护”指保持完好。"}, {"text": "设计", "is_correct": false, "explanation": "与“构建”没有反义关系，“设计”指事先规划。"}, {"text": "观察", "is_correct": false, "explanation": "与“构建”没有反义关系，“观察”指仔细地看。"}], "correct_answer": "拆解", "explanations": {"拆解": "正确：“拆解”与“构建”相反，指把整体拆开。", "维护": "与“构建”没有反义关系，“维护”指保持完好。", "设计": "与“构建”没有反义关系，“设计”指事先规划。", "观察": "与“构建”没有反义关系，“观察”指仔细地看。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
